async run(input, output, options = {}) {
    const G = this;
    G.input = input;
    G.output = output;
    // rawInput reads the next line without triggering a step boundary in the recorder.
    // Callers that record sessions can pass options.rawInput as an untracked reader.
    // Defaults to G.input so yesno still works when rawInput isn't provided.
    G.rawInput = options.rawInput || input;

    // Initialize RNG — use fixed seed if set, otherwise date/time like Fortran
    if (G._rngSeed !== undefined) {
      dungeonSrand(G._rngSeed);
    } else {
      const now = new Date();
      const i = now.getMonth() * 64 + now.getDate() * 8 + Math.floor(now.getFullYear() / 100);
      const j = now.getHours() * 64 + now.getMinutes() * 8 + now.getSeconds();
      dungeonSrand(((j << 16) + i) | 1);
    }

    if (options.restored) {
      // Restored from save — describe current location
      G.output('Saved game restored.');
      rmdesc(G, 3);
    } else {
      // Welcome message
      rspeak(G, 1);

      // Describe starting location
      rmdesc(G, 3);
    }

    // Main game loop
    while (!G.gameOver) {
      G.winner = PLAYER;
      G.telflg = false;

      // Read command if needed
      if (G.prscon <= 1) {
        const result = await rdline(G, 1);
        if (result === null) {
          // EOF — quit
          break;
        }
      }

      // Check for GDT (debugging tool) — skip in JS port
      // In Fortran: if inbuf starts with 'GDT', call GDT.
      // We skip this.

      G.moves++;
      G.sublnt = 0;
      const prvher = G.here;
      const prvlit = lit(G, G.here);

      // Parse input
      G.prswon = parse(G, G.inbuf, G.inlnt, true);
      if (G._trace) console.error(`GAME: move=${G.moves} here=${G.here} prsa=${G.prsa} prso=${G.prso} prsi=${G.prsi} prswon=${G.prswon}`);

      if (!G.prswon) {
        // Parse failed
        xendmv(G);
        if (!lit(G, G.here)) G.prscon = 1;
        continue;
      }

      // Check for actor action
      if (aappli(G, G.aactio[G.winner - 1])) {
        xendmv(G);
        if (!lit(G, G.here)) G.prscon = 1;
        continue;
      }

      // Check for vehicle action
      if (xvehic(G, 1)) {
        xendmv(G);
        if (!lit(G, G.here)) G.prscon = 1;
        continue;
      }

      // TELL command
      if (G.prsa === TELLW) {
        await handleTell(G);
        xendmv(G);
        if (!lit(G, G.here)) G.prscon = 1;
        continue;
      }

      // Collective objects (valuables, everything, possessions, bunch)
      if (G.prso === VALUA || G.prso === EVERY || G.prso === POSSE || G.prso === BUNOBJ) {
        valuac(G, G.prso);
        // After valuac, fall through to echo room check then room action
        while (!(G.echof || G.deadf) && G.here === ECHOR) {
          const echoExit = await handleEchoRoom(G);
          if (!echoExit) break;
          if (G.prso === VALUA || G.prso === EVERY || G.prso === POSSE || G.prso === BUNOBJ) {
            valuac(G, G.prso);
          } else {
            vappli(G, G.prsa);
          }
        }
        rappli(G, G.ractio[G.here - 1]);
        xendmv(G);
        if (!lit(G, G.here)) G.prscon = 1;
        continue;
      }

      // QUITW needs async yesno — handle before synchronous vappli
      if (G.prsa === QUITW) {
        score(G, true);
        if (await yesno(G, 343, 10, 0)) {
          G.gameOver = true;
          break;
        }
        xendmv(G);
        if (!lit(G, G.here)) G.prscon = 1;
        continue;
      }

      // Verb action
      if (!vappli(G, G.prsa)) {
        // Verb handler didn't handle it — fall through
        xendmv(G);
        if (!lit(G, G.here)) G.prscon = 1;
        continue;
      }

      // Check if room became lit
      if (!prvlit && G.here === prvher && lit(G, G.here)) {
        rmdesc(G, 0);
      }

      // Echo room special handling — Fortran GO TO 1000/300 loop
      // When a valid exit is found in the echo room, we must process
      // the walk (GO TO 300 in Fortran), then check echo room again.
      while (!(G.echof || G.deadf) && G.here === ECHOR) {
        const echoExit = await handleEchoRoom(G);
        if (!echoExit) break; // "echo" typed or no valid exit — done
        // Valid exit found — process the walk (Fortran label 300)
        if (G.prso === VALUA || G.prso === EVERY || G.prso === POSSE || G.prso === BUNOBJ) {
          valuac(G, G.prso);
        } else {
          vappli(G, G.prsa);
        }
        // Check if still in echo room (loop continues if so)
      }

      // Room action
      rappli(G, G.ractio[G.here - 1]);

      // End of move
      xendmv(G);
      if (!lit(G, G.here)) G.prscon = 1;
    }
  }

