function thiefp(G, arg) {
  if (G.prsa === FIGHTW) {
    if (G.ocan[STILL - 1] === THIEF) return false; // got stiletto
    if (qhere(G, STILL, G.thfpos)) {
      newsta(G, STILL, 0, 0, THIEF, 0); // recover
      if (qhere(G, THIEF, G.here)) rspeak(G, 499);
      return true;
    }
    newsta(G, THIEF, 0, 0, 0, 0); // vanish
    if (qhere(G, THIEF, G.here)) rspeak(G, 498);
    return true;
  }

  if (G.prsa === DEADXW) {
    G.thfact = false;
    if (G.here === TREAS) {
      let j = 501;
      for (let i = 1; i <= G.olnt; i++) {
        if (i === CHALI || i === THIEF || !qhere(G, i, G.here)) continue;
        G.oflag1[i - 1] |= VISIBT;
        rspsub(G, j, G.odesc2[i - 1]);
        j = 502;
        if (!qempty(G, i) &&
            ((G.oflag1[i - 1] & TRANBT) !== 0 || (G.oflag2[i - 1] & OPENBT) !== 0)) {
          princo(G, i, 573, true);
        }
      }
    }
    // drop anything thief is carrying
    let j = 500;
    for (let i = 1; i <= G.olnt; i++) {
      if (G.oadv[i - 1] !== -THIEF) continue;
      newsta(G, i, 0, G.here, 0, 0);
      rspsub(G, j, G.odesc2[i - 1]);
      j = 502;
      if (!qempty(G, i) &&
          ((G.oflag1[i - 1] & TRANBT) !== 0 || (G.oflag2[i - 1] & OPENBT) !== 0)) {
        princo(G, i, 573, true);
      }
    }
    return true;
  }

  if (G.prsa === FRSTQW) {
    return prob(G, 20, 75);
  }

  if (G.prsa === HELLOW && G.ocapac[THIEF - 1] < 0) {
    rspeak(G, 626);
    return true;
  }

  if (G.prsa === OUTXW) {
    G.thfact = false;
    G.odesc1[THIEF - 1] = 504;
    G.oflag1[STILL - 1] &= ~VISIBT;
    return true;
  }

  if (G.prsa === INXW ||
      ((G.prsa === ALARMW || G.prsa === KICKW) && G.ocapac[THIEF - 1] < 0)) {
    G.ocapac[THIEF - 1] = Math.abs(G.ocapac[THIEF - 1]);
    if (qhere(G, THIEF, G.here)) rspeak(G, 505);
    G.thfact = true;
    G.odesc1[THIEF - 1] = 503;
    G.oflag1[STILL - 1] |= VISIBT;
    return true;
  }

  if (G.prsa === TAKEW) {
    rspeak(G, 506); // joke
    return true;
  }

  if (G.prsa === THROWW && G.prso === KNIFE &&
      (G.oflag2[THIEF - 1] & FITEBT) === 0) {
    if (prob(G, 10, 10)) {
      let j = 508;
      for (let i = 1; i <= G.olnt; i++) {
        if (G.oadv[i - 1] !== -THIEF) continue;
        j = 509;
        newsta(G, i, 0, G.here, 0, 0);
      }
      newsta(G, THIEF, j, 0, 0, 0);
      return true;
    }
    rspeak(G, 507); // thief gets mad
    G.oflag2[THIEF - 1] |= FITEBT;
    return true;
  }

  if ((G.prsa === THROWW || G.prsa === GIVEW) &&
      G.prso !== 0 && G.prso !== THIEF) {
    if (G.ocapac[THIEF - 1] < 0) {
      G.ocapac[THIEF - 1] = Math.abs(G.ocapac[THIEF - 1]);
      G.thfact = true;
      G.odesc1[THIEF - 1] = 503;
      G.oflag1[STILL - 1] |= VISIBT;
      rspeak(G, 510);
    }
    if (G.prso === BRICK && G.ocan[FUSE - 1] === BRICK &&
        G.ctick[CEVFUS - 1] !== 0) {
      rspeak(G, 511); // refuses bomb
      return true;
    }
    if (G.prso === WATER) {
      newsta(G, WATER, 1081, 0, 0, 0);
      return true;
    }
    newsta(G, G.prso, 0, 0, 0, -THIEF);
    if (G.otval[G.prso - 1] > 0) {
      rspsub(G, 627, G.odesc2[G.prso - 1]); // engrossed
      G.thfenf = true;
      return true;
    }
    rspsub(G, 512, G.odesc2[G.prso - 1]);
    return true;
  }

  return false;
}

function blow(G, h, v, rmk, hflg, out) {
  const ra = G.oactio[v - 1];
  const dv = G.odesc2[v - 1];
  let res = RMISS;
  let att, def, oa, od, dweap;
  let pblose;

  if (hflg) {
    // Hero is attacker
    pblose = 10;
    G.oflag2[v - 1] |= FITEBT;
    if ((G.aflag[h - 1] & ASTAG) !== 0) {
      rspeak(G, 591);
      G.aflag[h - 1] &= ~ASTAG;
      return RMISS;
    }
    att   = Math.max(1, fights(G, h, true));
    oa    = att;
    def   = vilstr(G, v);
    od    = def;
    dweap = 0;
    for (let i = 1; i <= G.olnt; i++) {
      if (G.ocan[i - 1] === v && (G.oflag2[i - 1] & WEAPBT) !== 0) dweap = i;
    }
    if (v === G.aobj[PLAYER - 1]) { jigsup(G, 593); return RMISS; }
    if (def === 0) { rspsub(G, 592, dv); return RMISS; }
  } else {
    // Villain is attacker
    G.prscon = 0;
    pblose = 50;
    G.aflag[h - 1] &= ~ASTAG;
    if ((G.oflag2[v - 1] & STAGBT) !== 0) {
      G.oflag2[v - 1] &= ~STAGBT;
      rspsub(G, 594, dv);
      return RMISS;
    }
    att  = vilstr(G, v);
    oa   = att;
    def  = fights(G, h, true);
    if (def <= 0) return RMISS;
    od   = fights(G, h, false);
    dweap = Math.abs(fwim(G, 0, WEAPBT, 0, 0, h, true));
  }

  // --- label 2000: parties equipped ---
  let alreadyDead = false;
  if (def <= 0) {
    res = RKILL;
    if (hflg) rspsub(G, 595, dv);
    alreadyDead = true; // Fortran: GO TO 3000 (skip message printing)
  } else {
    // Choose table
    let tbl;
    if (def < 2) {
      att = Math.min(att, 3);
      tbl = DEF1R[att];
    } else if (def === 2) {
      att = Math.min(att, 4);
      tbl = DEF2R[att];
    } else {
      att = Math.min(2, Math.max(-2, att - def)) + 3;
      tbl = DEF3R[att];
    }

    // RVECTR(TBL + RND(10))  — Fortran 1-indexed, so JS index = tbl-1 + rnd(10)
    res = RVECTR[tbl - 1 + rnd(10)];

    // If hero was out, stagger->hesitate, other->sitting duck
    if (out !== 0) {
      if (res === RSTAG) res = RHES;
      else               res = RSIT;
    }

    // Weapon loss check
    // Fortran: IF((RES.EQ.RSTAG).AND.(DWEAP.NE.0).AND.PROB(25,PBLOSE))
    if (AND(res === RSTAG, dweap !== 0, prob(G, 25, pblose))) res = RLOSE;
  }

  // Print message (skip if defender was already dead/unconscious — Fortran GO TO 3000)
  if (!alreadyDead) {
    const mi = RSTATE[((rmk - 1) * 9) + res];
    if (mi !== 0) {
      const i = (mi % 1000) + rnd(Math.floor(mi / 1000)) + G.mbase + 1;
      let j = dv;
      if (!hflg && dweap !== 0) j = G.odesc2[dweap - 1];
      rspsub(G, i, j);
    }
  }

  // --- label 3000: apply result ---
  switch (res) {
    case ROUT:
      if (hflg) def = -def; // villain unconscious
      break;
    case RKILL:
    case RSIT:
      def = 0;
      break;
    case RXXX:
      def = Math.max(0, def - 1);
      break;
    case RSER:
      def = Math.max(0, def - 2);
      break;
    case RSTAG:
      if (hflg) G.oflag2[v - 1] |= STAGBT;
      else       G.aflag[h - 1]  |= ASTAG;
      break;
    case RLOSE:
      newsta(G, dweap, 0, G.here, 0, 0);
      dweap = 0;
      if (!hflg) {
        dweap = Math.abs(fwim(G, 0, WEAPBT, 0, 0, h, true));
        if (dweap !== 0) rspsub(G, 605, G.odesc2[dweap - 1]);
      }
      break;
    // RMISS, RHES: no effect on def
  }

  // --- label 4000: return result ---
  if (hflg) {
    // Hero attacked villain
    G.ocapac[v - 1] = def;
    if (def !== 0) {
      if (res === ROUT && ra !== 0) {
        G.prsa = OUTXW;
        oappli(G, ra, 0);
      }
      return res;
    }
    // Villain dead
    G.oflag2[v - 1] &= ~FITEBT;
    rspsub(G, 572, dv);
    newsta(G, v, 0, 0, 0, 0);
    if (ra !== 0) {
      G.prsa = DEADXW;
      oappli(G, ra, 0);
    }
    return res;
  }

  // --- label 4500: villain attacked hero ---
  G.astren[h - 1] = -10000; // assume dead
  if (def !== 0) G.astren[h - 1] = def - od;
  if (def < od) {
    G.ctick[CEVCUR - 1] = 30;
    G.cflag[CEVCUR - 1] = true;
  }
  if (fights(G, h, true) > 0) return res;
  G.astren[h - 1] = 1 - fights(G, h, false);
  jigsup(G, 596);
  return -1;
}

