function cxappl(G, ri) {
  if (ri === 0) return 0;

  switch (ri) {
    case 1: // C1 — Coffin curse
      G.egyptf = G.oadv[COFFI - 1] !== G.winner;
      return 0;

    case 2: // C2 — Carousel exit
      if (G.caroff) return 0;
      rspeak(G, 121); // spin the compass
      // fall through to C5
      return cxappl_c5(G);

    case 3: { // C3 — Chimney function
      G.litldf = false;
      let j = 0;
      for (let i = 0; i < G.olnt; i++) {
        if (G.oadv[i] === G.winner) j++;
      }
      if (j > 2) return 0; // carrying too much
      G.xstrng = 446; // assume no lamp
      if (G.oadv[LAMP - 1] !== G.winner) return 0;
      G.litldf = true;
      if ((G.oflag2[DOOR - 1] & OPENBT) === 0) {
        G.oflag2[DOOR - 1] &= ~TCHBT;
      }
      return 0;
    }

    case 4: // C4 — Frobozz flag (magnet room, fake exit)
      if (G.caroff) {
        rspeak(G, 121);
        return cxappl_c5(G);
      }
      G.frobzf = false;
      return 0;

    case 5: // C5 — Carousel out
      return cxappl_c5(G);

    case 6: // C6 — Frobozz flag (magnet room, real exit)
      if (G.caroff) {
        rspeak(G, 121);
        return cxappl_c5(G);
      }
      G.frobzf = true;
      return 0;

    case 7: // C7 — Frobozz flag (bank alarm)
      G.frobzf = G.oroom[BILLS - 1] !== 0 && G.oroom[PORTR - 1] !== 0;
      return 0;

    case 8: { // C8 — Frobozz flag (MRGO)
      G.frobzf = false;
      if (G.mloc !== G.xroom1) {
        // Mirror not in way
        return G.xroom1;
      }
      if (G.prso === XNORTH || G.prso === XSOUTH) {
        // N-S movement
        G.xstrng = 814; // structure blocks
        if (G.mdir % 180 === 0) return 0; // mirror N-S, done
        // Mirror is E-W
        let ldir = G.mdir;
        if (G.prso === XSOUTH) ldir = 180;
        G.xstrng = 815;
        if ((ldir > 180 && !G.mr1f) || (ldir < 180 && !G.mr2f)) {
          G.xstrng = 816;
        }
        return 0;
      }
      if (G.mdir % 180 !== 0) {
        // Mirror not N-S
        let ldir = G.mdir;
        if (G.prso === XSOUTH) ldir = 180;
        G.xstrng = 815;
        if ((ldir > 180 && !G.mr1f) || (ldir < 180 && !G.mr2f)) {
          G.xstrng = 816;
        }
        return 0;
      }
      // Mirror is N-S, calc east room
      G.xroom1 = ((G.xroom1 - MRA) * 2) + MRAE;
      if (G.prso > XSOUTH) G.xroom1++; // SW/NW = west side
      return G.xroom1;
    }

    case 9: // C9 — Frobozz flag (MIRIN)
      if (mrhere(G, G.here) === 1) {
        if (G.mr1f) G.xstrng = 805; // broken
        G.frobzf = G.mropnf;
        return 0;
      }
      G.frobzf = false;
      G.xstrng = 817;
      return 0;

    case 10: { // C10 — Frobozz flag (mirror exit)
      G.frobzf = false;
      const ldir = Math.floor((G.prso - XNORTH) / XNORTH) * 45;
      if (G.mropnf && ((G.mdir + 270) % 360 === ldir || G.prso === XEXIT)) {
        G.xroom1 = ((G.mloc - MRA) * 2) + MRAE + 1 - Math.floor(G.mdir / 180);
        if (G.mdir % 180 === 0) {
          // N-S, ok
        } else {
          G.xroom1 = G.mloc + 1;
          if (G.mdir > 180) G.xroom1 = G.mloc - 1;
        }
        return G.xroom1;
      }
      if (G.wdopnf && ((G.mdir + 180) % 360 === ldir || G.prso === XEXIT)) {
        G.xroom1 = G.mloc + 1;
        if (G.mdir === 0) G.xroom1 = G.mloc - 1;
        rspeak(G, 818); // close door
        G.wdopnf = false;
        return G.xroom1;
      }
      return 0;
    }

    case 11: // C11 — Maybe door
      if (G.lcell !== 4) G.xstrng = 678;
      return 0;

    case 12: // C12 — Frobzf (puzzle room main entrance)
      G.frobzf = true;
      G.cphere = 10;
      return 0;

    case 13: // C13 — Cpoutf (puzzle room side entrance)
      G.cphere = 52;
      return 0;

    case 14: { // C14 — Frobzf (puzzle room transitions)
      G.frobzf = false;
      if (G.prso === XUP) {
        if (G.cphere !== 10) return 0;
        G.xstrng = 881; // no ladder
        if (G.cpvec[G.cphere] !== -2) return 0;
        rspeak(G, 882);
        G.frobzf = true;
        return 0;
      }
      if (G.cphere === 52 && G.prso === XWEST && G.cpoutf) {
        G.frobzf = true;
        return 0;
      }
      // Locate exit
      let di = -1;
      for (let i = 0; i < 16; i += 2) {
        if (G.prso === G.cpdr[i]) { di = i; break; }
      }
      if (di < 0) return 0; // no such exit
      const j = G.cpdr[di + 1];
      const nxt = G.cphere + j;
      let k = 8;
      if (j < 0) k = -8;
      if ((Math.abs(j) === 1 || Math.abs(j) === 8 ||
           (G.cpvec[G.cphere + k - 1] === 0 || G.cpvec[nxt - k - 1] === 0)) &&
          G.cpvec[nxt - 1] === 0) {
        cpgoto(G, nxt);
        G.xroom1 = CPUZZ;
        return G.xroom1;
      }
      return 0;
    }

    case 15: { // C15 — Slide exit (frobzf + optional rope slide)
      G.frobzf = true;
      if (G.ttie === 0 || G.deadf) return 0; // no rope or dead → cellar
      if (G.oroom[G.ttie - 1] !== G.here) return 0; // rope elsewhere → cellar
      rspeak(G, 1014); // slippery!
      G.cflag[CEVSLI - 1] = true;
      G.ctick[CEVSLI - 1] = Math.max(2, Math.floor(100 / weighr(G, 0, G.winner)));
      G.xroom1 = SLID1;
      return G.xroom1;
    }

    default:
      bug(G, 5, ri);
      return 0;
  }
}

function valuac(G, v) {
  const av = G.avehic[G.winner - 1];

  // Nohere check helper
  function nohere(r) {
    if (av === 0) return !qhere(G, r, G.here);
    return G.ocan[r - 1] !== av;
  }

  // Nothis check helper
  function nothis(r) {
    if (v === BUNOBJ && qbunch(G, r)) return true;
    if (G.otval[r - 1] <= 0 && (v === VALUA || (v === BUNOBJ && G.bunsub === VALUA))) return true;
    if (G.oadv[r - 1] !== G.winner && (v === POSSE || (v === BUNOBJ && G.bunsub === POSSE))) return true;
    return false;
  }

  // Count possessions
  // Fortran uses I1 for singular (no padding) and I2 for plural (2-char field, space-pads 1-digit numbers)
  if (G.prsa === COUNTW && G.prso === POSSE) {
    let k = 0;
    for (let j = 0; j < G.olnt; j++) {
      if (G.oadv[j] === G.winner) k++;
    }
    if (k === 1) {
      G.output(` You have ${k} possession.`);
    } else {
      G.output(` You have ${String(k).padStart(2)} possessions.`);
    }
    G.telflg = true;
    return;
  }

  // Count valuables
  // Fortran uses I1 for singular (no padding) and I2 for plural (2-char field, space-pads 1-digit numbers)
  if (G.prsa === COUNTW && G.prso === VALUA) {
    let k = 0;
    let l = 0;
    for (let j = 0; j < G.olnt; j++) {
      if (G.oadv[j] === G.winner && G.otval[j] > 0) k++;
      if (G.ocan[j] === TCASE && G.otval[j] > 0) l++;
    }
    if (k === 1) {
      G.output(` You have ${k} valuable.`);
    } else {
      G.output(` You have ${String(k).padStart(2)} valuables.`);
    }
    G.telflg = true;
    if (G.here !== LROOM) return;
    if (l === 1) {
      G.output(` Your adventure has netted ${l} treasure.`);
    } else {
      G.output(` Your adventure has netted ${String(l).padStart(2)} treasures.`);
    }
    return;
  }

  // Take/Drop/Put
  const savep = G.prso;
  const saveh = G.here;
  let f = true;
  let i = 579; // assume not lit

  if (G.prsa === TAKEW) {
    // Take
    if (!lit(G, G.here)) { if (f) rspeak(G, i); G.prso = savep; G.bunsub = 0; return; }
    if (G.prso === BUNOBJ && G.bunsub === 0) {
      // Bunch with no except
      for (let bi = 0; bi < G.bunlnt; bi++) {
        G.prso = G.bunvec[bi];
        f = false;
        rspsub(G, 580, G.odesc2[G.prso - 1]);
        take(G, true);
        if (saveh !== G.here) { if (f) rspeak(G, i); G.prso = savep; G.bunsub = 0; return; }
      }
    } else {
      // Loop through all objects
      for (let obj = 1; obj <= G.olnt; obj++) {
        if (((G.oflag1[obj - 1] & TAKEBT) === 0 && (G.oflag2[obj - 1] & TRYBT) === 0) ||
            (G.oflag1[obj - 1] & VISIBT) === 0 ||
            (G.oflag2[obj - 1] & ACTRBT) !== 0 ||
            nothis(obj)) continue;
        if (nohere(obj)) {
          const jc = G.ocan[obj - 1];
          if (jc === 0 || obj === WATER) continue;
          if ((G.oflag2[jc - 1] & OPENBT) === 0 ||
              (nohere(jc) && G.oadv[jc - 1] !== G.winner)) continue;
        }
        G.prso = obj;
        f = false;
        rspsub(G, 580, G.odesc2[G.prso - 1]);
        take(G, true);
        if (saveh !== G.here) { if (f) rspeak(G, i); G.prso = savep; G.bunsub = 0; return; }
      }
    }
    // Clean up
    i = 581;
    if (savep === VALUA) i = 582;
    if (f) rspeak(G, i);
    G.prso = savep;
    G.bunsub = 0;
    return;
  }

  if (G.prsa === DROPW) {
    if (G.prso === BUNOBJ && G.bunsub === 0) {
      for (let bi = 0; bi < G.bunlnt; bi++) {
        G.prso = G.bunvec[bi];
        f = false;
        rspsub(G, 580, G.odesc2[G.prso - 1]);
        drop(G, true);
        if (saveh !== G.here) { if (f) rspeak(G, i); G.prso = savep; G.bunsub = 0; return; }
      }
    } else {
      for (let obj = 1; obj <= G.olnt; obj++) {
        if (G.oadv[obj - 1] !== G.winner || nothis(obj)) continue;
        G.prso = obj;
        f = false;
        rspsub(G, 580, G.odesc2[G.prso - 1]);
        drop(G, true);
        if (saveh !== G.here) { if (f) rspeak(G, i); G.prso = savep; G.bunsub = 0; return; }
      }
    }
    i = 581;
    if (savep === VALUA) i = 582;
    if (f) rspeak(G, i);
    G.prso = savep;
    G.bunsub = 0;
    return;
  }

  if (G.prsa === PUTW) {
    if (!lit(G, G.here)) { if (f) rspeak(G, i); G.prso = savep; G.bunsub = 0; return; }
    if (G.prso === BUNOBJ && G.bunsub === 0) {
      for (let bi = 0; bi < G.bunlnt; bi++) {
        G.prso = G.bunvec[bi];
        f = false;
        rspsub(G, 580, G.odesc2[G.prso - 1]);
        put(G, true);
        if (saveh !== G.here) { if (f) rspeak(G, i); G.prso = savep; G.bunsub = 0; return; }
      }
    } else {
      for (let obj = 1; obj <= G.olnt; obj++) {
        if ((G.oadv[obj - 1] !== G.winner &&
            (nohere(obj) || ((G.oflag1[obj - 1] & TAKEBT) === 0 && (G.oflag2[obj - 1] & TRYBT) === 0))) ||
            obj === G.prsi || nothis(obj) ||
            (G.oflag1[obj - 1] & VISIBT) === 0) continue;
        G.prso = obj;
        f = false;
        rspsub(G, 580, G.odesc2[G.prso - 1]);
        put(G, true);
        if (saveh !== G.here) { if (f) rspeak(G, i); G.prso = savep; G.bunsub = 0; return; }
      }
    }
    i = 581;
    if (savep === VALUA) i = 582;
    if (f) rspeak(G, i);
    G.prso = savep;
    G.bunsub = 0;
    return;
  }

  // Wrong verb
  i = 677;
  if (f) rspeak(G, i);
  G.prso = savep;
  G.bunsub = 0;
}

async function rhack(cmd) {
  if (movecm(cmd)) {
    if (game.multi) game.flags.mv = 1;
    await domove();
    return;
  }
  // Uppercase run-direction
  const lower = String.fromCharCode(cmd.charCodeAt(0) + 0x20);
  if (movecm(lower)) {
    game.flags.mv = 2; game.multi += 80; await domove(); return;
  }

  switch (cmd) {
    case 'f': {
      // C ref: hack.do.c case 'f' — run in direction until something interesting
      const dir = await game.input.getKey();
      if (movecm(dir)) { game.flags.mv = 3; game.multi += 80; await domove(); }
      else await pline('Bad f direction.');
      return;
    }
    case 's': await dosearch(); break;
    case 'e': {
      const otmp = await getobj('%', 'eat');
      if (!otmp) { game.multi = game.flags.move = 0; return; }
      if (!rn2(7)) {
        await pline('Blecch!!  Rotten food!');
        if (!rn2(4)) { await pline('You feel light headed.'); game.u.uconfused += d(2, 4); }
        else if (!rn2(4) && !game.u.ublind) { await pline('Everything suddenly goes dark.'); game.u.ublind = d(2, 10); seeoff(0); }
        else if (!rn2(3)) { await pline('The world spins and goes dark.'); nomul(-rnd(10)); }
        lesshungry(otmp.otyp ? 20 : 200);
      } else if (otmp.otyp) { await pline('That was a delicious fruit.'); lesshungry(100); }
      else { await pline('That really hit the spot!'); lesshungry(900); game.multi = -5; }
      useup(otmp); break;
    }
    case 'Q': await done1(); break;
    case 'q': {
      const otmp = await getobj('!', 'drink');
      if (!otmp) { game.multi = game.flags.move = 0; }
      else await drink1(otmp);
      break;
    }
    case 'w': {
      game.multi = 0;
      if (game.uwep && game.uwep.cursed) { await pline(CURSED); break; }
      const otmp = await getobj(')', 'wield');
      if (!otmp) { game.flags.move = false; break; }
      if (otmp.olet === '[') { await pline("You can't wield armor."); game.flags.move = false; break; }
      game.uwep = otmp; await prinv(otmp); break;
    }
    case 'r': {
      const otmp = await getobj('?', 'read');
      if (!otmp) { game.multi = game.flags.move = 0; }
      else await read1(otmp); break;
    }
    case '\x0c':  // ^L — redraw
      await docrt(); game.multi = game.flags.move = 0; break;
    case 'i':
      if (!game.invent) await pline(EMPTY);
      else await doinv(null);
      game.flags.move = game.multi = 0; break;
    case 'c': {
      const otmp = await getobj('?!=//', 'call');
      if (otmp) await docall(otmp);
      game.flags.move = 0; break;
    }
    case '>':
      if (game.u.ustuck || game.u.ux !== game.xdnstair || game.u.uy !== game.ydnstair) {
        await pline("You can't go down now."); game.flags.move = game.multi = 0; return;
      }
      await movemon(); seeoff(1); await dodown(); setsee(); await docrt(); break;
    case '<':
      if (game.u.ustuck || game.u.ux !== game.xupstair || game.u.uy !== game.yupstair) {
        await pline("You can't go up now."); game.flags.move = game.multi = 0; return;
      }
      await movemon(); seeoff(1); await doup(); setsee(); await docrt(); break;
    case ' ': break;
    case 't': {
      const otmp = await getobj(')', 'throw');
      if (!otmp || !await getdir()) { game.flags.move = game.multi = 0; return; }
      if (otmp === game.uarm || otmp === game.uleft || otmp === game.uright) {
        await pline(WEARI); return;
      }
      if (otmp === game.uwep) { if (otmp.cursed) { await pline(CURSED); return; } game.uwep = null; }
      const range = otmp.olet === ')' ? 6 : 5;
      const mtmp = bhit(game.dx, game.dy, range);
      const sx = game.dx, sy = game.dy;
      loseone(otmp, sx, sy);
      if (mtmp) { await amon(mtmp, otmp, -4); if (mtmp.mhp < 1) newsym(sx, sy); }
      else newsym(sx, sy);
      break;
    }
    case 'd': {
