    }
    case 'p': {
      const otmp = await getobj('/', 'zap');
      if (!otmp) { game.flags.move = game.multi = 0; return; }
      if (!otmp.spe) { await pline(NOTHIN); return; }
      if (otmp.otyp < 3) {
        otmp.spe--;
        switch (otmp.otyp) {
          case 0: await litroom(); break;
          case 1: if (!await findit()) return;  break;
          case 2: makemon(null); if (game.fmon) mnexto(game.fmon); break;
        }
        return;
      }
      if (!await getdir()) return;
      otmp.spe--;
      if (otmp.otyp < 10) {
        const htmp = bhit(game.dx, game.dy, rn1(8,6));
        if (htmp) {
          if (otmp.otyp === 3) { // striking
            if (rnd(20) < 10 + htmp.data.ac) { await hit('wand', htmp); htmp.mhp -= d(2,12); if (htmp.mhp < 1) await killed(htmp); }
            else await miss('wand', htmp);
          } else {
            switch (otmp.otyp) {
              case 4: htmp.mspeed = 2; break;  // MSLOW
              case 5: htmp.mspeed = 3; break;  // MFAST
              case 6: if ('WVZ&'.includes(htmp.data.mlet)) { htmp.mhp -= rnd(8); if (htmp.mhp < 1) await killed(htmp); else htmp.mstat = 1; } break;
              case 7: newcham(htmp, mon[rn2(8)][rn2(7)]); break;
              case 8: htmp.mcan = true; break;
              case 9: rloc(htmp); break;
            }
          }
        }
      } else await buzz(otmp.otyp - 11, game.u.ux, game.u.uy, game.dx, game.dy);
      break;
    }
    case 'W': {
      game.multi = 0;
      if (game.uarm) { game.flags.move = false; await pline('Already wearing armor.'); return; }
      const otmp = await getobj('[', 'wear');
      if (!otmp) { game.flags.move = false; break; }
      // C ref: movemon(); movemon(); then set uarm, nomul(-3), adjust AC, prinv
      await movemon(); await movemon();
      game.uarm = otmp; nomul(-3); otmp.known = true;
      game.u.uac -= otmp.otyp;
      if (otmp.minus) game.u.uac += otmp.spe; else game.u.uac -= otmp.spe;
      game.flags.botl |= AC; await prinv(game.uarm); break;
    }
    case 'P': {
      if (game.uleft && game.uright) { await pline('You are wearing two rings.'); game.flags.move = 0; break; }
      const otmp = await getobj('=', 'wear');
      if (!otmp) { game.flags.move = 0; break; }
      if (otmp === game.uleft || otmp === game.uright) { await pline('You are already wearing that.'); game.flags.move = 0; break; }
      if (game.uleft) game.uright = otmp;
      else if (game.uright) game.uleft = otmp;
      else {
        let side;
        do {
          await pline('Right or Left? ');
          side = await game.input.getKey();
          game.flags.topl = 1;  // C resets topl after reading "Right or Left?" key
          if (side === '\x1b') { game.flags.move = 0; return; }
        } while (!'rl'.includes(side));
        if (side === 'l') game.uleft = otmp; else game.uright = otmp;
      }
      // Apply ring effects
      applyRingOn(otmp); await prinv(otmp); break;
    }
    case 'R': {
      game.multi = 0;
      const otmp = await getobj('=', 'remove');
      if (!otmp) { game.flags.move = 0; return; }
      if (otmp.cursed) { await pline(CURSED); game.flags.move = 0; break; }
      else if (otmp === game.uleft) {
        game.uleft = null;
        await pline('You were wearing %s', doname(otmp));
        ringoff(otmp);
      } else if (otmp === game.uright) {
        game.uright = null;
        await pline('You were wearing %s', doname(otmp));
        ringoff(otmp);
      } else {
        await pline("You can't remove that."); game.flags.move = 0;
      }
      break;
    }
    case 'T': {
      game.multi = 0;
      if (!game.uarm) { await pline('Not wearing any!'); game.flags.move = 0; break; }
      if (game.uarm.cursed) { await pline(CURSED); game.flags.move = 0; break; }
      // C ref: movemon(); movemon(); nomul(-3); adjust AC; uarm=0; were(otmp);
      await movemon(); await movemon();
      const otmp = game.uarm;
      game.u.uac += otmp.otyp;
      if (otmp.minus) game.u.uac -= otmp.spe; else game.u.uac += otmp.spe;
      game.flags.botl |= AC; game.uarm = null; nomul(-3);
      await pline('You were wearing %s', doname(otmp)); break;
    }
    case 'S': await dosave(); break;
    case '!': {
      // Shell escape — subshell (not in original 1982 hack, added for browser)
      game.flags.move = false;
      try {
        const { Shell } = await import('../../shell/shell.js');
        const d = game.display;
        // Disable hack's cursor-sync hook during subshell
        const savedBeforeWait = game.input.beforeWait;
        game.input.beforeWait = null;
        // Shell getch expects numeric char codes; hack getKey returns string chars
        const shell = new Shell(d, async () => {
          const ch = await game.input.getKey();
          return ch.charCodeAt(0);
        });
        await shell.run({ subshell: true });
        // Restore hack state
        game.input.beforeWait = savedBeforeWait;
        d.clearScreen();
        await docrt();
        bot();
        d.flush();
      } catch (e) { /* shell not available */ }
      break;
    }
    default:
      if (cmd < ' ') await pline("Unknown command '^%c'.", String.fromCharCode(cmd.charCodeAt(0) + 64));
      else await pline("Unknown command '%c'", cmd);
      game.flags.move = false; break;
  }
}

async function domove() {
  const u = game.u;
  const levl = game.levl;

  if (u.utrap) {
    if (u.upit) await pline('You are still in a pit.');
    else await pline('You are caught in a beartrap.');
    u.utrap--;
    return;
  }
  if (u.uconfused) {
    do { game.dx = rn1(3,-1); game.dy = rn1(3,-1); }
    while (!game.dx && !game.dy);
  }
  const nx = u.ux + game.dx, ny = u.uy + game.dy;
  const tmpr = levl[nx][ny];
  const ust = levl[u.ux][u.uy];

  if (u.uswallow) {
    await attmon(u.ustuck, game.uwep, 0);
    if (game.multi) game.multi = 0;
    return;
  }
  if (u.ustuck && (nx !== u.ustuck.mx || ny !== u.ustuck.my)) {
    await k1('You cannot escape from %s%s!', u.ustuck.data.mname);
    if (game.multi) game.multi = 0;
    return;
  }
  const mtmp = g_at_mon(nx, ny, game.fmon);
  if (mtmp) {
    nomul(0);
    if (u.ublind) { await amon(mtmp, game.uwep, 0); }
    else if (mtmp.sinv) {
      if (mtmp.data.mlet === 'M') {
        await pline("That's a %s!", mtmp.data.mname);
        if (!u.ustuck) u.ustuck = mtmp;
        mtmp.sinv = false; atl(mtmp.mx, mtmp.my, 'M');
        return;
      } else if (mtmp.data.mlet === 'p') {
        if (u.uac + 5 > rnd(20)) {
          await pline('You are impaled by a falling piercer!');
          u.uhp -= d(4,6); game.flags.botl |= HP;
          game.killer = mtmp.data.mname;
        } else await pline('You duck a falling piercer!');
        mtmp.invis = false; mtmp.sinv = false; atl(mtmp.mx, mtmp.my, 'p');
      } else await justswld(mtmp);
      return;
    } else if (!game.flags.mdone || (!u.ucinvis && mtmp.invis)) {
      await amon(mtmp, game.uwep, 0);
    }
    return;
  }
  if (tmpr.typ < DOOR || (g_at_gen(nx, ny, game.ftrap) &&
      g_at_gen(nx, ny, game.ftrap).gflag & SEEN && game.flags.mv)) {
    game.flags.mv = game.multi = 0;
    if (game.flags.mdone) pru();
    if (!u.uconfused) game.flags.move = false;
    return;
  }
  if (game.dx && game.dy && (tmpr.typ === DOOR || ust.typ === DOOR)) {
    game.flags.move = game.flags.mv = game.multi = 0;
    if (game.flags.mdone) pru();
    return;
  }
  const oldux = u.ux, olduy = u.uy;
  u.ux = nx; u.uy = ny;
  game.flags.mdone = true;

  if (game.flags.mv > 1) {
    if ((game.xupstair === u.ux && game.yupstair === u.uy) ||
        (game.xdnstair === u.ux && game.ydnstair === u.uy)) nomul(0);
    if (!u.ublind) {
      if (levl[u.ux + game.dy] && levl[u.ux + game.dy][u.uy - game.dx] &&
          levl[u.ux + game.dy][u.uy - game.dx].typ === DOOR) nomul(0);
      if (levl[u.ux - game.dy] && levl[u.ux - game.dy][u.uy + game.dx] &&
          levl[u.ux - game.dy][u.uy + game.dx].typ === DOOR) nomul(0);
    }
    if (tmpr.typ === DOOR) {
      if (!u.ublind) game.multi = game.multi > 80 ? game.multi - 1 : 1;
      else nomul(0);
    }
  }

  if (ust.scrsym === '@') { newsym(oldux, olduy); game.oldux = oldux; game.olduy = olduy; }

  if (!u.ublind) {
    if (ust.lit) {
      if (tmpr.lit) {
        if (tmpr.typ === DOOR) prl1(u.ux + game.dx, u.uy + game.dy);
        else if (ust.typ === DOOR) nose1(oldux - game.dx, olduy - game.dy);
      } else { unsee(); ust.cansee = true; prl1(u.ux + game.dx, u.uy + game.dy); }
    } else {
      if (tmpr.lit) setsee();
      else {
        prl1(u.ux + game.dx, u.uy + game.dy);
        if (tmpr.typ === DOOR) {
          if (game.dy) { prl(u.ux-1, u.uy); prl(u.ux+1, u.uy); }
          else { prl(u.ux, u.uy-1); prl(u.ux, u.uy+1); }
        }
      }
      nose1(oldux - game.dx, olduy - game.dy);
    }
  } else if (!ust.seen) {
    ust.cansee = false; ust.isnew = true; on(oldux, olduy);
  } else ust.cansee = false;

  if (!game.multi) pru();

  // Pick up gold
  const gold = g_at_gen(u.ux, u.uy, game.fgold);
  if (gold) {
    if (gold.gflag < 2) gold.gflag = 2;
    await pline('%u gold pieces.', gold.gflag);
    u.urexp += gold.gflag; u.ugold += gold.gflag; game.flags.botl |= GOLD;
    if (gold === game.fgold) game.fgold = game.fgold.ngen;
    else { let g1 = game.fgold; while (g1.ngen !== gold) g1 = g1.ngen; g1.ngen = gold.ngen; }
    if (game.flags.mv > 1) nomul(0);
    if (u.uinvis) newsym(u.ux, u.uy);
  }

  // Pick up items
  const obj = g_at_obj(u.ux, u.uy, game.fobj);
  if (obj) {
    let wt = 0;
    for (let o = game.invent; o; o = o.nobj) wt += weight(o);
    wt += weight(obj);
    if (wt > 85) await pline('Your pack is full.');
    else { await gobj(obj); }
    if (game.flags.mv > 1) nomul(0);
  }

  // Trigger traps
  const trap = g_at_gen(u.ux, u.uy, game.ftrap);
  if (trap) {
    nomul(0);
    const ttype = trap.gflag & 0x1f;
    if (trap.gflag & SEEN && !rn2(6)) {
      await pline('You escape a%s.', trapName(ttype));
    } else {
      trap.gflag |= SEEN;
      switch (ttype) {
        case 6: // SLPTRP
          await pline('A cloud of gas puts you to sleep!'); nomul(-rnd(25)); break;
        case 0: // BEAR
          u.utrap = rn1(4,4); u.upit = false;
          await pline('A bear trap closes on your foot!'); break;
        case 1: // ARROW
          if (hitu(10, rnd(6), 'arrow')) await pline('An arrow shot you!');
          else await pline('You duck an arrow!'); break;
        case 3: // TDOOR
          if (!game.xdnstair) {
            await pline('A trapdoor opens and a rock falls on you!');
            u.uhp -= d(2,10); game.flags.botl |= HP;
          } else {
            await pline('A trap door opens up under you!');
            if (u.ufloat || u.ustuck) { await pline("You don't fall in!"); break; }
            seeoff(1);
            // C ref: do dodown(); while(!rn2(4) && xdnstair) — player can fall multiple levels
            do { await dodown(); } while (!rn2(4) && game.xdnstair);
            do { u.ux = rnd(79); u.uy = rn2(22); }
            while (levl[u.ux][u.uy].typ < ROOM || g_at_mon(u.ux, u.uy, game.fmon));
            setsee(); await docrt_fn();
          }
          break;
        case 2: // DART
          if (hitu(9, rnd(3), 'dart')) {
            await pline('A dart zaps out and hits you!');
            if (!rn2(6)) { await poisoned_fn('dart'); game.killer = 'poison dart'; }
          } else await pline('A dart wizzes by you and vanishes!'); break;
        case 4: // TELE
          newsym(u.ux, u.uy); tele(); break;
        case 5: // PIT
          if (u.ufloat) { await pline('A pit opens up under you!'); await pline("You don't fall in!"); break; }
          await pline('You fall into a pit!');
          u.utrap = rn1(6,2); u.upit = true;
          u.uhp -= rnd(6); game.flags.botl |= HP;
          game.killer = 'pit'; break;
        default:
          await pline('Bad trap %d', ttype);
      }
    }
  }
}

async function dochug(mtmp) {
  logEvent(`dochug[mlet=${mtmp.data.mlet},mstat=${mtmp.mstat},cansee=${game.levl[mtmp.mx][mtmp.my].cansee}]`);
  if (mtmp.cham && !rn2(6) && _newcham) _newcham(mtmp, mon[rn1(6, 2)][rn2(8)]);
  const mdat = mtmp.data;
  // Regenerate monsters
  if ((!game.moves % 20 || mregen.includes(mdat.mlet)) && mtmp.mhp < mtmp.orig_hp)
    mtmp.mhp++;
  if (mtmp.mstat === MFROZ || mtmp.sinv) return;
  if (mtmp.mstat === SLEEP) {
    if (game.levl[mtmp.mx][mtmp.my].cansee && !game.u.ustelth &&
        (!rn2(7) || game.u.uagmon)) mtmp.mstat = MNORM;
    else return;
  }
  if (mdat.mmove >= rnd(12) &&
      (mtmp.mstat === FLEE || Math.abs(mtmp.mx - game.u.ux) > 1 || Math.abs(mtmp.my - game.u.uy) > 1) &&
      _rloc && m_move(mtmp) && mdat.mmove <= 12) return;

  if (game.u.uswallow) {
    if (mtmp === game.u.ustuck) {
      switch (mtmp.data.mlet) {
        case ',': await k1(CRUSH, mtmp.data.mname); youswld(mtmp, 4 + game.u.uac, 5); break;
        case '~': await k1(CRUSH, mtmp.data.mname); youswld(mtmp, rnd(6), 7); break;
        default:  await k1('%s%s digests you!', mtmp.data.mname); youswld(mtmp, d(2,4), 12); break;
      }
    }
    return;
  }

  const mdix = Math.abs(mtmp.mx - game.u.ux);
  const mdiy = Math.abs(mtmp.my - game.u.uy);

  if (mdat.mlet !== 'a' && mdix < 2 && mdiy < 2) {
    hits_val = 0;
    _nomul && _nomul(0);
    if (!'EyF&D'.includes(mdat.mlet))
      hitu(mdat.mhd, d(mdat.damn, mdat.damd), mdat.mname);

    switch (mdat.mlet) {
      case '&':
        if (!mtmp.mcan && !rn2(15)) {
          if (!rn2(3)) break;
          makemon(mon[7][6]); mnexto(game.fmon); hits_val = -1;
        } else {
          hitu(10, d(2,6), mdat.mname); hitu(10, d(2,6), mdat.mname);
          hitu(10, rnd(3), mdat.mname); hitu(10, rnd(3), mdat.mname);
          hitu(10, rn1(4,2), mdat.mname);
        }
        break;
      case '~': case ',':
        if (hits_val && !mtmp.mcan) { await mhit(mdat.mname); await justswld(mtmp); }
        break;
      case 'A':
        if (!mtmp.mcan && hits_val && rn2(2)) {
          await mhit(mdat.mname); await pline('You feel weaker!'); _losestr && _losestr(1);
        }
        break;
      case 'C': hitu(4, rnd(6), mdat.mname); break;
      case 'c':
        if (!mtmp.mcan && hits_val && rn2(2)) {
          await mhit(mdat.mname);
          if (rn2(5)) {
            await pline('You feel real drugged out now.');
            switch (rn2(3)) {
              case 0: game.u.uconfused = d(4,5); break;
              case 1: _nomul && _nomul(-d(3,4)); break;
              case 2: game.u.ufast += d(3,3); break;
            }
          } else {
            await pline('You get turned to stone!'); game.u.uhp = -1;
            game.killer = mdat.mname;
          }
        }
        break;
      case 'D':
        if (rn2(6) || mtmp.mcan) {
          hitu(10, d(3,10), mdat.mname); hitu(10, rnd(8), mdat.mname); hitu(10, rnd(8), mdat.mname);
          break;
        }
        _buzz && await _buzz(1, mtmp.mx, mtmp.my, game.u.ux - mtmp.mx, game.u.uy - mtmp.my);
        game.killer = mdat.mname; hits_val = -1; break;
      case 'd': hitu(6, d(2,4), mdat.mname); break;
      case 'E':
        if (!game.u.ublind && !rn2(3) && game.multi >= 0) {
          await k1('You are frozen by %s%ss gaze!', mdat.mname);
          _nomul && _nomul(-rn1(8,5));
        }
        return;
      case 'e': hitu(10, d(3,6), mdat.mname); break;
      case 'F':
        if (mtmp.mcan) break;
        await k1('%s%s explodes!', mdat.mname);
        if (game.u.ucoldres) await pline(NOCOLD);
        else {
          if (17 - Math.floor(game.u.ulevel / 2) > rnd(20)) {
            await pline('You get blasted!'); losehp(d(6,6));
          } else { await pline('You duck the blast...'); losehp(d(3,6)); }
          game.killer = mdat.mname;
        }
        delmon(mtmp); hits_val = -1;
        if (game.levl[mtmp.mx][mtmp.my].scrsym === 'F') newsym(mtmp.mx, mtmp.my);
        break;
      case 'g':
        if (!mtmp.mcan && hits_val && game.multi >= 0 && !rn2(6)) {
          await mhit(mdat.mname);
          await k1('You are frozen by %s%ss juices.', mdat.mname);
          _nomul && _nomul(-rnd(10));
        }
        break;
      case 'h':
        if (!mtmp.mcan && hits_val && game.multi >= 0 && !rn2(5)) {
          await mhit(mdat.mname); _nomul && _nomul(-rnd(10));
          await k1('%s%ss bite puts you to sleep!', mdat.mname);
        }
        break;
      case 'j': {
        let t = hitu(4, rnd(3), mdat.mname);
        t &= hitu(4, rnd(3), mdat.mname);
        if (t) { hitu(4, rnd(4), mdat.mname); hitu(4, rnd(4), mdat.mname); }
        break;
      }
      case 'k':
        if (hitu(4, rnd(4), mdat.mname) && !mtmp.mcan && !rn2(8)) {
          await mhit(mdat.mname); await poisoned("the bee's sting");
          game.killer = mdat.mname;
        }
        break;
      case 'L':
        if (!mtmp.mcan && hits_val && game.u.ugold && rn2(2)) {
          await mhit(mdat.mname);
          let tmp = rnd(game.u.ugold);
          if (tmp < 100 && game.u.ugold < 100) tmp = game.u.ugold;
          game.u.ugold -= tmp; game.u.urexp -= tmp;
          await pline('Your purse feels lighter.');
          _rloc && _rloc(mtmp); mtmp.mstat = FLEE; game.flags.botl |= 2;
          // Add to fstole
          let stmp = game.fstole;
          while (stmp && stmp.smon !== mtmp) stmp = stmp.nstole;
          if (stmp) stmp.sgold += tmp;
          else {
            stmp = makeStole(mtmp, null, tmp);
            stmp.nstole = game.fstole; game.fstole = stmp;
          }
        }
        break;
      case 'N':
        if (!mtmp.mcan && hits_val && game.invent && rn2(2)) {
          await mhit(mdat.mname); await steal(mtmp);
          _rloc && _rloc(mtmp); mtmp.mstat = FLEE;
        }
        break;
      case 'n':
        hitu(11, d(2,6), mdat.mname); hitu(11, d(2,6), mdat.mname); break;
      case 'o': {
        let t1 = hitu(5, rnd(6), mdat.mname);
        if (hitu(5, rnd(6), mdat.mname) && !mtmp.mcan && t1 && !game.u.ustuck && rn2(2)) {
          game.u.ustuck = mtmp; await mhit(mdat.mname);
          await k1('%s%s has grabbed you!', mdat.mname); game.u.uhp -= d(2,8);
        } else if (game.u.ustuck === mtmp) {
          game.u.uhp -= d(2,8); game.flags.botl |= HP;
          await pline('You are being crushed.');
        }
        game.killer = mdat.mname; break;
      }
      case 'P':
        if (!mtmp.mcan && hits_val && !rn2(4)) { await mhit(mdat.mname); await justswld(mtmp); }
        else hitu(15, d(2,4), mdat.mname);
        break;
      case 'Q': hitu(3, rnd(2), mdat.mname); hitu(3, rnd(2), mdat.mname); break;
      case 'R':
        hitu(5, 0, mdat.mname);
        if (!mtmp.mcan && hits_val && game.uarm && game.uarm.otyp !== 2 &&
            (!game.uarm.minus || game.uarm.otyp - game.uarm.spe !== 1)) {
          await mhit(mdat.mname); await pline(RUST);
          minusone(game.uarm); game.u.uac++; game.flags.botl |= 32;
        }
        break;
      case 'S':
        if (!mtmp.mcan && hits_val && !rn2(8)) {
          await mhit(mdat.mname); await poisoned("snake's bite"); game.killer = mdat.mname;
        }
        break;
      case 's':
        if (hits_val && !rn2(8)) { await poisoned("scorpion's sting"); game.killer = mdat.mname; }
        hitu(5, rnd(8), mdat.mname); hitu(5, rnd(8), mdat.mname); break;
      case 'T': hitu(6, rnd(6), mdat.mname); hitu(6, rnd(6), mdat.mname); break;
      case 'U': hitu(9, d(3,4), mdat.mname); hitu(9, d(3,4), mdat.mname); break;
      case 'v': if (!mtmp.mcan && hits_val && !game.u.ustuck) game.u.ustuck = mtmp; break;
      case 'V':
        if (hits_val) {
          game.u.uhp -= 4; await mhit(mdat.mname);
          if (!mtmp.mcan && !rn2(3)) losexp(); game.killer = mdat.mname;
        }
        break;
      case 'W':
        if (!mtmp.mcan && hits_val && !rn2(5)) { await mhit(mdat.mname); losexp(); }
        break;
      case 'X':
        for (let i = 0; i < 3; i++) hitu(8, rnd(3), mdat.mname); break;
      case 'y':
        if (mtmp.mcan) break;
        delmon(mtmp);
        if (game.levl[mtmp.mx][mtmp.my].cansee) newsym(mtmp.mx, mtmp.my);
        if (!game.u.ublind) {
          await pline('A yellow light blinds you!');
          game.u.ublind = d(4,12);
          // seeoff(0)
        }
        hits_val = -1; break;
      case 'Y': hitu(4, rnd(6), mdat.mname); break;
    }

    switch (hits_val) {
      case 0: await k1('%s%s misses', mdat.mname); break;
      case -1: break;
      default: await mhit(mdat.mname);
    }
    // Extra movement for fast monsters
    for (let tmp = mdat.mmove - 12; tmp > rnd(12); tmp -= 12) m_move(mtmp);
  }
}

async function moveloop_turnend(game) {
    const player = (game.u || game.u);
    const nextTurnCount = game.turnCount + 1;
    // C ref: allmain.c -- random spawn happens before svm.moves++.
    // During this turn-end frame, mkobj-side erosion checks should
    // still observe the pre-increment move count.
    game.moves = game.turnCount;

    // C ref: mon.c m_calcdistress() — per-monster distress timers.
    for (const mon of (game.map || game.map).monsters) {
        if (mon.dead) continue;
        // C ref: mon.c:1178-1183 — mblinded timeout
        if (mon.mblinded && typeof mon.mblinded === 'number') {
            mon.mblinded--;
            if (mon.mblinded <= 0) {
                mon.mblinded = 0;
                mon.mcansee = true;
            }
        }
        // C ref: mon.c:1185-1190 — mfrozen timeout
        if (mon.mfrozen && typeof mon.mfrozen === 'number') {
            mon.mfrozen--;
            if (mon.mfrozen <= 0) {
                mon.mfrozen = 0;
                mon.mcanmove = true;
            }
        }
        // C ref: mon.c:1192-1197 — mfleetim timeout
        if (mon.mfleetim && mon.mfleetim > 0) {
            mon.mfleetim--;
            if (mon.mfleetim <= 0) {
                mon.mfleetim = 0;
                mon.mflee = false;
            }
        }
    }

    // C ref: mon.c m_calcdistress() — HP regen + mspec_used decrement, once per game turn.
    for (const mon of (game.map || game.map).monsters) {
        if (mon.dead) continue;
        mon_regen(mon, false, nextTurnCount);
    }

    // C ref: mon.c m_calcdistress() shapechange + lycanthropy pass.
    for (const mon of (game.map || game.map).monsters) {
        if (mon.dead) continue;
        await runtimeDecideToShapeshift(mon, (game.u || game.u).dungeonLevel,
            (game.map || game.map), (game.u || game.u), game.fov, game.display);
        if ((mon.data || mon.type) && ((mon.data || mon.type).mflags2 & M2_WERE)) {
            await were_change(mon, {
                player: (game.u || game.u),
                map: (game.map || game.map),
                fov: game.fov,
                display: game.display,
            });
        }
    }

    // C ref: allmain.c:226-227 — reallocate movement to monsters via mcalcmove
    await allocateMonsterMovement((game.map || game.map));

    // C ref: allmain.c:232-236 — occasional random monster spawn.
    // Rate depends on demigod state and depth relative to stronghold.
    // Spawn happens after movement allocation, so a new monster loses first turn.
    // C uses depth(&u.uz) > depth(&stronghold_level); stronghold is the Castle.
    const spawnRate = player?.uevent?.udemigod ? 25
        : (dungeonDepth(player?.uz) > strongholdDepth(game) ? 50 : 70);
    if (!rn2(spawnRate)) {
        await makemon_appear(
            null,
            0,
            0,
            0,
            level_difficulty((game.map || game.map).uz, game),
            (game.map || game.map)
        );
    }

    // C ref: allmain.c:238 u_calc_moveamt(wtcap)
    u_calc_moveamt(player);

    // C ref: allmain.c:239 + 348-365 — settrack() then moves++ bookkeeping.
    settrack(player);
    game.turnCount = nextTurnCount;
    player.turns = game.turnCount;
    game._currentTurn = game.turnCount + 1;
    // C ref: allmain.c sets gh.hero_seq = svm.moves << 3 when moves advances;
    // track the low 3-bit action count separately for mapdump anchor parity.
    game.heroSeqN = 0;
    game.moves = game.turnCount;

    // C ref: allmain.c:213 — mvl_wtcap = near_capacity() is computed at
    // the top of the do-while iteration, BEFORE nh_timeout.  regen_hp and
    // overexert_hp use this cached value so they see the SAME encumbrance
    // even if nh_timeout changes it mid-iteration (e.g. healing wounded legs).
    const mvl_wtcap = near_capacity(player);

    // C ref: allmain.c once-per-turn block runs nh_timeout() after
    // mcalcdistress/mcalcmove and random spawn setup.
    await nh_timeout({
        player: (game.u || game.u),
        map: (game.map || game.map),
        display: game.display,
        game,
    });
    // C ref: allmain.c:273-274 — run_regions() runs immediately after nh_timeout().
    await run_regions((game.map || game.map), (game.u || game.u), game);
    // C ref: lethal side effects during nh_timeout()/run_regions() route
    // through done(); once death is pending/final, do not continue turn-end
    // RNG work in this cycle.
    if (game?.playerDied || game?.gameOver) {
        return;
    }

    // C ref: allmain.c:273-274 — ublesscnt countdown (prayer cooldown)
    {
        const p = (game.u || game.u);
        if (p.ublesscnt) p.ublesscnt--;
    }

    // C ref: allmain.c:276 — saving_grace_turn reset
    game.saving_grace_turn = false;

    // C ref: allmain.c:295-301 — regen_hp(mvl_wtcap)
    await regen_hp(game, mvl_wtcap);

    // C ref: allmain.c:297-301 — overexert_hp when encumbered and moving
    // Uses mvl_wtcap (cached BEFORE nh_timeout), matching C.
    {
        const p = player;
        if (mvl_wtcap > MOD_ENCUMBER && p.umoved) {
            const moves = game.turnCount;
            if (!(mvl_wtcap < EXT_ENCUMBER ? moves % 30 : moves % 10)) {
                await overexert_hp(game);
            }
        }
    }

    // C ref: allmain.c:304 — regen_pw(mvl_wtcap)
    await regen_pw_turnend(game, mvl_wtcap);

    // C ref: allmain.c:306-338 — Teleportation/Polymorph/Lycanthropy checks
    {
        const p = (game.u || game.u);
        const propActive = (propIdx, legacyName, legacyName2 = null) => {
            if (typeof p?.hasProp === 'function') return !!p.hasProp(propIdx);
            if (p?.uprops && p.uprops[propIdx]) {
                const e = p.uprops[propIdx];
                return !!(e.intrinsic || e.extrinsic);
            }
            return !!(p?.[legacyName] || (legacyName2 ? p?.[legacyName2] : 0));
        };
        const teleportation = propActive(TELEPORT, 'Teleportation', 'teleportation');
        const polymorph = propActive(POLYMORPH, 'Polymorph', 'polymorph');
        if (!p.uinvulnerable) {
            if (teleportation && !rn2(85)) {
                // tele() — full teleportation not ported; consume RNG only
                // TODO: wire tele() when available
            }
            if (polymorph && !rn2(100)) {
                // polyself() — full polymorph not ported; consume RNG only
                // TODO: wire polyself() when available
            } else if (p.ulycn != null && p.ulycn >= 0 && !p.Upolyd) {
                const nightBonus = 0; // TODO: night() not ported
                if (!rn2(80 - (20 * nightBonus))) {
                    // you_were() — lycanthropy not ported; consume RNG only
                    // TODO: wire you_were() when available
                }
            }
        }
    }

    // C ref: allmain.c:346-348 — autosearch for players with Searching
    // intrinsic (Archeologists/Rangers at level 1, Rogues at 10, etc.)
    // C also checks !svl.level.flags.noautosearch.
    {
        const mapFlags = (game.map || game.map)?.flags || {};
        if ((game.u || game.u).searching && !mapFlags.noautosearch && game.multi >= 0) {
            await dosearch0((game.u || game.u), (game.map || game.map), game.display, game, 1);
        }
    }

    // C ref: allmain.c:351 dosounds() — ambient sounds
    await moveloop_dosounds(game);

    // C ref: allmain.c:358 do_storms()
    do_storms();

    // C ref: allmain.c:353 gethungry()
    await gethungry((game.u || game.u));

    // C ref: allmain.c:354 age_spells() — decrement spell retention each turn
    age_spells((game.u || game.u));

    // C ref: allmain.c:355 exerchk() — exercise attribute checks.
    // C's exerchk() calls exerper() internally (attrib.c:601).
    const moves = game.turnCount + 1;
    await exerchk((game.u || game.u), moves);

    // C ref: allmain.c:362 — invault() between exerchk and u_wipe_engr
    await invault((game.map || game.map), (game.u || game.u), game.fov || FOV);

    // C ref: allmain.c:363-364 — amulet() when carrying Amulet of Yendor
    if ((game.u || game.u).uhave?.amulet) {
        await amulet((game.map || game.map), (game.u || game.u), game.display);
    }

    // C ref: allmain.c:370-371 — engrave wipe check (ACURR(A_DEX))
    // C: if (!rn2(40+DEX*3)) u_wipe_engr(rnd(3));
    // C's u_wipe_engr(cnt) receives rnd(3) as parameter THEN checks
    // can_reach_floor internally. The rnd(3) is consumed regardless of
    // whether can_reach_floor succeeds. Match C's call order.
    {
        const dex = acurr((game.u || game.u), A_DEX);
        if (!rn2(40 + dex * 3)) {
            const cnt = rnd(3); // consumed unconditionally, matching C
            if (can_reach_floor((game.u || game.u), (game.map || game.map), true)) {
                await wipe_engr_at((game.map || game.map), (game.u || game.u).x, (game.u || game.u).y, cnt, false);
            }
        }
    }

    // C ref: allmain.c:374 — water/air planes update moving bubbles/clouds each turn.
    if ((game.map || game.map)?.flags?.is_waterlevel || (game.map || game.map)?.flags?.is_airlevel) {
        if ((game.map || game.map)?._water && (game.u || game.u)) {
            (game.map || game.map)._water.heroPos = {
                x: (game.u || game.u).x,
                y: (game.u || game.u).y,
                dx: (game.u || game.u).dx || 0,
                dy: (game.u || game.u).dy || 0,
            };
            (game.map || game.map)._water.onHeroMoved = (x, y) => {
                (game.u || game.u).x = x;
                (game.u || game.u).y = y;
                mark_vision_dirty(); // player position changed
            };
            (game.map || game.map)._water.onVisionRecalc = () => {
                vision_recalc();
            };
        }
        await movebubbles((game.map || game.map));
    } else if ((game.map || game.map)?.flags?.fumaroles) {
        // C ref: allmain.c:381-382 — fumaroles on fire/lava levels
        await fumaroles((game.map || game.map));
    }

    // C ref: allmain.c:385-393 — immobile turn countdown and unmul().
    if (game.multi < 0) {
        await runmode_delay_output(game, game.display);
        if (++game.multi === 0) {
            await unmul(null, (game.u || game.u), game.display, game);
            if ((game.u || game.u)?.utotype) {
                await deferred_goto((game.u || game.u), game);
            }
        }
    }
    // After turn-end completes, subsequent command processing observes
    // the incremented move counter.
    game.moves = game.turnCount + 1;
    // C ref: allmain.c:472-478 — bot() runs when disp.botl is set.
    // In C this happens at the end of the per-turn block, before the hero
    // gets input. Render status now so the display reflects current HP,
    // encumbrance, Dlvl, etc. before the next screen capture.
    const _p = game?.u;
    if (_p) {
        _p._botl = true;
        if (game?.display && typeof game.display.renderStatus === 'function') {
            game.display.renderStatus(_p);
            _p._botl = false;
        }
    }
}

