async function set_artifact_intrinsic(otmp, on, wp_mask, player) {
  const oart = get_artifact(otmp);
  if (oart === artilist[ART_NONARTIFACT]) return;

  // In the JS port the player uprops system is keyed by property index.
  // Many of the C extrinsic bitfields (EFire_resistance etc.) map to
  // player.uprops[propIdx].extrinsic.  Since the full uprops system is
  // not always wired, we guard against missing entries.
  function ensureProp(propIdx) {
    if (!player || !player.uprops) return null;
    if (!player.uprops[propIdx])
      player.uprops[propIdx] = { intrinsic: 0, extrinsic: 0, blocked: 0 };
    return player.uprops[propIdx];
  }

  // --- defn / cary resistance ---
  const dtyp = (wp_mask !== W_ART) ? oart.defn.adtyp : oart.cary.adtyp;
  // Map AD_ to property index
  const adtypToProp = {
    [AD_FIRE]: 0,   // FIRE_RES
    [AD_COLD]: 1,   // COLD_RES
    [AD_ELEC]: 4,   // SHOCK_RES
    [AD_MAGM]: 11,  // ANTIMAGIC
    [AD_DISN]: 3,   // DISINT_RES
    [AD_DRST]: 5,   // POISON_RES
    [AD_DRLI]: 8,   // DRAIN_RES
  };

  let propIdx = adtypToProp[dtyp];
  if (propIdx !== undefined) {
    let dominated = false;
    // When removing W_ART carry effect, check if another carried artifact
    // also confers this; if so, leave the mask alone.
    if (wp_mask === W_ART && !on && player) {
      const inv = player.inventory || [];
      for (const o of inv) {
        if (o !== otmp && o.oartifact) {
          const art2 = get_artifact(o);
          if (art2 !== artilist[ART_NONARTIFACT] && art2.cary.adtyp === dtyp) {
            dominated = true;
            break;
          }
        }
      }
    }
    if (!dominated) {
      const p = ensureProp(propIdx);
      if (p) {
        if (on) p.extrinsic |= wp_mask;
        else p.extrinsic &= ~wp_mask;
      }
    }
  }

  // --- spfx intrinsics ---
  let spfx = (wp_mask !== W_ART) ? oart.spfx : oart.cspfx;
  if (spfx && wp_mask === W_ART && !on && player) {
    // don't remove spfx also conferred by other carried artifacts
    const inv = player.inventory || [];
    for (const o of inv) {
      if (o !== otmp && o.oartifact) {
        const art2 = get_artifact(o);
        if (art2 !== artilist[ART_NONARTIFACT])
          spfx &= ~art2.cspfx;
      }
    }
  }

  // Map SPFX_ bits to property indices
  const spfxMap = [
    [SPFX_SEARCH, SEARCHING],
    [SPFX_ESP,    TELEPAT],
    [SPFX_STLTH,  STEALTH],
    [SPFX_REGEN,  REGENERATION],
    [SPFX_TCTRL,  TELEPORT_CONTROL],
    [SPFX_EREGEN, ENERGY_REGENERATION],
    [SPFX_HSPDAM, HALF_SPDAM],
    [SPFX_HPHDAM, HALF_PHDAM],
    [SPFX_PROTECT,PROTECTION],
    [SPFX_REFLECT,REFLECTING],  // only for W_WEP
  ];

  for (const [bit, prop] of spfxMap) {
    if (!(spfx & bit)) continue;
    // SPFX_REFLECT from artifact only applies when wielded
    if (bit === SPFX_REFLECT && !(wp_mask & W_WEP)) continue;
    const p = ensureProp(prop);
    if (p) {
      if (on) p.extrinsic |= wp_mask;
      else p.extrinsic &= ~wp_mask;
    }
    if (bit === SPFX_ESP && player) {
      player.ETelepat = player.uprops?.[TELEPAT]?.extrinsic || 0;
      recalc_telepat_range(player);
      see_monsters(player.map || null);
    }
  }

  // SPFX_WARN: warn_of_mon vs generic warning
  if (spfx & SPFX_WARN) {
    if (spec_m2(otmp)) {
      const p = ensureProp(WARN_OF_MON);
      if (p) {
        if (on) p.extrinsic |= wp_mask;
        else p.extrinsic &= ~wp_mask;
      }
    } else {
      const p = ensureProp(WARNING);
      if (p) {
        if (on) p.extrinsic |= wp_mask;
        else p.extrinsic &= ~wp_mask;
      }
    }
  }

  // SPFX_HALRES: hallucination resistance
  if (spfx & SPFX_HALRES) {
    const p = ensureProp(HALLUC_RES);
    if (p) {
      if (on) p.extrinsic |= wp_mask;
      else p.extrinsic &= ~wp_mask;
    }
  }

  // SPFX_XRAY
  if (spfx & SPFX_XRAY) {
    if (player) {
      player.xray_range = on ? 3 : -1;
    }
  }

  // Sunsword blindness resistance when wielded
  if (wp_mask === W_WEP && is_art(otmp, ART_SUNSWORD)) {
    // BLINDED property doesn't map directly; skip for now
    // In C this sets EBlnd_resist
  }

  // If dropping (W_ART removal) and artifact has inv_prop <= LAST_PROP that
  // is currently invoked, turn it off
  if (wp_mask === W_ART && !on && oart.inv_prop) {
    if (oart.inv_prop <= LAST_PROP && player && player.uprops) {
      const ip = player.uprops[oart.inv_prop];
      if (ip && (ip.extrinsic & W_ARTI)) {
        await arti_invoke(otmp, player);
      }
    }
  }
}

async function artifact_hit(magr, mdef, otmp, dmgptr, dieroll) {
  const youattack = !!(magr && magr.isPlayer);
  const youdefend = !!(mdef && mdef.isPlayer);
  const vis = (!youattack && magr && magr.mx !== undefined)
              || (!youdefend && mdef && mdef.mx !== undefined)
              || youattack;
  let realizes_damage;

  const hittee = youdefend ? 'you' : (mdef && mdef.name ? mdef.name : 'it');

  // spec_dbon handles most damage; returns [bonus, applies]
  const [bonus, spec_dbon_applies_val] = spec_dbon(otmp, mdef, dmgptr.value);
  dmgptr.value += bonus;

  if (youattack && youdefend) return false;

  realizes_damage = youdefend || vis || (youattack && mdef);

  // Fire
  if (attacks(AD_FIRE, otmp)) {
    if (realizes_damage) {
      const mdat = mdef.data || (mdef.mnum != null ? mons[mdef.mnum] : null);
      const action = !spec_dbon_applies_val ? 'hits'
        : (mdat && mdat.mndx === PM_WATER_ELEMENTAL) ? 'vaporizes part of'
        : 'burns';
      await pline_The("fiery blade %s %s%s", action, hittee, !spec_dbon_applies_val ? '.' : '!');
    }
    if (!rn2(4)) {
      // destroy_items / ignite_items not yet ported; consume RNG
    }
    return realizes_damage;
  }
  // Cold
  if (attacks(AD_COLD, otmp)) {
    if (realizes_damage) {
      await pline_The("ice-cold blade %s %s%s",
        !spec_dbon_applies_val ? 'hits' : 'freezes', hittee,
        !spec_dbon_applies_val ? '.' : '!');
    }
    if (!rn2(4)) {
      // destroy_items not yet ported
    }
    return realizes_damage;
  }
  // Elec
  if (attacks(AD_ELEC, otmp)) {
    if (realizes_damage) {
      await pline_The("massive hammer hits%s %s%s",
        !spec_dbon_applies_val ? '' : '!  Lightning strikes', hittee,
        !spec_dbon_applies_val ? '.' : '!');
    }
    if (!rn2(5)) {
      // destroy_items not yet ported
    }
    return realizes_damage;
  }
  // Magic missiles
  if (attacks(AD_MAGM, otmp)) {
    if (realizes_damage) {
      await pline_The("imaginary widget hits%s %s%s",
        !spec_dbon_applies_val ? '' : '!  A hail of magic missiles strikes',
        hittee, !spec_dbon_applies_val ? '.' : '!');
    }
    return realizes_damage;
  }

  // Magicbane special
  if (attacks(AD_STUN, otmp) && dieroll <= MB_MAX_DIEROLL) {
    return await Mb_hit(magr, mdef, otmp, dmgptr, dieroll, vis, hittee, spec_dbon_applies_val);
  }

  if (!spec_dbon_applies_val) return false;

  // Vorpal / Tsurugi beheading
  if (spec_ability(otmp, SPFX_BEHEAD)) {
    if (is_art(otmp, ART_TSURUGI_OF_MURAMASA) && dieroll === 1) {
      const wepdesc = 'The razor-sharp blade';
      if (!youdefend) {
        const mdat = mdef.data || (mdef.mnum != null ? mons[mdef.mnum] : null);
        if (mdat && (mdat.msize || 0) >= MZ_LARGE) {
          if (youattack) await You("slice deeply into %s!", hittee);
          else if (vis) await pline("%s cuts deeply into %s!", magr.name || 'It', hittee);
          dmgptr.value *= 2;
          return true;
        }
        dmgptr.value = 2 * mdef.mhp + FATAL_DAMAGE_MODIFIER;
        await pline("%s cuts %s in half!", wepdesc, hittee);
        return true;
      } else {
        // player is defender
        dmgptr.value *= 2;
        await pline("%s cuts deeply into you!", magr ? (magr.name || wepdesc) : wepdesc);
        return true;
      }
    } else if (is_art(otmp, ART_VORPAL_BLADE)
               && (dieroll === 1 || (mdef.data && mdef.data.mndx === PM_JABBERWOCK)
                   || (mdef.mnum === PM_JABBERWOCK))) {
      const wepdesc = artilist[ART_VORPAL_BLADE].name;
      if (!youdefend) {
        const mdat = mdef.data || (mdef.mnum != null ? mons[mdef.mnum] : null);
        if (!mdat || !has_head_simple(mdat)) {
          if (youattack) await pline("Somehow, you miss %s wildly.", hittee);
          else if (vis) await pline("Somehow, %s misses wildly.", magr.name || 'it');
          dmgptr.value = 0;
          return !!(youattack || vis);
        }
        if (noncorporeal_simple(mdat) || amorphous_simple(mdat)) {
          await pline("%s slices through %s's neck.", wepdesc, hittee);
          return true;
        }
        dmgptr.value = 2 * mdef.mhp + FATAL_DAMAGE_MODIFIER;
        await pline("%s beheads %s!", wepdesc, hittee);
        return true;
      } else {
        // player is defender — very lethal
        dmgptr.value = 2 * (mdef.mhp || mdef.hp || 0) + FATAL_DAMAGE_MODIFIER;
        await pline("%s beheads you!", wepdesc);
        return true;
      }
    }
  }

  // Drain life
  if (spec_ability(otmp, SPFX_DRLI)) {
    const mdat = mdef.data || (mdef.mnum != null ? mons[mdef.mnum] : null);
    const life = (mdat && nonliving_simple(mdat)) ? 'animating force' : 'life';
    if (!youdefend) {
      const m_lev = mdef.m_lev || 0;
      let drain = rnd(8); // monhp_per_lvl is usually 1d8
      if (mdef.mhpmax - drain <= m_lev)
        drain = (mdef.mhpmax > m_lev) ? (mdef.mhpmax - (m_lev + 1)) : 0;

      if (vis) {
        if (is_art(otmp, ART_STORMBRINGER))
          await pline_The("black blade draws the %s from %s!", life, hittee);
        else
          await pline("%s draws the %s from %s!", otmp.oname || 'The weapon', life, hittee);
      }
      if (m_lev === 0) {
        dmgptr.value = 2 * mdef.mhp + FATAL_DAMAGE_MODIFIER;
      } else {
        dmgptr.value += drain;
        mdef.mhpmax -= drain;
        mdef.m_lev--;
      }
      // Heal attacker
      if (drain > 0) {
        const healamt = ((drain + 1) / 2) | 0;
        if (youattack && magr) {
          if (magr.hp !== undefined) {
            magr.hp = Math.min(magr.hp + healamt, magr.hpmax || magr.hp + healamt);
          }
        } else if (magr) {
          magr.mhp = Math.min((magr.mhp || 0) + healamt, magr.mhpmax || magr.mhp + healamt);
        }
      }
      return vis;
    } else {
      // Player is the defender
      if (vis || youdefend) {
        if (is_art(otmp, ART_STORMBRINGER))
          await pline_The("black blade drains your %s!", life);
        else
          await pline("%s drains your %s!", otmp.oname || 'The weapon', life);
      }
      // losexp would go here for full implementation
      return true;
    }
  }

  return false;
}

async function drag_ball(x, y, allow_drag, player, map, game) {
    const uball = player.uball;
    const uchain = player.uchain;
    if (!uball || !uchain) return { ret: false, bc_control: 0, ballx: 0, bally: 0, chainx: 0, chainy: 0, cause_delay: false };

    let ballx = uball.ox;
    let bally = uball.oy;
    let chainx = uchain.ox;
    let chainy = uchain.oy;
    let bc_control = 0;
    let cause_delay = false;

    if (dist2(x, y, uchain.ox, uchain.oy) <= 2) { // nothing moved
        await move_bc(1, bc_control, ballx, bally, chainx, chainy, player, map);
        return { ret: true, bc_control, ballx, bally, chainx, chainy, cause_delay };
    }

    // only need to move the chain?
    if (carried(uball) || distmin(x, y, uball.ox, uball.oy) <= 2) {
        const oldchainx = uchain.ox, oldchainy = uchain.oy;

        bc_control = BC_CHAIN;
        await move_bc(1, bc_control, ballx, bally, chainx, chainy, player, map);
        if (carried(uball)) {
            // move chain only if necessary
            if (distmin(x, y, uchain.ox, uchain.oy) > 1) {
                chainx = player.x;
                chainy = player.y;
            }
            return { ret: true, bc_control, ballx, bally, chainx, chainy, cause_delay };
        }

        // Check if chain would be in rock
        let already_in_rock;
        if (IS_CHAIN_ROCK(player.x, player.y, map) || IS_CHAIN_ROCK(chainx, chainy, map)
            || IS_CHAIN_ROCK(uball.ox, uball.oy, map))
            already_in_rock = true;
        else
            already_in_rock = false;

        // SKIP_TO_DRAG helper — restore chain and jump to drag section
        let skip_to_drag = false;
        async function SKIP_TO_DRAG() {
            chainx = oldchainx;
            chainy = oldchainy;
            await move_bc(0, bc_control, ballx, bally, chainx, chainy, player, map);
            skip_to_drag = true;
        }

        switch (dist2(x, y, uball.ox, uball.oy)) {
        // two spaces diagonal from ball, move chain in-between
        case 8:
            chainx = Math.floor((uball.ox + x) / 2);
            chainy = Math.floor((uball.oy + y) / 2);
            if (IS_CHAIN_ROCK(chainx, chainy, map) && !already_in_rock)
                await SKIP_TO_DRAG();
            break;

        // player is distance 2/1 from ball
        case 5: {
            let tempx, tempy, tempx2, tempy2;

            if (Math.abs(x - uball.ox) === 1) {
                tempx = x;
                tempx2 = uball.ox;
                tempy = tempy2 = Math.floor((uball.oy + y) / 2);
            } else {
                tempx = tempx2 = Math.floor((uball.ox + x) / 2);
                tempy = y;
                tempy2 = uball.oy;
            }
            if (IS_CHAIN_ROCK(tempx, tempy, map) && !IS_CHAIN_ROCK(tempx2, tempy2, map)
                && !already_in_rock) {
                if (allow_drag) {
                    if (dist2(player.x, player.y, uball.ox, uball.oy) === 5
                        && dist2(x, y, tempx, tempy) === 1)
                        await SKIP_TO_DRAG();
                    if (!skip_to_drag && dist2(player.x, player.y, uball.ox, uball.oy) === 4
                        && dist2(x, y, tempx, tempy) === 2)
                        await SKIP_TO_DRAG();
                }
                if (!skip_to_drag) {
                    chainx = tempx2;
                    chainy = tempy2;
                }
            } else if (!skip_to_drag && !IS_CHAIN_ROCK(tempx, tempy, map)
                       && IS_CHAIN_ROCK(tempx2, tempy2, map) && !already_in_rock) {
                if (allow_drag) {
                    if (dist2(player.x, player.y, uball.ox, uball.oy) === 5
                        && dist2(x, y, tempx2, tempy2) === 1)
                        await SKIP_TO_DRAG();
                    if (!skip_to_drag && dist2(player.x, player.y, uball.ox, uball.oy) === 4
                        && dist2(x, y, tempx2, tempy2) === 2)
                        await SKIP_TO_DRAG();
                }
                if (!skip_to_drag) {
                    chainx = tempx;
                    chainy = tempy;
                }
            } else if (!skip_to_drag && IS_CHAIN_ROCK(tempx, tempy, map)
                       && IS_CHAIN_ROCK(tempx2, tempy2, map) && !already_in_rock) {
                await SKIP_TO_DRAG();
            } else if (!skip_to_drag) {
                if (dist2(tempx, tempy, uchain.ox, uchain.oy)
                        < dist2(tempx2, tempy2, uchain.ox, uchain.oy)
                    || ((dist2(tempx, tempy, uchain.ox, uchain.oy)
                         === dist2(tempx2, tempy2, uchain.ox, uchain.oy))
                        && rn2(2))) {
                    chainx = tempx;
                    chainy = tempy;
                } else {
                    chainx = tempx2;
                    chainy = tempy2;
                }
            }
            break;
        }

        // ball is two spaces horizontal or vertical from player
        case 4:
            if (!CHAIN_IN_MIDDLE(uchain.ox, uchain.oy, x, y, uball))
                ;  // fall through to set chain position
            else break;
            chainx = Math.floor((x + uball.ox) / 2);
            chainy = Math.floor((y + uball.oy) / 2);
            if (IS_CHAIN_ROCK(chainx, chainy, map) && !already_in_rock)
                await SKIP_TO_DRAG();
            break;

        // ball is one space diagonal from player
        case 2:
            if (dist2(x, y, uball.ox, uball.oy) === 2
                && dist2(x, y, uchain.ox, uchain.oy) === 4) {
                if (uchain.oy === y)
                    chainx = uball.ox;
                else
                    chainy = uball.oy;
                if (IS_CHAIN_ROCK(chainx, chainy, map) && !already_in_rock)
                    await SKIP_TO_DRAG();
                break;
            }
            // FALLTHROUGH
            // eslint-disable-next-line no-fallthrough
        case 1:
        case 0:
            // do nothing if possible
            if (CHAIN_IN_MIDDLE(uchain.ox, uchain.oy, x, y, uball))
                break;
            // otherwise try to drag chain to player's old position
            if (CHAIN_IN_MIDDLE(player.x, player.y, x, y, uball)) {
                chainx = player.x;
                chainy = player.y;
                break;
            }
            // otherwise use player's new position
            chainx = x;
            chainy = y;
            break;

        default:
            impossible("bad chain movement");
            break;
        }

        if (!skip_to_drag) {
            return { ret: true, bc_control, ballx, bally, chainx, chainy, cause_delay };
        }

        // Fall through to drag section
    }

    // drag:
    if (near_capacity(player) > SLT_ENCUMBER && dist2(x, y, player.x, player.y) <= 2) {
        await You("cannot %sdrag the heavy iron ball.",
            (player.inventory && player.inventory.length) ? "carry all that and also " : "");
        nomul(0, game);
        return { ret: false, bc_control, ballx, bally, chainx, chainy, cause_delay };
    }

    if ((is_pool(uchain.ox, uchain.oy, map)
         // water not mere continuation of previous water
         && (map.at(uchain.ox, uchain.oy).typ === POOL
             || !is_pool(uball.ox, uball.oy, map)
             || map.at(uball.ox, uball.oy).typ === POOL))
        || ((() => { const t = t_at(uchain.ox, uchain.oy, map);
                     return t && (is_pit(t.ttyp) || is_hole(t.ttyp)); })())
    ) {
        if (player.levitating || player.levitation) {
            await You_feel("a tug from the iron ball.");
            const t = t_at(uchain.ox, uchain.oy, map);
            if (t) t.tseen = 1;
        } else {
            await You("are jerked back by the iron ball!");
            const victim = map.monsterAt ? map.monsterAt(uchain.ox, uchain.oy) : null;
            if (victim) {
                const dieroll = rnd(20);
                let tmp = -2 + Luck(player) + (typeof victim.findMac === 'function' ? victim.findMac() : 10);
                // omon_adj not wired; skip for now
                // tmp += omon_adj(victim, uball, true);

                if (tmp >= dieroll) {
                    // hmon(victim, uball, HMON_DRAGGED, dieroll) — combat not wired for ball drag
                } else {
                    // miss(xname(uball), victim) — miss message not wired
                }
            }
            // now check again in case mon died
            const still_there = map.monsterAt ? map.monsterAt(uchain.ox, uchain.oy) : null;
            if (!still_there) {
                player.x0 = player.x;
                player.y0 = player.y;
                player.x = uchain.ox;
                player.y = uchain.oy;
                newsym(player.x0, player.y0);
            }
            nomul(0, game);

            bc_control = BC_BALL;
            await move_bc(1, bc_control, ballx, bally, chainx, chainy, player, map);
            ballx = uchain.ox;
            bally = uchain.oy;
            await move_bc(0, bc_control, ballx, bally, chainx, chainy, player, map);
            await spoteffects(true, player, map, null, game);
            return { ret: false, bc_control, ballx, bally, chainx, chainy, cause_delay };
        }
    }

    bc_control = BC_BALL | BC_CHAIN;

    await move_bc(1, bc_control, ballx, bally, chainx, chainy, player, map);
    if (dist2(x, y, player.x, player.y) > 2) {
        // Teleported more than one square — just put everything at target.
        ballx = chainx = x;
        bally = chainy = y;
    } else {
        let newchainx = player.x, newchainy = player.y;

        if (dist2(x, y, uchain.ox, uchain.oy) === 4
            && !IS_CHAIN_ROCK(newchainx, newchainy, map)) {
            newchainx = Math.floor((x + uchain.ox) / 2);
            newchainy = Math.floor((y + uchain.oy) / 2);
            if (IS_CHAIN_ROCK(newchainx, newchainy, map)) {
                newchainx = player.x;
                newchainy = player.y;
            }
        }

        ballx = uchain.ox;
        bally = uchain.oy;
        chainx = newchainx;
        chainy = newchainy;
    }
    cause_delay = true;
    return { ret: true, bc_control, ballx, bally, chainx, chainy, cause_delay };
}

