        if (game.multi) context.mv = true;
        return await domove(DIRECTION_KEYS[c], player, map, display, game);
    }

    // Run keys (capital letter = run in that direction)
    if (RUN_KEYS[c]) {
        // C ref: cmd.c:3808 — F prefix only valid before movement commands
