    case RIN_SEE_INVISIBLE:
        toggle_extrinsic(player, SEE_INVIS, false);
        mark_vision_dirty();
        if (!player.blind) {
            await learnring(ring, true);
        }
        break;
    case RIN_INVISIBILITY:
        toggle_extrinsic(player, INVIS, false);
        if (!player.blind) {
            await learnring(ring, true);
        }
        break;
    case RIN_LEVITATION:
        toggle_extrinsic(player, LEVITATION, false);
        // C ref: float_down(0L, 0L);
        await learnring(ring, true);
        break;
    case RIN_GAIN_STRENGTH:
        adj_abon(player, ring, A_STR, -(ring.spe || 0));
        break;
    case RIN_GAIN_CONSTITUTION:
        adj_abon(player, ring, A_CON, -(ring.spe || 0));
        break;
    case RIN_ADORNMENT:
        adj_abon(player, ring, A_CHA, -(ring.spe || 0));
        break;
    case RIN_INCREASE_ACCURACY:
        player.uhitinc = (player.uhitinc || 0) - (ring.spe || 0);
        break;
    case RIN_INCREASE_DAMAGE:
        player.udaminc = (player.udaminc || 0) - (ring.spe || 0);
        break;
    case RIN_PROTECTION_FROM_SHAPE_CHAN:
        toggle_extrinsic(player, PROT_FROM_SHAPE_CHANGERS, false);
        break;
    case RIN_PROTECTION:
        toggle_extrinsic(player, PROTECTION, false);
        await learnring(ring, (ring.spe || 0) !== 0);
        if (ring.spe) find_ac(player);
        break;
    }
}

async function canwearobj(player, obj, display, silent = false) {
    const sub = objectData[obj.otyp]?.oc_subtyp;
    const slot = ARMOR_SLOTS[sub];
    if (!slot) return false;
    const mdat = player?.data || player?.polyData || null;
    const verysmall = !!mdat && ((mdat.msize || 0) < MZ_SMALL);
    const cantWear = !!mdat && cantweararm(mdat);
    const wearingThisArmor = !!(obj.owornmask & W_ARMOR);
    const weapon = player?.weapon || null;
    const bimanualWep = !!(weapon && objectData[weapon.otyp]?.oc_bimanual);
    const weldedWep = !!(weapon && weapon.cursed);
    const isFlimsy = (o) => Number(objectData[o?.otyp]?.oc_material || 0) <= LEATHER;

    // C: verysmall/nohands gate
    if (verysmall || (!!mdat && nohands(mdat))) {
        if (!silent) await You("can't wear any armor in your current form.");
        return false;
    }

    // C: cantweararm body-fit gate for suit/shirt/cloak with cloak exception.
    const isSuit = sub === ARM_SUIT;
    const isShirt = sub === ARM_SHIRT;
    const isCloak = sub === ARM_CLOAK;
    if ((isSuit || isShirt || isCloak) && cantWear) {
        const wrappingAllowed = !!mdat && is_humanoid(mdat);
        const isCloakAllowedException = isCloak
            && ((obj.otyp !== MUMMY_WRAPPING && !!mdat && (mdat.msize === MZ_SMALL))
                || (obj.otyp === MUMMY_WRAPPING && wrappingAllowed));
        if (!isCloakAllowedException) {
            if (!silent) await pline("The %s will not fit on your body.", slot.name);
            return false;
        }
    } else if (wearingThisArmor) {
        if (!silent) await You('are already wearing that!');
        return false;
    }

    // C: welded two-handed weapon blocks suit/shirt.
    if (weldedWep && bimanualWep && (isSuit || isShirt)) {
        if (!silent) await You('cannot do that while holding your weapon.');
        return false;
    }

    // Slot-specific prechecks in C order.
    if (sub === ARM_HELM) {
        if (player.helmet) {
            if (!silent) await You('are already wearing %s.', helm_simple_name(player.helmet));
            return false;
        }
        if (!!mdat && has_horns(mdat) && !isFlimsy(obj)) {
            if (!silent) await pline("The %s won't fit over your horns.", armor_simple_name(obj));
            return false;
        }
        return true;
    }

    if (sub === ARM_SHIELD) {
        if (player.shield) {
            if (!silent) await You('are already wearing a shield.');
            return false;
        }
        if (weapon && bimanualWep) {
            if (!silent) await You('cannot wear a shield while wielding a two-handed weapon.');
            return false;
        }
        if (player.twoweap) {
            if (!silent) await You('cannot wear a shield while wielding two weapons.');
            return false;
        }
        return true;
    }

    if (sub === ARM_BOOTS) {
        if (player.boots) {
            if (!silent) await You('are already wearing %s.', boots_simple_name(player.boots));
            return false;
        }
        if (!!mdat && slithy(mdat)) {
            if (!silent) await You('have no feet...');
            return false;
        }
        if (!!mdat && mdat.mlet === S_CENTAUR) {
            if (!silent) await You('have too many hooves to wear boots.');
            return false;
        }
        if (player.utrap && (player.utraptype === TT_BEARTRAP || player.utraptype === TT_LAVA || player.utraptype === TT_INFLOOR || player.utraptype === TT_BURIEDBALL)) {
            if (!silent) {
                if (player.utraptype === TT_BEARTRAP) {
                    await Your('foot is trapped!');
                } else if (player.utraptype === TT_LAVA || player.utraptype === TT_INFLOOR) {
                    await Your('feet are stuck!');
                } else {
                    await Your('leg is attached to the buried ball!');
                }
            }
            return false;
        }
        return true;
    }

    if (sub === ARM_GLOVES) {
        if (player.gloves) {
            if (!silent) await You('are already wearing %s.', gloves_simple_name(player.gloves));
            return false;
        }
        if (weldedWep) {
            if (!silent) await You('cannot wear gloves over your weapon.');
            return false;
        }
        if (player.glib) {
            if (!silent) await pline('Your fingers are too slippery to pull on those gloves.');
            return false;
        }
        return true;
    }

    if (sub === ARM_SHIRT) {
        if (player.armor || player.cloak || player.shirt) {
            if (!silent) {
                if (player.shirt) await You('are already wearing a shirt.');
                else if (player.armor && !player.cloak) await You_cant('wear that over your armor.');
                else await You_cant('wear that over your %s.', cloak_simple_name(player.cloak));
            }
            return false;
        }
        return true;
    }

    if (sub === ARM_CLOAK) {
        if (player.cloak) {
            if (!silent) await You('are already wearing %s.', cloak_simple_name(player.cloak));
            return false;
        }
        return true;
    }

    if (sub === ARM_SUIT) {
        if (player.cloak) {
            if (!silent) await You('cannot wear armor over a %s.', cloak_simple_name(player.cloak));
            return false;
        }
        if (player.armor) {
            if (!silent) await You('are already wearing some armor.');
            return false;
        }
        return true;
    }

    if (!silent) {
        await silly_thing('wear', obj);
        return false;
    }
    return false;
}

async function handleRemoveAll(player, display, game = null) {
    // C ref: doddoremarm checks context.takeoff for in-progress disrobing first
    // (not applicable in JS since we don't have persistent occupation state here)

    // C ref: check if anything is worn/wielded at all
    if (!player.weapon && !player.swapWeapon && !player.quiver
        && !player.amulet && !player.blindfold
        && !player.leftRing && !player.rightRing && !wearing_armor(player)) {
        await You("are not wearing anything.");
        return { moved: false, tookTime: false };
    }

    // Collect all worn/wielded items (matching is_worn filter)
    const wornSet = new Set();
    if (player.weapon) wornSet.add(player.weapon);
    if (player.swapWeapon) wornSet.add(player.swapWeapon);
    if (player.quiver) wornSet.add(player.quiver);
    for (const obj of getWornArmorItems(player)) wornSet.add(obj);
    for (const obj of getWornAccessoryItems(player)) wornSet.add(obj);
    const wornAll = (player.inventory || []).filter(obj => wornSet.has(obj));

    if (wornAll.length === 0) {
        await You("are not wearing anything.");
        return { moved: false, tookTime: false };
    }

    // C class labels used by query_category (matching C def_inv_order)
    const CLASS_LABEL = {
        [WEAPON_CLASS]: 'Weapons', [ARMOR_CLASS]: 'Armor', [RING_CLASS]: 'Rings',
        [AMULET_CLASS]: 'Amulets', [TOOL_CLASS]: 'Tools', [FOOD_CLASS]: 'Comestibles',
        [POTION_CLASS]: 'Potions', [SCROLL_CLASS]: 'Scrolls', [SPBOOK_CLASS]: 'Spellbooks',
        [WAND_CLASS]: 'Wands', [COIN_CLASS]: 'Coins', [GEM_CLASS]: 'Gems/Stones',
    };
    const INV_ORDER = [COIN_CLASS, AMULET_CLASS, WEAPON_CLASS, ARMOR_CLASS, FOOD_CLASS,
        SCROLL_CLASS, SPBOOK_CLASS, POTION_CLASS, RING_CLASS, WAND_CLASS, TOOL_CLASS,
        GEM_CLASS, ROCK_CLASS, BALL_CLASS, CHAIN_CLASS];

    // Count worn item categories (cf. query_category ccount)
    const wornClasses = new Set(wornAll.map(o => o.oclass));
    const ccount = wornClasses.size;

    // Phase 1: query_category — category selection
    // C ref: pickup.c:1288 "no point in actually showing a menu for a single category"
    // When ccount==1, skip the category menu entirely (C returns the single class immediately)
    let selectedClasses = null; // null = all categories
    if (ccount > 1) {
        // Build category menu overlay (cf. C query_category with WORN_TYPES|ALL_TYPES|BUCX_TYPES)
        const catLines = ["What type of things do you want to take off?", ""];
        catLines.push("a - All worn and wielded types");

        let autoChar = 'b'.charCodeAt(0);
        const catMap = new Map(); // char → class set
        for (const cls of INV_ORDER) {
            if (!wornClasses.has(cls)) continue;
            const label = CLASS_LABEL[cls] || 'Other';
            const ch = String.fromCharCode(autoChar);
            catLines.push(ch + " - " + label);
            catMap.set(ch, cls);
            autoChar++;
            if (autoChar > 'z'.charCodeAt(0)) autoChar = 'A'.charCodeAt(0);
        }

        // BUC entries (only shown if any worn item has that status)
        const bucLines = [];
        if (wornAll.some(o => o.bknown && o.blessed))               bucLines.push("B - Items known to be Blessed");
        if (wornAll.some(o => o.bknown && o.cursed))                 bucLines.push("C - Items known to be Cursed");
        if (wornAll.some(o => o.bknown && !o.blessed && !o.cursed))  bucLines.push("U - Items known to be Uncursed");
        if (wornAll.some(o => !o.bknown))                            bucLines.push("X - Items of unknown B/C/U status");
        if (bucLines.length > 0) {
            catLines.push("", ...bucLines);
        }
        catLines.push("(end)");

        // Show category menu as PICK_ANY overlay
        const catAllowedChars = 'a' + [...catMap.keys()].join('') + 'BUCX';
        const catResult = await renderOverlayMenuUntilDismiss(display, catLines, catAllowedChars);
        if (!catResult) {
            // Dismissed without selection
            return { moved: false, tookTime: false };
        }
        if (catResult !== 'a') {
            // Specific category selected
            const selCls = catMap.get(catResult);
            if (selCls != null) {
                selectedClasses = new Set([selCls]);
            }
            // BUC filter selections (B/C/U/X) — not fully implemented, treat as all
        }
    }

    // Phase 2: query_objlist — item selection
    // C ref: query_objlist("What do you want to take off?", ..., PICK_ANY, is_worn/is_worn_by_type)
    // Build item overlay grouped by class
    const filteredItems = selectedClasses
        ? wornAll.filter(o => selectedClasses.has(o.oclass))
        : wornAll;

    if (filteredItems.length === 0) {
        await pline("There is nothing else you can remove or unwield.");
        return { moved: false, tookTime: false };
    }

    const itemLines = ["What do you want to take off?", ""];
    let lastClass = -1;
    for (const obj of filteredItems) {
        if (obj.oclass !== lastClass) {
            const label = CLASS_LABEL[obj.oclass] || 'Other';
            if (lastClass !== -1) itemLines.push(""); // blank line between sections
            itemLines.push(label);
            lastClass = obj.oclass;
        }
        const name = doname(obj, player);
        itemLines.push(`${obj.invlet} - ${name}`);
    }
    itemLines.push("(end)");

    const itemAllowedChars = filteredItems.map(o => o.invlet).join('');
    const itemResult = await renderOverlayMenuUntilDismiss(display, itemLines, itemAllowedChars);
    if (!itemResult) {
        // Dismissed without selection
        return { moved: false, tookTime: false };
    }

    const item = filteredItems.find(o => o.invlet === itemResult);
    if (!item) {
        return { moved: false, tookTime: false };
    }

    // Handle weapon slots via setuwep/setuswapwep/setuqwep (cf. do_takeoff W_WEP/W_SWAPWEP/W_QUIVER)
    if (item === player.weapon) {
        if (welded(item, player)) {
            await You("can't. It is cursed.");
            item.bknown = true;
            return { moved: false, tookTime: false };
        }
        const wasTwoweap = player.twoweap;
        setuwep(player, null);
        if (wasTwoweap) await You("are no longer wielding either weapon.");
        else await You("are %s.", empty_handed(player));
        return { moved: false, tookTime: true };
    }
    if (item === player.swapWeapon) {
        const wasTwoweap = player.twoweap;
        setuswapwep(player, null);
        await You("%sno longer %s.", wasTwoweap ? "are " : "",
            wasTwoweap ? "wielding two weapons at once" : "have a second weapon readied");
        return { moved: false, tookTime: true };
    }
    if (item === player.quiver) {
        setuqwep(player, null);
        await You("no longer have ammunition readied.");
        return { moved: false, tookTime: true };
    }

    // Armor or accessory — use existing removal path
    return await removeArmorOrAccessory(player, display, game, item);
}

function dogfood(mon, obj, moves) {
    const mptr = monPtr(mon);
    if (!mptr) return APPORT;
    const carni = carnivorous(mptr);
    const herbi = herbivorous(mptr);
    if (hasPoisonTrapBit(obj) && !resists_poison(mon))
        return POISON;

    if (is_quest_artifact(obj) || obj_resists(obj, 0, 95))
        return obj.cursed ? TABU : APPORT;

    if (obj.oclass === FOOD_CLASS) {
        const fx = (obj.otyp === CORPSE || obj.otyp === TIN || obj.otyp === EGG)
            ? (obj.corpsenm !== undefined ? obj.corpsenm : NON_PM)
            : NON_PM;
        const fptr = ismnum(fx) ? mons[fx] : null;

        if (obj.otyp === CORPSE && fptr && is_rider(fptr))
            return TABU;

        if ((obj.otyp === CORPSE || obj.otyp === EGG)
            && fptr && flesh_petrifies(fptr)
            && !resists_ston(mon))
            return POISON;

        if (obj.otyp === LUMP_OF_ROYAL_JELLY
            && mptr === mons[PM_KILLER_BEE]) {
            return TABU;
        }

        if (!carni && !herbi)
            return obj.cursed ? UNDEF : APPORT;

        const starving = !!(mon.mtame && !mon.isminion
                           && mon.edog && mon.edog.mhpmax_penalty);
        const mblind = false;

        if (monIndex(mon) === PM_GHOUL) {
            if (obj.otyp === CORPSE) {
                const corpseAge = peek_at_iced_corpse_age(obj);
                return (corpseAge + 50 <= (moves || 0)
                        && fx !== PM_LIZARD && fx !== PM_LICHEN) ? DOGFOOD
                    : (starving && fptr && !mon_vegan(fptr)) ? ACCFOOD
                    : POISON;
            }
            if (obj.otyp === EGG)
                return starving ? ACCFOOD : POISON;
            return TABU;
        }

        switch (obj.otyp) {
        case TRIPE_RATION:
        case MEATBALL:
        case MEAT_RING:
        case MEAT_STICK:
        case ENORMOUS_MEATBALL:
            return carni ? DOGFOOD : MANFOOD;

        case EGG:
            if (fx === PM_PYROLISK && !likes_fire(mptr))
                return POISON;
            return carni ? CADAVER : MANFOOD;

        case CORPSE: {
            const corpseAge = peek_at_iced_corpse_age(obj);
            if ((corpseAge + 50 <= (moves || 0)
                 && fx !== PM_LIZARD && fx !== PM_LICHEN
                 && mptr.mlet !== S_FUNGUS)
                || (fptr && acidic(fptr) && !resists_acid(mon))
                || (fptr && poisonous(fptr) && !resists_poison(mon)))
                return POISON;
            else if (polyfood(obj) && mon.mtame > 1 && !starving)
                return MANFOOD;
            else if (fptr && mon_vegan(fptr))
                return herbi ? CADAVER : MANFOOD;
            else if (humanoid(mptr) && fptr && same_race(mptr, fptr)
                     && !is_undead(mptr) && fptr.mlet !== S_KOBOLD
                     && fptr.mlet !== S_ORC && fptr.mlet !== S_OGRE)
                return (starving && carni && !is_elf(mptr)) ? ACCFOOD : TABU;
            else
                return carni ? CADAVER : MANFOOD;
        }

        case GLOB_OF_GREEN_SLIME:
            return (starving || slimeproof(mptr)) ? ACCFOOD : POISON;

        case CLOVE_OF_GARLIC:
            return is_undead(mptr) ? TABU
                : (herbi || starving) ? ACCFOOD
                : MANFOOD;

        case TIN:
            return is_metallivore(mptr) ? ACCFOOD : MANFOOD;

        case APPLE:
            return herbi ? DOGFOOD : starving ? ACCFOOD : MANFOOD;

        case CARROT:
            return (herbi || mblind) ? DOGFOOD : starving ? ACCFOOD : MANFOOD;

        case BANANA:
            return (mptr.mlet === S_YETI && herbi) ? DOGFOOD
                : (herbi || starving) ? ACCFOOD
                : MANFOOD;

        default:
            if (starving) return ACCFOOD;
            return (obj.otyp > SLIME_MOLD) ? (carni ? ACCFOOD : MANFOOD)
                                           : (herbi ? ACCFOOD : MANFOOD);
        }
    }

    if (obj.oclass === ROCK_CLASS)
        return UNDEF;

    if (obj.otyp === AMULET_OF_STRANGULATION
        || obj.otyp === RIN_SLOW_DIGESTION)
        return TABU;

    if (mon_hates_silver(mon)
        && objectData[obj.otyp].oc_material === SILVER)
        return TABU;

    if (monIndex(mon) === PM_GELATINOUS_CUBE && is_organic(obj))
        return ACCFOOD;

    if (is_metallivore(mptr) && is_metallic(obj)
        && (is_rustprone(obj) || monIndex(mon) !== PM_RUST_MONSTER)) {
        return (is_rustprone(obj) && !obj.oerodeproof) ? DOGFOOD : ACCFOOD;
    }

    if (!obj.cursed
        && obj.oclass !== BALL_CLASS
        && obj.oclass !== CHAIN_CLASS)
        return APPORT;

    return UNDEF;
}

