async function handleInventory(player, display, game) {
    if (player.inventory.length === 0 && (player.gold || 0) <= 0) {
        await display.putstr_message('Not carrying anything.');
        return { moved: false, tookTime: false };
    }

    const win = create_nhwindow(NHW_MENU);
    try {
    const lines = buildInventoryOverlayLines(player);
    const pageRows = Number.isInteger(display?.rows) ? display.rows : STATUS_ROW_1;
    const pages = buildInventoryPages(lines, pageRows);
    let pageIndex = 0;

    const fullScreenInventory = pages.length > 1;
    await drawInventoryPage(display, pages[pageIndex] || [], { fullScreen: fullScreenInventory });
    const invByLetter = new Map();
    for (const item of player.inventory || []) {
        if (item?.invlet) invByLetter.set(String(item.invlet), item);
    }
    const clearTopline = () => {
        if (typeof display.clearRow === 'function') display.clearRow(0);
        if (display && Object.hasOwn(display, 'topMessage')) display.topMessage = null;
        if (display && Object.hasOwn(display, 'messageNeedsMore')) display.messageNeedsMore = false;
    };
    // C tty/menu parity: inventory stays up until an explicit dismissal key.
    // Non-dismiss keys can be consumed without closing the menu frame.
    while (true) {
        const ch = await nhgetch();
        // C tty parity: space advances pages when present; otherwise it
        // dismisses the inventory only at the end of the final page.
        if (ch === 32) {
            if (pageIndex + 1 < pages.length) {
                pageIndex++;
                await drawInventoryPage(display, pages[pageIndex] || [], { fullScreen: fullScreenInventory });
                continue;
            }
            break;
        }
        if (ch === 62) { // '>'
            if (pageIndex + 1 < pages.length) {
                pageIndex++;
                await drawInventoryPage(display, pages[pageIndex] || [], { fullScreen: fullScreenInventory });
            }
            continue;
        }
        if (ch === 98 && pageIndex > 0) { // b
            pageIndex--;
            await drawInventoryPage(display, pages[pageIndex] || [], { fullScreen: fullScreenInventory });
            continue;
        }
        if (ch === 60 && pageIndex > 0) { // '<'
            pageIndex--;
            await drawInventoryPage(display, pages[pageIndex] || [], { fullScreen: fullScreenInventory });
            continue;
        }
        if (ch === 94 && pageIndex > 0) { // '^'
            pageIndex = 0;
            await drawInventoryPage(display, pages[pageIndex] || [], { fullScreen: fullScreenInventory });
            continue;
        }
        if (ch === 124 && pageIndex + 1 < pages.length) { // '|'
            pageIndex = pages.length - 1;
            await drawInventoryPage(display, pages[pageIndex] || [], { fullScreen: fullScreenInventory });
            continue;
        }
        if (ch === 27 || ch === 10 || ch === 13) break;
        const c = String.fromCharCode(ch);
        if (c === ':') {
            // C tty menu parity: ':' enters in-menu incremental search.
            // We keep menu rows in place and update only topline prompt text.
            await getlin('Search for: ', display);
            continue;
        }
        const pageLines = pages[pageIndex] || [];
        const visibleLetters = new Set(
            pageLines
                .map((line) => {
                    const m = String(line || '').match(/^\s*([a-zA-Z])\s+-\s+/);
                    return m ? m[1] : null;
                })
                .filter(Boolean)
        );
        const selected = visibleLetters.has(c) ? invByLetter.get(c) : null;
        if (selected) {
            const baseName = xname({ ...selected, quan: 1 });
            const noun = xname(selected);
            const lowerBaseName = baseName.toLowerCase();
            const isLightSource = (
                lowerBaseName === 'oil lamp'
                || lowerBaseName === 'brass lantern'
                || lowerBaseName === 'magic lamp'
                || lowerBaseName === 'wax candle'
                || lowerBaseName === 'tallow candle'
            );
            const isRubbableLamp = (lowerBaseName === 'oil lamp' || lowerBaseName === 'magic lamp');
            const isWornArmor = (
                selected === player.armor
                || selected === player.shield
                || selected === player.helmet
                || selected === player.gloves
                || selected === player.boots
                || selected === player.cloak
            );
            const stackCanShoot = ammoAndLauncher(selected, player.weapon);
            // C ref: engrave menu uses surface(u.ux, u.uy) for "floor"/"stairs"/etc.
            const _map = game?.map || game?.lev;
            const _loc = _map?.at?.(player.x, player.y);
            const _surfName = (_loc?.typ === STAIRS || _loc?.typ === LADDER)
                ? 'stairs' : (_loc?.typ === ROOM ? 'floor' : 'ground');
            let menuOffx = 34;
            const displayCols = Number.isInteger(display.cols) ? display.cols : COLNO;
            if (typeof display.setCell === 'function'
                && Number.isInteger(displayCols)
                && Number.isInteger(display.rows)) {
                let maxcol = 0;
                for (const line of lines) {
                    if (line.length > maxcol) maxcol = line.length;
                }
                menuOffx = Math.max(10, displayCols - maxcol - 2);
            }
            const rawActions = ((selected.quan || 1) > 1)
                ? (() => {
                    const stackUsesThrowMenu = (selected.oclass === WEAPON_CLASS
                        || selected.otyp === FLINT
                        || selected.otyp === ROCK);
                    if (stackUsesThrowMenu) {
                        const actions = [];
                        if (selected === player.quiver) {
                            actions.push("- - Quiver '-' to un-ready these items");
                        }
                        actions.push(`c - Name this stack of ${noun}`);
                        actions.push('d - Drop this stack');
                        actions.push('E - Write on the ground with one of these items');
                        actions.push(stackCanShoot
                            ? `f - Shoot one of these with your wielded ${xname({ ...player.weapon, quan: 1 })}`
                            : 'f - Throw one of these');
                        actions.push('i - Adjust inventory by assigning new letter');
                        actions.push('I - Adjust inventory by splitting this stack');
                        if (selected.otyp === FLINT || selected.otyp === ROCK) {
                            actions.push('R - Rub something on this stone');
                        }
                        actions.push(stackCanShoot
                            ? "t - Shoot one of these (same as 'f')"
                            : "t - Throw one of these (same as 'f')");
                        actions.push('w - Wield this stack in your hands');
                        actions.push('/ - Look up information about these');
                        actions.push('(end)');
                        return actions;
                    }
                    if (selected.oclass === POTION_CLASS) {
                        return [
                            'a - Dip something into one of these potions',
                            `c - Name this stack of ${noun}`,
                            `C - Call the type for ${noun}`,
                            'd - Drop this stack',
                            'i - Adjust inventory by assigning new letter',
                            'I - Adjust inventory by splitting this stack',
                            'q - Quaff (drink) one of these potions',
                            't - Throw one of these',
                            'w - Wield this stack in your hands',
                            '/ - Look up information about these',
                            '(end)',
                        ];
                    }
                    const actions = [
                        `c - Name this stack of ${noun}`,
                        'd - Drop this stack',
                        'i - Adjust inventory by assigning new letter',
                        'I - Adjust inventory by splitting this stack',
                        't - Throw one of these',
                        'w - Wield this stack in your hands',
                        '/ - Look up information about these',
                        '(end)',
                    ];
                    if (selected.oclass === FOOD_CLASS) {
                        actions.splice(2, 0, 'e - Eat one of these');
                    }
                    return actions;
                })()
                : (selected.oclass === SPBOOK_CLASS
                    ? [
                        `c - Name this specific ${noun}`,
                        'd - Drop this item',
                        'i - Adjust inventory by assigning new letter',
                        'r - Study this spellbook',
                        't - Throw this item',
                        'w - Wield this item in your hands',
                        '/ - Look up information about this',
                        '(end)',
                    ]
                : ((selected === player.weapon && selected.oclass === WEAPON_CLASS)
                    ? [
                        "- - Wield '-' to un-wield this weapon",
                        `c - Name this specific ${noun}`,
                        'd - Drop this item',
                        `E - Engrave on the ${_surfName} with this item`,
                        'i - Adjust inventory by assigning new letter',
                        "Q - Quiver this item for easy throwing with 'f'ire",
                        't - Throw this item',
                        'x - Ready this as an alternate weapon',
                        '/ - Look up information about this',
                        '(end)',
                    ]
                    : (isWornArmor
                        ? [
                            `c - Name this specific ${noun}`,
                            'i - Adjust inventory by assigning new letter',
                            'T - Take off this armor',
                            '/ - Look up information about this',
                            '(end)',
                        ]
                        : (selected.oclass === WAND_CLASS
                        ? [
                            'a - Break this wand',
                            `c - Name this specific ${noun}`,
                            'd - Drop this item',
                            `E - Engrave on the ${_surfName} with this item`,
                            'i - Adjust inventory by assigning new letter',
                            't - Throw this item',
                            'w - Wield this item in your hands',
                            'z - Zap this wand to release its magic',
                            '/ - Look up information about this',
                            '(end)',
                        ]
                        : (selected.oclass === WEAPON_CLASS
                        ? [
                            `c - Name this specific ${noun}`,
                            'd - Drop this item',
                            `E - Write on the ${_surfName} with this item`,
                            'i - Adjust inventory by assigning new letter',
                            "Q - Quiver this item for easy throwing with 'f'ire",
                            't - Throw this item',
                            'w - Wield this item as your weapon',
                            '/ - Look up information about this',
                            '(end)',
                        ]
                    : [
                        ...(selected.otyp === MAGIC_MARKER
                            ? ['a - Write on something with this marker']
                            : isLightSource
                            ? [selected.lamplit
                                ? 'a - Snuff out this light source'
                                : 'a - Light this light source']
                            : selected.oclass === POTION_CLASS
                            ? ['a - Dip something into this potion']
                            : baseName.toLowerCase() === 'stethoscope'
                            ? ['a - Listen through the stethoscope']
                            : []),
                        `c - Name this specific ${noun}`,
                        ...(selected.oclass === POTION_CLASS
                            ? [`C - Call the type for ${noun}s`]
                            : []),
                        'd - Drop this item',
                        ...(selected.otyp === MAGIC_MARKER
                            ? ['E - Scribble graffiti on the floor']
                            : []),
                        'i - Adjust inventory by assigning new letter',
                        ...(isRubbableLamp ? [`R - Rub this ${noun}`] : []),
                        ...(selected.oclass === POTION_CLASS
                            ? ['q - Quaff (drink) this potion']
                            : []),
                        ...(selected.oclass === SCROLL_CLASS
                            ? ['r - Read this scroll to activate its magic']
                            : []),
                        't - Throw this item',
                        'w - Wield this item in your hands',
                        '/ - Look up information about this',
                        '(end)',
                    ])))));
            const promptText = `Do what with the ${noun}?`;
            const maxAction = rawActions.reduce((m, line) => Math.max(m, line.length), promptText.length);
            menuOffx = Math.max(10, displayCols - maxAction - 2);
            const pad = ' '.repeat(menuOffx);
            const stackActions = rawActions.map((line) => `${pad}${line}`);
            const actionPrompt = `${pad}${promptText}`;
            if (typeof display.setCell === 'function'
                && Number.isInteger(display.cols)
                && Number.isInteger(display.rows)) {
                if (game && typeof display.renderMap === 'function' && game.map && game.u && game.fov) {
                    display.renderMap(game.map, game.u, game.fov, game.flags || {});
                    if (fullScreenInventory && typeof display.clearRow === 'function') {
                        if (Number.isInteger(STATUS_ROW_1)) display.clearRow(STATUS_ROW_1);
                        if (Number.isInteger(STATUS_ROW_2)) display.clearRow(STATUS_ROW_2);
                    }
                } else {
                    display.clearScreen();
                }
            }
            if (typeof display.putstr === 'function' && typeof display.clearRow === 'function') {
                display.clearRow(0);
                await display.putstr(0, 0, pad, 7, 0);
                await display.putstr(menuOffx, 0, promptText, 7, 1);
                if (display && Object.hasOwn(display, 'topMessage')) display.topMessage = actionPrompt;
                if (display && Object.hasOwn(display, 'messageNeedsMore')) display.messageNeedsMore = false;
            } else {
                await display.putstr_message(actionPrompt);
            }
            if (typeof display.putstr === 'function') {
                for (let i = 0; i < stackActions.length; i++) {
                    if (typeof display.clearRow === 'function') display.clearRow(i + 2);
                    await display.putstr(0, i + 2, stackActions[i]);
                }
                // C ref: tty clears any inventory overflow at STATUS_ROW_1/2
                // when showing the "Do what with X?" prompt. renderMap redraws
                // rows 1-21 but NOT the status rows (22-23), which may still
                // hold lingering inventory items. Only clear those rows.
                if (typeof display.clearRow === 'function'
                    && Number.isInteger(STATUS_ROW_1) && Number.isInteger(STATUS_ROW_2)) {
                    display.clearRow(STATUS_ROW_1);
                    display.clearRow(STATUS_ROW_2);
                }
            }
            const actionKeys = new Set(rawActions.map((line) => String(line || '').charAt(0)));
            while (true) {
                const actionCh = await nhgetch();
                if (actionCh === 32 || actionCh === 27 || actionCh === 10 || actionCh === 13) {
                    if (typeof display.clearRow === 'function') {
                        for (let i = 0; i < stackActions.length; i++) {
                            display.clearRow(i + 2);
                        }
                    }
                    clearTopline();
                    return { moved: false, tookTime: false };
                }
                const actionKey = String.fromCharCode(actionCh);
                if (!actionKeys.has(actionKey)) continue;
                if (typeof display.clearRow === 'function') {
                    for (let i = 0; i < stackActions.length; i++) {
                        display.clearRow(i + 2);
                    }
                }
                clearTopline();
                if ((actionKey === 'f' || actionKey === 't') && game?.map) {
                    return await promptDirectionAndThrowItem(
                        player,
                        (game.map || game.map),
                        display,
                        selected,
                        { fromFire: stackCanShoot, game }
                    );
                }
                if (actionKey === 'i') {
                    // cf. invent.c doorganize() / #adjust — reassign inventory letter
                    await docrt();
                    const inv = player.inventory || [];
                    const usedLetters = new Set(inv.map(o => o.invlet));
                    // Build available-letter string for prompt
                    const allLetters = 'abcdefghijklmnopqrstuvwxyzABCDEFGHIJKLMNOPQRSTUVWXYZ';
                    let availStr = '';
                    {
                        let i = 0;
                        while (i < allLetters.length) {
                            const ch = allLetters[i];
                            if (!usedLetters.has(ch) || ch === selected.invlet) {
                                // Find run of consecutive available letters
                                let j = i;
                                while (j + 1 < allLetters.length
                                    && (!usedLetters.has(allLetters[j + 1]) || allLetters[j + 1] === selected.invlet)) {
                                    j++;
                                }
                                if (availStr) availStr += '';
                                if (j - i >= 2) {
                                    availStr += `${allLetters[i]}-${allLetters[j]}`;
                                } else {
                                    for (let k = i; k <= j; k++) availStr += allLetters[k];
                                }
                                i = j + 1;
                            } else {
                                i++;
                            }
                        }
                    }
                    const adjustPrompt = `Adjust letter to what [${availStr}] (? see used letters)?`;
                    await display.putstr_message(adjustPrompt);
                    const adjCh = await nhgetch();
                    const adjChar = String.fromCharCode(adjCh);
                    if (adjCh === 27 || adjCh === 10 || adjCh === 13 || adjCh === 32) {
                        clearTopline();
                        await display.putstr_message('Never mind.');
                        return { moved: false, tookTime: false };
                    }
                    if (/^[a-zA-Z]$/.test(adjChar)) {
                        // Swap if another item has that letter
                        const other = inv.find(o => o !== selected && o.invlet === adjChar);
                        if (other) {
                            other.invlet = selected.invlet;
                        }
                        selected.invlet = adjChar;
                    }
                    clearTopline();
                    return { moved: false, tookTime: false };
                }
                if (actionKey === 'c') {
                    await docrt();
                    const namedInput = await getlin(`What do you want to name this ${baseName}? `, display);
                    if (namedInput !== null) {
                        const nextName = namedInput.trim();
                        selected.oname = nextName;
                    }
                    clearTopline();
                }
                return { moved: false, tookTime: false };
            }
        }
        // C tty parity for plain inventory view: non-navigation keys which do
        // not select a visible inventory letter are ignored.
        continue;
    }
    clearTopline();
    // C ref: wintty.c erase_menu_or_text — fullscreen inventory dismiss
    // calls docrt() to restore the map. During hallucination, docrt's
    // newsym loop consumes display RNG for hallucinated cells.
    if (fullScreenInventory) {
        await docrt();
    }

    return { moved: false, tookTime: false };
    } finally {
        destroy_nhwindow(win);
    }
}

async function getobj(word, obj_ok, flags = 0, player = null) {
    const p = player || _gstate?.u || null;
    const display = _gstate?.display || null;
    if (!p || typeof obj_ok !== 'function') return null;

    const inv = p.inventory || [];

    // Categorize items using the obj_ok callback (C ref: invent.c:2098-2158)
    const suggested = [];
    const downplay = [];
    const allValid = []; // items the player CAN select (suggested + downplay + exclude_selectable)
    for (const obj of inv) {
        const result = obj_ok(obj);
        if (result === GETOBJ_SUGGEST) {
            suggested.push(obj);
            allValid.push(obj);
        } else if (result === GETOBJ_DOWNPLAY) {
            downplay.push(obj);
            allValid.push(obj);
        } else if (result === GETOBJ_EXCLUDE_SELECTABLE) {
            allValid.push(obj);
        }
    }

    // No selectable items at all
    if (allValid.length === 0 && suggested.length === 0) return null;

    // C ref: auto-select if exactly one GETOBJ_SUGGEST item, no downplay items,
    // and GETOBJ_PROMPT flag is not set (invent.c:2215-2230)
    if (suggested.length === 1 && downplay.length === 0 && !(flags & GETOBJ_PROMPT)) {
        return suggested[0];
    }

    // No display available — fall back to simple selection
    if (!display) return getobj_simple(word, obj_ok, p);

    // Interactive prompt via nhgetch (C ref: invent.c:2232-2370)
    // C only shows SUGGEST items in the prompt bracket; DOWNPLAY items are
    // accepted but hidden from the choice string (invent.c:2233-2240).
    const suggestedLetters = suggested.map(o => o.invlet).join('');
    const choices = compactInvletPromptChars(suggestedLetters);
    const prompt = choices
        ? `What do you want to ${word}? [${choices} or ?*] `
        : `What do you want to ${word}? [*] `;
    const allInvLetters = allValid.filter(o => o?.invlet).map(o => o.invlet).join('');
    const clearPrompt = () => {
        if (typeof display.clearRow === 'function') display.clearRow(0);
        display.topMessage = null;
        display.messageNeedsMore = false;
    };

    // C ref: invent.c:1935 — getobj uses yn_function() which renders the prompt
    // directly on the topline via tty_putstr, truncated at screen width.
    // Use putstr() instead of putstr_message() to avoid word-wrapping long prompts.
    if (display.messageNeedsMore) {
        const { more } = await import('./display.js');
        await more(display, { forceVisual: true });
    }
    // C ref: invent.c:1935 — getobj uses yn_function(qbuf, NULL, '\0') which
    // renders via custompline → tty_putstr. Long prompts wrap at the screen
    // edge (character boundary), not at word boundaries like putstr_message.
    // Render directly via putstr to match C's wrapping behavior.
    if (display.messageNeedsMore) {
        const { more } = await import('./display.js');
        await more(display, { forceVisual: true });
    }
    display.clearRow(0);
    if (typeof display.clearRow === 'function' && display._topMessageRow1 !== undefined) {
        display.clearRow(1);
        display._topMessageRow1 = undefined;
    }
    display.messageNeedsMore = false;
    display.topMessage = null;
    const promptCols = display.cols || 80;
    if (prompt.length >= promptCols) {
        // C ref: update_topl wraps at CO-1 (79 for 80-col screen).
        const wrapAt = promptCols - 1;
        await display.putstr(0, 0, prompt.substring(0, wrapAt), 7);
        const row1 = prompt.substring(wrapAt);
        await display.putstr(0, 1, row1, 7);
        display._topMessageRow1 = row1;
        if (typeof display.setCursor === 'function') {
            display.setCursor(Math.min(row1.length, promptCols - 1), 1);
        }
    } else {
        await display.putstr(0, 0, prompt, 7);
        if (typeof display.setCursor === 'function') {
            display.setCursor(Math.min(prompt.length, promptCols - 1), 0);
        }
    }

    enterModal('getobj');
    try {
    while (true) {
        const ch = await nhgetch();
        const c = String.fromCharCode(ch);

        // ESC / Enter / Space = cancel
        // C ref: invent.c:2367-2370 — pline1("Never mind.") on ESC
        if (ch === 27 || ch === 10 || ch === 13 || c === ' ') {
            clearPrompt();
            await display.putstr_message('Never mind.');
            return null;
        }

        // '?' or '*' = show inventory overlay
        if (c === '?' || c === '*') {
            clearPrompt();
            const includeSyntheticGold = allValid.some((o) => o?.oclass === COIN_CLASS);
            const lines = buildInventoryOverlayLinesFromItems(allValid, p, { includeSyntheticGold });
            const menuSelection = await renderOverlayMenuUntilDismiss(
                display, lines, allInvLetters
            );
            if (menuSelection) {
                const item = inv.find(o => o.invlet === menuSelection);
                if (item) {
                    clearPrompt();
                    return item;
                }
            }
            // Re-show prompt after overlay dismissal
            await display.putstr_message(prompt);
            continue;
        }

        // Try to find inventory item by letter
        const item = inv.find(o => o.invlet === c);
        if (!item) {
            // C ref: invent.c:2304 — pline("You don't have that object.")
            // C's pline concatenates with the getobj prompt (toplin=NEED_MORE).
            // If overflow → more() blocks. If fits → concatenated with --More-- indicator.
            // Either way, the player must press a key to continue.
            await pline("You don't have that object.");
            // C ref: display_nhwindow(WIN_MESSAGE, FALSE) — force --More-- dismiss
            // even when the concatenated message fit on one line.
            const _winMsg = getWinMessage();
            if (_winMsg != null) await display_nhwindow(_winMsg, false);
            clearPrompt();
            await display.putstr_message(prompt);
            continue;
        }

        // C ref: invent.c:getobj() sets disp.botl = TRUE before validating the
        // chosen inventory letter, so rejection feedback can still force a
        // message-side flush.
        markGetobjSelectionBoundary(p);
        const okResult = obj_ok(item);
        if (okResult === GETOBJ_EXCLUDE) {
            clearPrompt();
            await silly_thing(word, item);
            return null;
        }

        // Found a valid inventory item — clear prompt and return
        clearPrompt();
        return item;
    }
    } finally {
        exitModal('getobj');
    }
}

async function display_pickinv(lets, xtra_choice, query, allowxtra, want_reply, out_cnt,
    player = null, display = null, options = null) {
    const p = player || _gstate?.u || null;
    const d = display || _gstate?.display || null;
    if (!p || !d) return '';
    const wizIdentify = !!options?.wizardIdentify;
    const wizIdentifyAccel = Number.isInteger(options?.wizIdentifyAccel)
        ? (options.wizIdentifyAccel | 0)
        : 9;

    // C ref: invent.c display_pickinv() calls reset_justpicked(gi.invent)
    // to clear pickup_prev flags when inventory is displayed
    if (p.inventory) {
        for (const obj of p.inventory) {
            if (obj) obj.pickup_prev = 0;
        }
    }

    if (wizIdentify) {
        const inv = Array.isArray(p.inventory) ? p.inventory : [];
        const unid = inv.filter((obj) => obj && not_fully_identified(obj));
        const lines = [];
        const choices = [];

        const hasUnid = unid.length > 0;
        lines.push(hasUnid
            ? `Debug Identify -- unidentified or partially identified item${unid.length !== 1 ? 's' : ''}`
            : 'Debug Identify');

        if (unid.length === 0) {
            lines.push('(all items are permanently identified already)');
            await renderOverlayMenuUntilDismiss(d, lines, '', { noTitleInverse: true });
            return '';
        }

        let identifyLine = `_ - select ${unid.length === 1 ? 'it' : 'any or all of them'} to permanently identify`;
        if (unid.length > 1) {
            identifyLine += ` (${visctrl(wizIdentifyAccel)} for all)`;
        }
        lines.push(identifyLine);
        choices.push('_');
        choices.push(String.fromCharCode(wizIdentifyAccel));

        const groupedLines = buildInventoryOverlayLinesFromItems(unid, p, {
            fullyIdentify: true,
            includeSyntheticGold: false,
        })
            .filter((line) => line !== '(end)');
        lines.push(...groupedLines);
        for (const obj of unid) {
            const invlet = String(obj.invlet || '');
            if (!invlet) continue;
            choices.push(invlet);
        }
        const result = await renderOverlayMenuPickAny(
            d,
            (selected) => lines.map((line) => {
                const match = String(line).match(/^([A-Za-z_]) - (.*)$/);
                if (!match) return line;
                return `${match[1]} ${selected.has(match[1]) ? '+' : '-'} ${match[2]}`;
            }),
            choices.join(''),
            {
                noTitleInverse: true,
                skipInvertSelections: ['_', String.fromCharCode(wizIdentifyAccel)],
            }
        );
        if (result === null) return '';
        if (result.includes('_') || result.includes(String.fromCharCode(wizIdentifyAccel))) {
            await identify_pack(0, p, false, true);  // C ref: identify_pack(0, FALSE) uses credit_hero=TRUE
            return '';
        }
        if (result.length > 0) {
            for (const invlet of result) {
                const target = unid.find((obj) => String(obj?.invlet || '') === invlet);
                if (target && not_fully_identified(target)) {
                    // C ref: invent.c:3398 — identify(otmp) calls
                    // fully_identify_obj → makeknown(otyp) = discover_object
                    // with credit_hero=TRUE, which fires exercise(A_WIS, TRUE)
                    // when a type is newly discovered.
                    await fully_identify_obj(target, true);
                }
            }
            update_inventory(p);
        }
        return '';
    }

    const objects = display_inventory_items(lets, p);
    const lines = [];
    const choices = [];
    const choiceSet = new Set();

    if (typeof query === 'string' && query.length > 0) {
        lines.push(query);
    }

    for (const obj of objects) {
        const invlet = String(obj?.invlet || '');
        if (!invlet) continue;
        const line = xprname(obj, null, invlet, true, 0, 0, p);
        lines.push(line);
        if (!choiceSet.has(invlet)) {
            choiceSet.add(invlet);
            choices.push(invlet);
        }
    }

    const allowExtraChoice = !!(allowxtra && xtra_choice);
    if (allowExtraChoice) {
        lines.push(`- - ${String(xtra_choice)}`);
        if (!choiceSet.has('-')) {
            choiceSet.add('-');
            choices.push('-');
        }
    }

    if (lines.length === 0) {
        await d.putstr_message('Not carrying anything.');
        if (out_cnt && typeof out_cnt === 'object') out_cnt.value = -1;
        return '';
    }

    const result = await renderOverlayMenuUntilDismiss(
        d,
        lines,
        want_reply ? choices.join('') : '',
        { allowCountPrefix: !!want_reply }
    );
    const selection = selectionFromInventoryResult(result);
    const count = countFromInventoryResult(result);
    if (out_cnt && typeof out_cnt === 'object') {
        out_cnt.value = Number.isFinite(count) ? count : -1;
    }
    return selection;
}

async function pick_lock(game, pick, rx, ry, container) {
    const { u: player, map, display } = game;
    const xlock = getXlock(game);
    const PICKLOCK_LEARNED_SOMETHING = -1;
    const PICKLOCK_DID_NOTHING = 0;
    const PICKLOCK_DID_SOMETHING = 1;

    const picktyp = pick ? pick.otyp : 0;
    const autounlock = (rx !== 0 || container != null);

    // Check whether we're resuming an interrupted previous attempt
    if (xlock.usedtime && picktyp === xlock.picktyp) {
        const action = lock_action(game);
        await You(`resume your attempt at ${action}.`);
        xlock.magic_key = false; // simplified: is_magic_key not available here
        game.occupation = {
            occtxt: action,
            fn: await makePicklockOccupation(game),
        };
        xlock._isPicklock = true;
        return PICKLOCK_DID_SOMETHING;
    }

    if (pick && picktyp !== SKELETON_KEY && picktyp !== LOCK_PICK
        && picktyp !== CREDIT_CARD) {
        return PICKLOCK_DID_NOTHING;
    }

    let ch = 0;
    let ccx, ccy;

    if (rx !== 0) {
        // autounlock — caller provided coordinates
        ccx = rx;
        ccy = ry;
    } else {
        // Prompt for direction
        await display.putstr_message('In what direction? ');
        const dirCh = await nhgetch();
        display.topMessage = null;
        const c = String.fromCharCode(dirCh);
        let dir = DIRECTION_KEYS[c];
        if (!dir && (dirCh === 10 || dirCh === 13)) dir = DIRECTION_KEYS.j;
        if (!dir && (c === '.' || c === 's')) dir = [0, 0];
        if (!dir) {
            return PICKLOCK_DID_NOTHING;
        }
        // C ref: get_adjacent_loc() → getdir() → confdir() for confused direction
        player.dx = dir[0];
        player.dy = dir[1];
        confdir(false, player);
        ccx = player.x + player.dx;
        ccy = player.y + player.dy;
    }

    if (ccx === player.x && ccy === player.y) {
        // Pick lock on a container at hero's location
        const floorObjs = map.objectsAt(player.x, player.y) || [];
        let found = false;
        let count = 0;

        for (const otmp of floorObjs) {
            if (autounlock && otmp !== container) continue;
            if (!Is_box(otmp)) continue;
            count++;

            let verb;
            let it = false;
            if (otmp.obroken) {
                verb = 'fix';
            } else if (!otmp.olocked) {
                verb = 'lock'; it = true;
            } else if (picktyp !== LOCK_PICK) {
                verb = 'unlock'; it = true;
            } else {
                verb = 'pick';
            }

            if (!autounlock) {
                let itemName = doname(otmp);
                // C object naming includes container lock-state adjectives in
                // this prompt (for example, "an unlocked chest").
                if (it && !otmp.olocked && Is_box(otmp) && !otmp.obroken && otmp.lknown
                    && !/\bunlocked\b/i.test(itemName)) {
                    itemName = itemName.replace(/^(an?|the)\s+/i, 'an unlocked ');
                }
                const qbuf = `There is ${itemName} here; ${verb} ${it ? 'it' : 'its lock'}?`;
                otmp.lknown = true;
                const ansCode = await ynFunction(qbuf, 'ynq', 'q'.charCodeAt(0), display);
                const ansChar = String.fromCharCode(ansCode);
                if (ansChar === 'q') return PICKLOCK_DID_NOTHING;
                if (ansChar === 'n') continue;
            } else {
                // autounlock — simplified: proceed directly
                if (!pick) return PICKLOCK_DID_NOTHING;
                const qbuf = `Unlock it with ${yname(pick)}?`;
                const ansCode = await ynFunction(qbuf, 'ynq', 'q'.charCodeAt(0), display);
                if (String.fromCharCode(ansCode) !== 'y') return PICKLOCK_DID_NOTHING;
            }

            if (otmp.obroken) {
                await You_cant(`fix its broken lock with ${doname(pick)}.`);
                return PICKLOCK_LEARNED_SOMETHING;
            } else if (picktyp === CREDIT_CARD && !otmp.olocked) {
                await You_cant("do that with a credit card.");
                return PICKLOCK_LEARNED_SOMETHING;
            }

            const dex = acurr(player, A_DEX);
            const isRogue = Role_if(player, PM_ROGUE) ? 1 : 0;
            switch (picktyp) {
            case CREDIT_CARD:
                ch = dex + 20 * isRogue;
                break;
            case LOCK_PICK:
                ch = 4 * dex + 25 * isRogue;
                break;
            case SKELETON_KEY:
                ch = 75 + dex;
                break;
            default:
                ch = 0;
            }
            if (otmp.cursed) ch = Math.floor(ch / 2);

            xlock.box = otmp;
            xlock.door = null;
            found = true;
            break;
        }

        if (!found) {
            if (!count) {
                await There("doesn't seem to be any sort of lock here.");
            }
            return PICKLOCK_LEARNED_SOMETHING;
        }

    } else {
        // Pick lock on an adjacent door
        const loc = map.at(ccx, ccy);

        const mtmp = map.monsterAt(ccx, ccy);
        if (mtmp && mtmp.m_ap_type !== M_AP_FURNITURE && mtmp.m_ap_type !== M_AP_OBJECT) {
            if (picktyp === CREDIT_CARD
                && (mtmp.isshk || mtmp.data?.mname === 'Oracle')) {
                await verbalize("No checks, no credit, no problem.");
            } else {
                await pline(`I don't think ${mon_nam(mtmp)} would appreciate that.`);
            }
            return PICKLOCK_LEARNED_SOMETHING;
        }

        if (!loc || !IS_DOOR(loc.typ)) {
            await You("see no door there.");
            return PICKLOCK_DID_NOTHING;
        }

        switch (loc.flags) {
        case D_NODOOR:
            await pline("This doorway has no door.");
            return PICKLOCK_LEARNED_SOMETHING;
        case D_ISOPEN:
            await You("cannot lock an open door.");
            return PICKLOCK_LEARNED_SOMETHING;
        case D_BROKEN:
            await pline("This door is broken.");
            return PICKLOCK_LEARNED_SOMETHING;
        default:
            // credit cards are only good for unlocking
            if (picktyp === CREDIT_CARD && !(loc.flags & D_LOCKED)) {
                await You_cant("lock a door with a credit card.");
                return PICKLOCK_LEARNED_SOMETHING;
            }

            const lockStr = (loc.flags & D_LOCKED) ? 'Unlock' : 'Lock';
            const qbuf = autounlock
                ? `${lockStr} it with ${yname(pick)}?`
                : `${lockStr} it?`;
            const ansCode = await ynFunction(qbuf, 'ynq', 'q'.charCodeAt(0), display);
            if (String.fromCharCode(ansCode) !== 'y') {
                return PICKLOCK_DID_NOTHING;
            }

            const dex = acurr(player, A_DEX);
            const isRogue = Role_if(player, PM_ROGUE) ? 1 : 0;
            switch (picktyp) {
            case CREDIT_CARD:
                ch = 2 * dex + 20 * isRogue;
                break;
            case LOCK_PICK:
                ch = 3 * dex + 30 * isRogue;
                break;
            case SKELETON_KEY:
                ch = 70 + dex;
                break;
            default:
                ch = 0;
            }
            xlock.door = loc;
            xlock.box = null;
        }
    }

    xlock.chance = ch;
    xlock.picktyp = picktyp;
    xlock.magic_key = false; // simplified
    xlock.usedtime = 0;
    xlock._isPicklock = true;
    xlock._targetX = ccx;
    xlock._targetY = ccy;

    const action = lock_action(game);
    game.occupation = {
        occtxt: action,
        fn: await makePicklockOccupation(game),
    };
    return PICKLOCK_DID_SOMETHING;
}

