async function mattacku(monster, player, display, game = null, opts = {}) {
    assertNotInModal('mattacku');
    if (!monster.attacks || monster.attacks.length === 0) return;
    if (monster.passive) return; // passive monsters don't initiate attacks

    const map = opts.map || null;
    const attackVars = calc_mattacku_vars(monster, player);
    let range2 = (opts.range2 !== undefined) ? !!opts.range2 : !!attackVars.range2;
    let foundyou = !!attackVars.foundyou;
    const firstfoundyou = foundyou;
    let skipnonmagc = false;
    const sum = new Array(6).fill(M_ATTK_MISS); // C NATTK == 6
    const combatState = { skipdrin: false };
    const postAttackTail = (attackResult) => {
        // C ref: mhitu.c:936-942 — successful attack can wake sleeping hero.
        const wakeEligible = attackResult === M_ATTK_HIT
            && Number(player?.usleep || 0) > 0
            && Number.isFinite(game?.moves)
            && Number(player.usleep) < Number(game.moves);
        if (wakeEligible && !rn2(10)) {
            if (game) {
                game.multi = -1;
                game.nomovemsg = 'The combat suddenly awakens you.';
            }
        }
        return !!(attackResult & (M_ATTK_AGR_DIED | M_ATTK_AGR_DONE));
    };

    // C ref: mhitu.c:mattacku() — melee-capable attackers stop hero running
    // before any hit messaging and mark botl dirty via nomul(0).
    if (!range2 && game) {
        nomul(0, game);
    }

    // C ref: mhitu.c:527-546 — mounted hero: attackers may target steed.
    if (player?.usteed) {
        if (monster === player.usteed) {
            // Your steed won't attack you.
            return false;
        }
        const mdat = monster.data || monster.type || {};
        if (!rn2(is_orc(mdat) ? 2 : 4) && m_next2u(monster, player)) {
            const vis = !player?.blind;
            const mmCtx = {
                player,
                map,
                turnCount: game?.moves ?? game?.turnCount ?? 0,
            };
            const steed = player.usteed;
            const steedAttack = await mattackm(monster, steed, display, vis, map, mmCtx);
            if (steedAttack & M_ATTK_AGR_DIED) return true;
            if ((steedAttack & M_ATTK_DEF_DIED) || !player.usteed || !m_next2u(monster, player)) {
                return false;
            }
            return !!((await mattackm(player.usteed, monster, display, vis, map, mmCtx)) & M_ATTK_DEF_DIED);
        }
    }

    // C ref: mhitu.c:755-761 — Unlike defensive stuff, don't let them use item _and_ attack.
    if (map && await find_offensive(monster, map, player)) {
        const offended = await use_offensive(monster, map, player);
        if (offended !== 0)
            return offended === 1 ? true : undefined;
    }

    for (let i = 0; i < 6; i++) {
        // C ref: only actual death/game-over should stop mattacku mid-pass.
        // Life-saving does not abort the current monster-attack stream.
        if (game?.playerDied || game?.gameOver) {
            break;
        }
        if (opts.range2 === undefined && i > 0) {
            const vars = calc_mattacku_vars(monster, player);
            range2 = !!vars.range2;
            foundyou = !!vars.foundyou;
            // C ref: mhitu.c:778 — avoid wildmiss spam after initial foundyou.
            if (firstfoundyou && !foundyou) {
                sum[i] = M_ATTK_MISS;
                continue;
            }
        }
        const attack = getmattk(monster, player, i, sum);
        if (!attack) continue;
        if (attack.aatyp === AT_NONE) continue;
        if (combatState.skipdrin && attack.adtyp === AD_DRIN) continue;
        if (skipnonmagc && attack.aatyp !== AT_MAGC) continue;

        // cf. mhitu.c mattacku() attack dispatch:
        // Melee attacks (AT_CLAW, AT_BITE, etc.) only fire when !range2.
        // AT_WEAP: melee when !range2, thrwmu when range2.
        // AT_BREA, AT_SPIT, AT_MAGC: ranged-only handlers.
        if (range2) {
            if (attack.aatyp === AT_WEAP) {
                // cf. mhitu.c:882-885 — AT_WEAP at range calls thrwmu
                sum[i] = map ? (await thrwmu(monster, map, player, display, game)) : M_ATTK_MISS;
                if (!Number.isInteger(sum[i])) sum[i] = M_ATTK_MISS;
                if (postAttackTail(sum[i])) break;
                continue;
            }
            if (attack.aatyp === AT_SPIT) {
                sum[i] = map ? (await spitmu(monster, attack, map, player, display, game)) : M_ATTK_MISS;
                if (!Number.isInteger(sum[i])) sum[i] = M_ATTK_MISS;
                if (postAttackTail(sum[i])) break;
                continue;
            }
            if (attack.aatyp === AT_BREA) {
                sum[i] = map ? (await breamu(monster, attack, map, player, display, game)) : M_ATTK_MISS;
                if (!Number.isInteger(sum[i])) sum[i] = M_ATTK_MISS;
                if (postAttackTail(sum[i])) break;
                continue;
            }
            if (attack.aatyp === AT_MAGC) {
                if (map) {
                    sum[i] = await buzzmu(monster, attack, player, map);
                    if (!Number.isInteger(sum[i])) sum[i] = M_ATTK_MISS;
                    if (postAttackTail(sum[i])) break;
                }
                continue;
            }
            // Skip melee-only attack types when at range
            continue;
        }

        if (attack.aatyp === AT_MAGC) {
            const vis = !player?.blind && !(monster.minvis && !player?.seeInvisible);
            sum[i] = await castmu(monster, attack, vis, foundyou, player, map);
            if (!Number.isInteger(sum[i])) sum[i] = M_ATTK_MISS;
            if (postAttackTail(sum[i])) break;
            continue;
        }

        // C ref: mhitu.c:830-835 — AT_GAZE can affect you either ranged or not.
        // Medusa gaze already operated through m_respond in dochug().
        if (attack.aatyp === AT_GAZE) {
            const mdat = monster.data || monster.type || {};
            if (mdat.mndx !== PM_MEDUSA) {
                sum[i] = await gazemu(monster, attack, player, map, display);
                if (!Number.isInteger(sum[i])) sum[i] = M_ATTK_MISS;
                if (postAttackTail(sum[i])) break;
            }
            continue;
        }

        // C ref: mhitu.c:837-840 — AT_EXPL is automatic hit if next to.
        // No to-hit roll needed; goes directly to explmu().
        if (attack.aatyp === AT_EXPL) {
            if (!range2) {
                sum[i] = await explmu(monster, attack, foundyou, player, map, display);
                if (!Number.isInteger(sum[i])) sum[i] = M_ATTK_MISS;
                if (postAttackTail(sum[i])) break;
            }
            continue;
        }

        const suppressHitMsg = !!(game && game._suppressMonsterHitMessagesThisTurn);

        // ================================================================
        // To-hit calculation (mattacku path)
        // ================================================================
        // cf. mhitu.c:707-716 — tmp = AC_VALUE(u.uac) + 10 + mtmp->m_lev,
        // then apply state modifiers and clamp to at least 1.
        // cf. AC_VALUE(ac) macro: ac >= 0 ? ac : -rnd(-ac)
        const playerAc = Number.isInteger(player.ac)
            ? player.ac
            : (Number.isInteger(player.effectiveAC) ? player.effectiveAC : 10);
        const acValue = (playerAc >= 0) ? playerAc : -rnd(-playerAc);
        const mdat = monster.data || monster.type || {};
        const heroInvis = !!(player?.Invis || player?.invis || playerHasProp(player, INVIS));
        const monCanSee = (monster?.mcansee !== 0 && monster?.mcansee !== false);
        let toHit = acValue + 10 + (monster.mlevel || 0);
        if ((game?.multi || 0) < 0) toHit += 4;
        if ((heroInvis && !perceives(mdat)) || !monCanSee) toHit -= 2;
        if (monster?.mtrapped) toHit -= 2;
        if (toHit <= 0) toHit = 1;

        if (!foundyou) {
            clear_hitmsg_state();
            await wildmiss(monster, attack, player, display);
            skipnonmagc = true;
            continue;
        }
        if (attack.aatyp === AT_WEAP) {
            // C ref: mhitu.c AT_WEAP melee branch — monsters can still spend
            // this turn wielding before any hit-roll RNG is consumed.
            if ((monster.weapon_check === NEED_WEAPON || !monster.weapon)) {
                monster.weapon_check = NEED_HTH_WEAPON;
                if (await mon_wield_item(monster) !== 0) {
                    sum[i] = M_ATTK_MISS;
                    continue;
                }
            }
        }
        if (attack.aatyp === AT_WEAP && monster.weapon) {
            // C ref: mhitu.c:905-907 — add temporary hitval bonus for this strike.
            toHit += weaponHitval(monster.weapon, player);
            await maybeMonsterWeaponSwingMessage(monster, player, display, suppressHitMsg);
        }

        const dieRoll = rnd(20 + i);
        mhituTrace(
            game,
            `tohit mon=${monster?.m_id ?? 0} mndx=${monster?.mndx ?? -1} i=${i} `
            + `aatyp=${attack?.aatyp ?? -1} adtyp=${attack?.adtyp ?? -1} `
            + `toHit=${toHit} die=${dieRoll} ac=${playerAc} acv=${acValue} `
            + `mlev=${monster?.mlevel ?? 0} multi=${game?.multi ?? 0} `
            + `heroInvis=${heroInvis ? 1 : 0} perceives=${perceives(mdat) ? 1 : 0} `
            + `mcansee=${monCanSee ? 1 : 0} mtrapped=${monster?.mtrapped ? 1 : 0}`
        );
        if (toHit <= dieRoll) {
            // Miss — cf. mhitu.c:86-98 missmu()
            clear_hitmsg_state();
            if (map && !canSpotMonsterForMap(monster, map, player, game?.fov || null)) {
                map_invisible(map, monster.mx, monster.my, player);
            }
            if (!suppressHitMsg) {
                const verbose = !!(game?.flags?.verbose);
                const just = (toHit === dieRoll && verbose) ? 'just ' : '';
                await display.putstr_message(`${Monnam(monster)} ${just}misses!`);
            }
            // C ref: missmu() ends with unconditional stop_occupation().
            if (game) {
                if (typeof game.stopOccupation === 'function') await game.stopOccupation();
                else game.occupation = null;
            }
            sum[i] = M_ATTK_MISS;
            continue;
        }

        // ================================================================
        // Hit! — hitmu() equivalent
        // ================================================================

        if (map && !canSpotMonsterForMap(monster, map, player, game?.fov || null)) {
            map_invisible(map, monster.mx, monster.my, player);
        }

        // C ref: mhitu.c hitmu() — if a hides-under/eel monster was
        // undetected when it hits the hero, reveal it.
        if (monster.mundetected && (hides_under(mdat) || mdat.mlet === S_EEL)) {
            monster.mundetected = false;
            if (Number.isInteger(monster.mx) && Number.isInteger(monster.my)) {
                newsym(monster.mx, monster.my, map || game?.map || null);
            }
        }

        // cf. mhitu.c:1182 — base damage: d(dice, sides)
        const mhm = {
            damage: 0,
            hitflags: M_ATTK_MISS,
            permdmg: 0,
            done: false,
        };
        if (attack.damn !== undefined || attack.damd !== undefined) {
            // C ref: hitmu() always calls d(damn, damd), even for 0,0 attacks.
            mhm.damage = c_d(attack.damn || 0, attack.damd || 0);
        } else if (attack.dmg) {
            mhm.damage = c_d(attack.dmg[0], attack.dmg[1]);
        }

        // Context for handlers
        const ctx = { display, game, suppressHitMsg, map, combatState, dieRoll };

        // cf. mhitu.c:1187 — mhitm_adtyping dispatch
        // Each handler calls hitmsg() and applies effects.
        // For AD_PHYS + AT_WEAP, weapon damage is added inside the handler.
        await mhitu_adtyping(monster, attack, player, mhm, ctx);

        // cf. mhitu.c:1189 — mhitm_knockback()
        const weaponUsed = !!(attack.aatyp === AT_WEAP && monster.weapon);
        await mhitm_knockback(monster, attack, weaponUsed, display);

        // cf. mhitu.c:1192 — check if handler consumed the attack
        if (mhm.done) {
            sum[i] = mhm.hitflags || M_ATTK_HIT;
            if (postAttackTail(sum[i])) break;
            continue;
        }

        // ================================================================
        // Negative AC damage reduction (hitmu path)
        // ================================================================
        // cf. mhitu.c:1204 — if (damage && u.uac < 0) damage -= rnd(-u.uac)
        if (mhm.damage > 0 && playerAc < 0) {
            mhm.damage -= rnd(-playerAc);
            if (mhm.damage < 1) mhm.damage = 1;
        }

        // ================================================================
        // Apply damage
        // ================================================================
        if (mhm.damage > 0) {
            // C ref: mhitu.c:1212 — Half_physical_damage halves hitmu damage.
            const hasHalfPhysical = !!(playerHasProp(player, HALF_PHDAM)
                || player?.halfPhysDamage
                || player?.Half_physical_damage);
            if (hasHalfPhysical) {
                mhm.damage = Math.floor((mhm.damage + 1) / 2);
            }
            const hpBefore = Number.isFinite(player?.uhp) ? player.uhp : (Number(player?.hp) || 0);
            mhituTrace(
                game,
                `pre_mdamageu mon=${monster?.m_id ?? 0} mndx=${monster?.mndx ?? -1} `
                + `aatyp=${attack?.aatyp ?? -1} adtyp=${attack?.adtyp ?? -1} `
                + `dmg=${mhm.damage} hp_before=${hpBefore} `
                + `halfphys=${hasHalfPhysical ? 1 : 0} ac=${playerAc}`
            );
            await mdamageu(monster, mhm.damage, player, display, game);
            const died = (player.uhp || 0) <= 0;
            const hpAfter = Number.isFinite(player?.uhp) ? player.uhp : (Number(player?.hp) || 0);
            mhituTrace(
                game,
                `post_mdamageu mon=${monster?.m_id ?? 0} hp_after=${hpAfter} died=${died ? 1 : 0}`
            );

            if (died) {
                break;
            }
        }

        // C ref: hitmu() ends with unconditional stop_occupation().
        if (game) {
            if (typeof game.stopOccupation === 'function') await game.stopOccupation();
            else game.occupation = null;
        }
        // C ref: hitmu() returns M_ATTK_HIT for successful contact even when
        // post-effect damage is 0 (for example, rust/corrode touch attacks).
        sum[i] = mhm.hitflags || M_ATTK_HIT;
        const stopAfterTail = postAttackTail(sum[i]);
        if (game?._stopMoveloopAfterLifesave || game?.playerDied || game?.gameOver) {
            break;
        }
        if (stopAfterTail) break;
    }
}

