async function xkilled(mon, xkill_flags, map, player) {
    const nomsg = !!(xkill_flags & XKILL_NOMSG);
    const nocorpse = !!(xkill_flags & XKILL_NOCORPSE);
    const x = mon.mx, y = mon.my;

    mon.mhp = 0;

    // C ref: mon.c:3497-3506 — kill message before mondead.
    // Callers that pass XKILL_GIVEMSG are responsible for showing the
    // kill message BEFORE calling xkilled (matching C's message timing).
    // See handleMonsterKilled in uhitm.js for the hero-attack path.

    // C ref: mondead() with life-saving
    await mondead_full(mon, map, player);
    if (mon.mhp > 0) return; // life-saved

    // C ref: mdat/mndx needed for both treasure/corpse and cleanup sections
    const mdat = mon?.data || mon?.type || {};
    const mndx = mon.mndx ?? 0;

    // C ref: nocorpse and LEVEL_SPECIFIC_NOCORPSE both goto cleanup
    // (skip treasure/corpse but still award XP and apply penalties).
    // Only life-saved monsters return early without cleanup.
    if (nocorpse) {
        // Skip directly to cleanup — no treasure, no corpse
    } else {

    // C ref: mon.c:3573-3574 — LEVEL_SPECIFIC_NOCORPSE
    // Suppress treasure/corpse on Rogue level, levels with deathdrops=false
    // (e.g. tutorial), or undead on graveyard levels.
    const game = _gstate;
    const levelFlags = map?.flags || {};
    // C ref: mon.c LEVEL_SPECIFIC_NOCORPSE — check deathdrops as falsy
    // (0 or false), not strict === false, since the flag may be 0.
    // Guard against undefined (unset) by requiring != null.
    const levelSpecificNocorpse =
        levelFlags.is_rogue_level
        || (levelFlags.deathdrops != null && !levelFlags.deathdrops)
        || (levelFlags.graveyard && is_undead(mdat) && rn2(3));
    // C ref: mon.c:3576 — accessible(x,y) || is_pool(x,y) gates treasure+corpse
    const loc = map?.at(x, y);
    const tileAccessible = loc && (ACCESSIBLE(loc.typ) || IS_POOL(loc.typ));
    if (!levelSpecificNocorpse && tileAccessible) {
        if (map && !rn2(6)
            && !(game?.mvitals?.[mndx]?.mvflags & G_NOCORPSE)
            && (x !== (player?.x || 0) || y !== (player?.y || 0))
            && mdat.mlet !== S_KOP
            && !mon.mcloned) {
            const otmp = mkobj(RANDOM_CLASS, true);
            if (otmp) {
                const otyp = otmp.otyp;
                if (otmp.oclass === FOOD_CLASS && !(mdat.mflags2 & M2_COLLECT)
                    && !otmp.oartifact) {
                    delobj(otmp);
                } else if ((mdat.msize || 0) < MZ_HUMAN && otyp !== FIGURINE
                    && (otmp.owt > 30 || objectData[otyp]?.oc_big)) {
                    // C ref: mon.c:3602-3604 — un-create artifact before deleting
                    if (otmp.oartifact)
                        artifact_exists(otmp, safe_oname(otmp), false, ONAME_NO_FLAGS);
                    delobj(otmp);
                } else if (!await flooreffects(otmp, x, y, nomsg ? '' : 'fall', player, map)) {
                    // C ref: mon.c:3606 — flooreffects checks lava/pool/etc.
                    // Object survives floor effects → place on map.
                    place_object(otmp, x, y, map);
                    stackobj(otmp, map);
                }
            }
        }

        let explodedOnDeath = false;
        if (map && !nocorpse && Array.isArray(mdat.mattk)) {
            for (const atk of mdat.mattk) {
                if (atk?.aatyp === AT_BOOM) {
                    corpse_chance(mon);
                    await mon_explodes(mon, atk, map, player);
                    explodedOnDeath = true;
                    break;
                }
            }
        }

        // Corpse
        if (!explodedOnDeath && map && !nocorpse && corpse_chance(mon)) {
            const loc = map.at(x, y);
            if (loc && (ACCESSIBLE(loc.typ) || IS_POOL(loc.typ))) {
                make_corpse(mon, 0, map);
                newsym(x, y);
            }
        }
    }
    } // end of !nocorpse else block
    // C ref: mon.c:3641 — monster is gone, corpse or other object might now be visible
    newsym(x, y);

    // C ref: mon.c:3638-3668 — cleanup: punish bad behavior, give experience
    if (player) {
        // Murder penalty: killing non-hostile humans (excluding role monsters and PM_HUMAN)
        if (is_human(mdat)
            && (!always_hostile(mdat) && (mon.malign || 0) <= 0)
            && (mndx < PM_ARCHEOLOGIST || mndx > PM_WIZARD)
            && mndx !== PM_HUMAN
            && (player.alignment ?? 0) !== A_CHAOTIC) {
            // HTelepat &= ~INTRINSIC; // TODO: intrinsic telepathy loss
            change_luck(-2, player);
            // You("murderer!"); // cosmetic
        }
        // Peaceful/tame luck penalty — rn2(2) is RNG-consuming
        if ((mon.mpeaceful && !rn2(2)) || mon.mtame)
            change_luck(-1, player);
        // Unicorn guilt — same alignment
        if (is_unicorn(mdat) && sgn(player.alignment ?? 0) === sgn(mdat.maligntyp || 0)) {
            change_luck(-5, player);
            // You_feel("guilty..."); // cosmetic
        }

        // Give experience points
        const game = _gstate;
        const tmp = experience(mon, game?.mvitals?.[mndx]?.died || 0);
        more_experienced(tmp, 0, game, player);
        await newexplevel(player);

        // Alignment adjustments for special monsters
        const msound = mdat.msound ?? 0;
        if (game?.quest_status?.leader_m_id && mon.m_id === game.quest_status.leader_m_id) {
            // REAL BAD! Killed quest leader
            adjalign(player, -((player.alignmentRecord || 0) + Math.floor(currentAlignLim(player) / 2)));
            // u.ugangr += 7; // TODO: god anger
            change_luck(-20, player);
        } else if (msound === MS_NEMESIS) {
            // Real good! (only if leader not killed)
            if (!game?.quest_status?.killed_leader)
                adjalign(player, Math.floor(currentAlignLim(player) / 4)); // ALIGNLIM/4
        } else if (msound === MS_GUARDIAN) {
            adjalign(player, -Math.floor(currentAlignLim(player) / 8)); // -ALIGNLIM/8
            // u.ugangr++; // TODO: god anger
            change_luck(-4, player);
        } else if (mon.ispriest) {
            adjalign(player, p_coaligned(mon, player) ? -2 : 2);
            if (p_coaligned(mon, player))
                player.ublessed = 0;
            if ((mdat.maligntyp || 0) === A_NONE)
                adjalign(player, Math.floor(currentAlignLim(player) / 4)); // ALIGNLIM/4
        } else if (mon.mtame) {
            adjalign(player, -15);
            if (!(player?.hallucinating || player?.Hallucination)) {
                await You_hear('the rumble of distant thunder...');
            } else {
                await You_hear('the studio audience applaud!');
            }
        } else if (mon.mpeaceful) {
            // C ref: mon.c:3720 — killing a peaceful monster
            adjalign(player, -5);
        }

        // C ref: mon.c:3724 — malign was already adjusted for alignment and randomization
        adjalign(player, mon.malign || 0);
    }
}

