        // not a single-step chase. Keeping this logic here avoids a module cycle
        // with monmove.js's canonical move_special().
        const omx = mon.mx, omy = mon.my;
        if (inhishop(mon, map)) {
            await shk_fixes_damage(mon, map, _gstate);
