                        || !!carrying(DWARVISH_MATTOCK, player)
                        || (((player.Fast || player.fast) ? 1 : 0)
                            && (!!sobj_at(PICK_AXE, player.x, player.y, map)
                                || !!sobj_at(DWARVISH_MATTOCK, player.x, player.y, map)));
                    if (satdoor && badinv) {
                        return MMOVE_NOTHING;
                    }
                    avoid = !badinv;
