                    avoid = !!(player.ushops && distu(player, gtx, gty) > 8);
                    badinv = false;
                }

                if (((!robbed && !billct && !debit) || avoid)
                    && dist2(omx, omy, gtx, gty) < 3) {
                    if (!badinv && !onlineu(mon, player)) {
                        return MMOVE_NOTHING;
