                ggy = cp.y;
            }
        }
    }

    let getitems = false;
    const isRogueLevel = !!(map?.flags?.is_rogue || map?.flags?.roguelike || map?.flags?.is_rogue_lev);
    if ((!mon_is_peaceful(mon) || !rn2(10)) && !isRogueLevel) {
