        `step=${monmoveStepLabel(map)}`,
        `id=${mon.m_id ?? '?'}`,
        `mndx=${mon.mndx ?? '?'}`,
        `name=${mon.data?.mname || mon.type?.mname || mon.name || '?'}`,
        `pos=(${omx},${omy})`,
        `target=(${ggx},${ggy})`,
        `mux=(${mon.mux ?? '?'},${mon.muy ?? '?'})`,
        `mcansee=${(mon.mcansee !== 0 && mon.mcansee !== false) ? 1 : 0}`,
