    const preferredRangeMin = (appr === -2 && arw) ? (2 * 2) : 0;
    const preferredRangeMax = (appr === -2 && arw) ? Number(arw.range || 0) : 0;
    const jcnt = Math.min(MTSZ, cnt - 1);
