                        `step=${monmoveStepLabel(map)}`,
                        `id=${mon.m_id ?? '?'}`,
                        `mndx=${mon.mndx ?? '?'}`,
                        `name=${mon.data?.mname || mon.type?.mname || mon.name || '?'}`,
                        `pos=(${omx},${omy})`,
                        `cand=(${nx},${ny})`,
                        `j=${j}`,
                        `denom=${denom}`,
                        `roll=${trackRoll}`);
                    if (trackRoll) {
