async function readobjnam(bp, no_wish, opts = {}) {
    if (typeof bp !== 'string') return null;
    const state = readobjnam_init();
    if (!readobjnam_preparse(state, bp)) return null;

    readobjnam_postparse1(state);
    if (state.otmp) return state.otmp; // cf. objnam.c:4931 — case 3: return d.otmp
    readobjnam_postparse2(state);
    readobjnam_postparse3(state);

    const actualn = state.actualn || '';
    const dn = state.dn || actualn;
    const un = state.un || '';
    const origbp = state.origbp || '';
    const oclass = state.oclass || 0;
    const forcedTyp = state.forcedTyp || 0;

    const directTyp = (oclass === COIN_CLASS && forcedTyp === GOLD_PIECE)
        ? forcedTyp
        : 0;
    // cf. objnam.c:4949 — postparse3 returns 2 (typfnd) for gems/tin,
    // completely skipping rnd_otyp_by_namedesc. typfndTyp signals this.
    let otyp = state.typfndTyp || directTyp || STRANGE_OBJECT;
    if (!(otyp > STRANGE_OBJECT && otyp < NUM_OBJECTS)) {
        otyp = rnd_otyp_by_namedesc(actualn, oclass, 1);
        if ((otyp <= STRANGE_OBJECT || otyp >= NUM_OBJECTS) && dn && dn !== actualn) {
            otyp = rnd_otyp_by_namedesc(dn, oclass, 1);
        }
        if ((otyp <= STRANGE_OBJECT || otyp >= NUM_OBJECTS) && un) {
            otyp = rnd_otyp_by_namedesc(un, oclass, 1);
        }
        if ((otyp <= STRANGE_OBJECT || otyp >= NUM_OBJECTS) && origbp && origbp !== actualn) {
            otyp = rnd_otyp_by_namedesc(origbp, oclass, 1);
        }

        // C ref: objnam.c:4750 — after oclass-specific rnd_otyp_by_namedesc fails,
        // C does NOT retry with oclass=0. It falls through to Japanese items,
        // armor "mail" append, spinach, and fruit checks instead.
        // The oclass=0 fallback was JS-only and consumed extra RNG.
    }

    // C ref: objnam.c:4862-4870 — artifact lookup by name (before alt spellings)
    // When no class and no type found, try to match an artifact name.
    let artifactName = null;
    if ((otyp <= STRANGE_OBJECT || otyp >= NUM_OBJECTS) && !oclass && actualn) {
        const arti = artifact_name(actualn, true);
        if (arti) {
            otyp = arti.otyp;
            artifactName = arti.name;
        }
    }

    // C ref: objnam.c:4447 — alternate spellings table (spellings[])
    // wishymatch(userBp, sp, true) — check actual bp text against each alias
    if (otyp <= STRANGE_OBJECT || otyp >= NUM_OBJECTS) {
        const bpLookup = (state.origbp || '').toLowerCase().trim();
        if (bpLookup) {
            for (const { sp, ob } of alt_spellings) {
                if (wishymatch(bpLookup, sp, true)) {
                    otyp = ob;
                    break;
                }
            }
        }
    }

    if (forcedTyp > STRANGE_OBJECT && forcedTyp < NUM_OBJECTS) {
        otyp = forcedTyp;
    }

    let otmp = null;
    if (otyp > STRANGE_OBJECT && otyp < NUM_OBJECTS) {
        if (no_wish && objectData[otyp]?.no_wish) return null;
        otmp = mksobj(otyp, true, false);
    } else if (oclass) {
        otmp = mkobj(oclass, false);
    }
    if (!otmp) {
        // C flow parity: terrain/trap wishing is part of readobjnam, gated to
        // wizard mode and disabled for wizkit startup wishing.
        const wizard = !!opts.wizard;
        const wizkit_wishing = !!opts.wizkit_wishing;
        if (wizard && !wizkit_wishing && !oclass) {
            const terrain = await wizterrainwish({
                text: bp,
                player: opts.player || null,
                map: opts.map || opts.player?.map || null,
                x: opts.x,
                y: opts.y,
            });
            if (terrain) {
                if (opts && typeof opts === 'object') {
                    opts._terrainWish = terrain;
                }
                return hands_obj;
            }
        }
        return null;
    }
    otyp = otmp.otyp;

    // C ref: objnam.c readobjnam() — apply requested quantity.
    // When no explicit count was given (quan==1 from init), force quan=1
    // to override any random quantity set by mksobj_init (e.g. food 1/6
    // chance of quan=2, multigen weapons, gems, etc.).
    if (state.quan > 1) {
        otmp.quan = state.quan;
    } else {
        otmp.quan = 1;
    }
    otmp.owt = weight(otmp);
    if (state.buc === 1) bless(otmp);
    else if (state.buc === -1) curse(otmp);
    else if (state.buc === 2) uncurse(otmp);

    if (state.spe !== null) {
        otmp.spe = state.spe;
    }

    // cf. objnam.c:5181-5243 — set otmp->corpsenm or dragon scale [mail]
    const mntmp = state.mntmp;
    if (typeof mntmp === 'number' && mntmp >= LOW_PM) {
        const adjustedMntmp = (mntmp === PM_LONG_WORM_TAIL) ? PM_LONG_WORM : mntmp;
        switch (otyp) {
        case EGG: {
            const hatched = can_be_hatched(adjustedMntmp);
            set_corpsenm(otmp, hatched);
            break;
        }
        case CORPSE:
            if (!(mons[adjustedMntmp]?.geno & G_UNIQ) || !!opts.wizard) {
                set_corpsenm(otmp, adjustedMntmp);
            }
            break;
        case FIGURINE:
            if (!(mons[adjustedMntmp]?.geno & G_UNIQ)) {
                otmp.corpsenm = adjustedMntmp;
            }
            break;
        case STATUE:
            otmp.corpsenm = adjustedMntmp;
            break;
        case TIN:
            otmp.corpsenm = adjustedMntmp;
            break;
        default:
            // Dragon scales / scale mail
            if (otyp === SCALE_MAIL && adjustedMntmp >= PM_GRAY_DRAGON
                && adjustedMntmp <= PM_YELLOW_DRAGON) {
                otmp.otyp = GRAY_DRAGON_SCALE_MAIL + adjustedMntmp - PM_GRAY_DRAGON;
            }
            break;
        }
    }

    // C ref: objnam.c:5336-5356 — if name matches an artifact, call oname/artifact_exists
    if (artifactName) {
        artifact_exists(otmp, artifactName, true, ONAME_WISH);
        if (otmp.oartifact) {
            otmp.quan = 1;
            otmp.oname = artifactName;
        }
    }

    // C ref: objnam.c:5361-5371 — "more wishing abuse" check
    // C: if ((is_quest_artifact(d.otmp) || (d.otmp->oartifact && rn2(nartifact_exist()) > 1)) && !wizard)
    // The rn2() call is short-circuited for true quest artifacts.
    if (otmp && otmp.oartifact) {
        const wizard = !!opts.wizard;
        const abuse = is_quest_artifact(otmp)
            || (otmp.oartifact && rn2(nartifact_exist()) > 1);
        if (abuse && !wizard) {
            artifact_exists(otmp, otmp.oname || '', false, 0);
            otmp.oartifact = 0;
            otmp.oname = '';
        }
    }

    otmp.dknown = true;

    return otmp;
}

