async function handleSet(game, { showAdvanced = false } = {}) {
    const { display, u: player } = game;
    const flags = game.flags;

    let currentPage = 1;
    let showHelp = false;

    function applyOptionSideEffects() {
        player.showExp = !!flags.showexp;
        player.showTime = !!flags.time;
        if (typeof window !== 'undefined') window.gameFlags = flags;
    }

    async function drawOptions() {
        const normalizedPage = normalizeOptionsPage(currentPage, showHelp, showAdvanced);
        currentPage = normalizedPage;
        const { screen, attrs } = renderOptionsMenu(normalizedPage, showHelp, flags, showAdvanced, game);

        display.clearScreen();
        for (let r = 0; r < display.rows; r++) {
            const line = screen[r] || '';
            const lineAttrs = attrs[r] || '';
            const maxCols = Math.min(display.cols, line.length);
            for (let c = 0; c < maxCols; c++) {
                const attr = lineAttrs[c] === '1' ? 1 : 0;
                await display.putstr(c, r, line[c], undefined, attr);
            }
        }
    }

    function normalizeListFlag(flagName) {
        if (!Array.isArray(flags[flagName])) {
            flags[flagName] = [];
        }
        return flags[flagName];
    }

    function normalizeStatusConditionFlag() {
        const raw = flags.statusconditions;
        if (Array.isArray(raw)) {
            flags.statusconditions = raw.filter(name => STATUS_CONDITION_FIELDS_ALPHA.includes(name));
            return flags.statusconditions;
        }
        const count = (typeof raw === 'number')
            ? Math.max(0, Math.min(STATUS_CONDITION_FIELDS_ALPHA.length, raw))
            : STATUS_CONDITION_DEFAULT_ON.size;
        flags.statusconditions = STATUS_CONDITION_FIELDS_ALPHA.filter((name, idx) => {
            if (typeof raw === 'number') return idx < count;
            return STATUS_CONDITION_DEFAULT_ON.has(name);
        });
        return flags.statusconditions;
    }

    async function renderSimpleEditorLines(title, lines) {
        display.clearScreen();
        const maxRows = Math.min(display.rows, lines.length + 3);
        const header = ` ${title} `;
        await display.putstr(0, 0, header, undefined, 1);
        await display.putstr(0, 1, '');
        for (let i = 0; i < maxRows - 2; i++) {
            await display.putstr(0, i + 2, lines[i].substring(0, display.cols));
        }
    }

    async function renderCenteredList(lines, left = 41, headerInverse = false) {
        display.clearScreen();
        for (let i = 0; i < lines.length && i < display.rows; i++) {
            const text = lines[i].substring(0, Math.max(0, display.cols - left));
            const attr = (headerInverse && i === 0) ? 1 : 0;
            await display.putstr(left, i, text, undefined, attr);
        }
    }

    async function editPickOption(option) {
        const choices = option.choices || [];
        const current = String(flags[option.flag] || '');
        const lines = [`Set ${option.name}:`, ''];
        for (let i = 0; i < choices.length; i++) {
            const letter = String.fromCharCode(97 + i); // a, b, c, ...
            const mark = choices[i].value === current ? ' *' : '';
            lines.push(` ${letter} - ${choices[i].label}${mark}`);
        }
        lines.push('', '(end)');
        await renderCenteredList(lines, 30, true);

        const ch = await nhgetch();
        if (ch === 27) return; // ESC = cancel
        const idx = ch - 97; // 'a' = 0
        if (idx >= 0 && idx < choices.length) {
            flags[option.flag] = choices[idx].value;
            saveFlags(flags);
            applyOptionSideEffects();
        }
    }

    async function editDoWhatCountOption(option) {
        const list = normalizeListFlag(option.flag);
        const addPrompt = option.flag === 'menucolors'
            ? 'What new menucolor pattern? '
            : 'What new autopickup exception pattern? ';
        const addLabel = option.flag === 'menucolors'
            ? 'a - add new menucolor'
            : 'a - add new autopickup exception';

        while (true) {
            const lines = [
                'Do what?',
                '',
                addLabel,
                'x * exit this menu',
                '(end)'
            ];
            await renderCenteredList(lines);

            const ch = await nhgetch();
            const c = String.fromCharCode(ch);
            if (ch === 27 || c === 'x') {
                saveFlags(flags);
                return;
            }
            if (c === 'a') {
                const added = await getlin(addPrompt, display);
                if (added !== null) {
                    const trimmed = added.trim();
                    if (trimmed.length > 0) list.push(trimmed);
                }
                continue;
            }
        }
    }

    async function editStatusHilitesOption() {
        if (!flags.statushighlights || typeof flags.statushighlights !== 'object' || Array.isArray(flags.statushighlights)) {
            flags.statushighlights = {};
        }
        let page = 1;
        const pageSize = 21;

        while (true) {
            const lines = [];
            const totalPages = Math.ceil(STATUS_HILITE_FIELDS.length / pageSize);
            const start = (page - 1) * pageSize;
            const visible = STATUS_HILITE_FIELDS.slice(start, start + pageSize);

            if (page === 1) {
                lines.push('Status hilites:');
                lines.push('');
            }
            for (let i = 0; i < visible.length; i++) {
                const key = String.fromCharCode('a'.charCodeAt(0) + i);
                lines.push(`${key} - ${visible[i]}`);
            }
            lines.push(`(${page} of ${totalPages})`);
            display.clearScreen();
            for (let i = 0; i < lines.length && i < display.rows; i++) {
                const row = (i === lines.length - 1) ? 23 : i;
                await display.putstr(0, row, lines[i].substring(0, display.cols));
            }

            const ch = await nhgetch();
            const c = String.fromCharCode(ch);
            if (ch === 27 || c === 'q') {
                return;
            }
            if (c === '>' && page < totalPages) {
                page += 1;
                continue;
            }
            if (c === '<' && page > 1) {
                page -= 1;
                continue;
            }
            if (c >= 'a' && c <= 'z') {
                const idx = c.charCodeAt(0) - 'a'.charCodeAt(0);
                if (idx < 0 || idx >= visible.length) continue;
                const field = visible[idx];
                const label = field.toLowerCase();
                const lines2 = [
                    `Select ${label} field hilite behavior:`,
                    '',
                    `a - Always highlight ${label}`,
                    `${field === 'hunger' ? 'c - hunger value changes' : `c - ${label} value changes`}`,
                    `${field === 'hunger' ? 't - hunger text match' : `t - ${label} text match`}`,
                    '(end)'
                ];
                await renderCenteredList(lines2);
                const ch2 = await nhgetch();
                const c2 = String.fromCharCode(ch2);
                if (c2 === 'a' || c2 === 'c' || c2 === 't') {
                    flags.statushighlights[field] = c2;
                    saveFlags(flags);
                }
            }
        }
    }

    async function editStatusConditionsOption() {
        const enabled = normalizeStatusConditionFlag();
        let page = 1;
        const pageSize = 19;

        while (true) {
            const totalPages = Math.ceil(STATUS_CONDITION_FIELDS_ALPHA.length / pageSize);
            const start = (page - 1) * pageSize;
            const visible = STATUS_CONDITION_FIELDS_ALPHA.slice(start, start + pageSize);
            const lines = [];
            if (page === 1) {
                lines.push('Choose status conditions to toggle');
                lines.push('');
                lines.push('S - change sort order from "alphabetically" to "by ranking"');
                lines.push('sorted alphabetically');
            }
            for (let i = 0; i < visible.length; i++) {
                const key = String.fromCharCode('a'.charCodeAt(0) + i);
                const mark = enabled.includes(visible[i]) ? '*' : '-';
                lines.push(`${key} ${mark} ${visible[i]}`);
            }
            lines.push(`(${page} of ${totalPages})`);

            display.clearScreen();
            for (let i = 0; i < lines.length && i < display.rows; i++) {
                const row = (i === lines.length - 1) ? 23 : i;
                await display.putstr(0, row, lines[i].substring(0, display.cols));
            }

            const ch = await nhgetch();
            const c = String.fromCharCode(ch);
            if (ch === 27) {
                saveFlags(flags);
                return;
            }
            if (c === '>' && page < totalPages) {
                page += 1;
                continue;
            }
            if (c === '<' && page > 1) {
                page -= 1;
                continue;
            }
            if (c >= 'a' && c <= 'z') {
                const idx = c.charCodeAt(0) - 'a'.charCodeAt(0);
                if (idx < 0 || idx >= visible.length) continue;
                const field = visible[idx];
                const pos = enabled.indexOf(field);
                if (pos >= 0) enabled.splice(pos, 1);
                else enabled.push(field);
                saveFlags(flags);
            }
        }
    }

    async function editNumberPadModeOption() {
        const lines = [
            'Select number_pad mode:',
            '',
            'a -  0 (off)',
            'b -  1 (on)',
            'c -  2 (on, MSDOS compatible)',
            'd -  3 (on, phone-style digit layout)',
            'e -  4 (on, phone-style layout, MSDOS compatible)',
            "f - -1 (off, 'z' to move upper-left, 'y' to zap wands)",
            '(end)',
        ];
        await renderCenteredList(lines, 24, true);
        const ch = await nhgetch();
        const c = String.fromCharCode(ch);
        const modeByKey = { a: 0, b: 1, c: 2, d: 3, e: 4, f: -1 };
        if (Object.prototype.hasOwnProperty.call(modeByKey, c)) {
            flags.number_pad = modeByKey[c];
            saveFlags(flags);
        }
    }

    async function editAutounlockOption() {
        const actions = [
            { key: 'u', token: 'untrap', suffix: '(might fail)' },
            { key: 'a', token: 'apply-key', suffix: '' },
            { key: 'k', token: 'kick', suffix: '(doors only)' },
            { key: 'f', token: 'force', suffix: '(chests/boxes only)' },
        ];
        const tokenOrder = new Map(actions.map((a, idx) => [a.token, idx]));
        const parseSelected = () => {
            const raw = String(flags.autounlock ?? '').trim();
            if (raw === 'none') return new Set();
            if (!raw) return new Set(['apply-key']);
            const selected = new Set();
            for (const part of raw.split(/[,\s]+/)) {
                const tok = part.trim();
                if (!tok) continue;
                if (tokenOrder.has(tok)) selected.add(tok);
            }
            return selected;
        };
        const saveSelected = (selected) => {
            if (selected.size === 0) {
                flags.autounlock = 'none';
            } else {
                flags.autounlock = Array.from(selected)
                    .sort((a, b) => (tokenOrder.get(a) ?? 99) - (tokenOrder.get(b) ?? 99))
                    .join(',');
            }
            saveFlags(flags);
        };

        while (true) {
            const selected = parseSelected();
            const lines = ["Select 'autounlock' actions:", ''];
            for (const action of actions) {
                const mark = selected.has(action.token) ? '*' : '-';
                const spacer = action.suffix ? ' '.repeat(Math.max(1, 11 - action.token.length)) : '';
                lines.push(`${action.key} ${mark} ${action.token}${spacer}${action.suffix}`.trimEnd());
            }
            lines.push('(end)');
            display.clearScreen();
            display.renderMap((game.map || game.map), player, game.fov, flags);
            for (let i = 0; i < lines.length && i < display.rows; i++) {
                const text = lines[i].substring(0, Math.max(0, display.cols - 41));
                const attr = (i === 0) ? 1 : 0;
                await display.putstr(41, i, ' '.repeat(Math.max(0, display.cols - 41)));
                await display.putstr(41, i, text, undefined, attr);
            }

            const ch = await nhgetch();
            const c = String.fromCharCode(ch).toLowerCase();
            if (ch === 27 || ch === 10 || ch === 13 || c === ' ') {
                return;
            }
            const action = actions.find((entry) => entry.key === c);
            if (!action) continue;
            if (selected.has(action.token)) selected.delete(action.token);
            else selected.add(action.token);
            saveSelected(selected);
        }
    }

    async function editPickupTypesOption() {
        const choices = [
            { key: 'a', glyph: '$', symbol: '$', label: 'pile of coins' },
            { key: 'b', glyph: '"', symbol: '"', label: 'amulet' },
            { key: 'c', glyph: ')', symbol: ')', label: 'weapon' },
            { key: 'd', glyph: '[', symbol: '[', label: 'suit or piece of armor' },
            { key: 'e', glyph: '%', symbol: '%', label: 'piece of food' },
            { key: 'f', glyph: '?', symbol: '?', label: 'scroll' },
            { key: 'g', glyph: '+', symbol: '+', label: 'spellbook' },
            { key: 'h', glyph: '!', symbol: '!', label: 'potion' },
            { key: 'i', glyph: '=', symbol: '=', label: 'ring' },
            { key: 'j', glyph: '/', symbol: '/', label: 'wand' },
            { key: 'k', glyph: '(', symbol: '(', label: 'useful item (pick-axe, key, lamp...)' },
            { key: 'l', glyph: '*', symbol: '*', label: 'gem or rock' },
            { key: 'm', glyph: '`', symbol: '`', label: 'boulder or statue' },
            { key: 'n', glyph: '0', symbol: '0', label: 'iron ball' },
            { key: 'o', glyph: '_', symbol: '_', label: 'iron chain' },
        ];
        const symbolOrder = new Map(choices.map((choice, idx) => [choice.symbol, idx]));

        const parseTypes = () => {
            const raw = String(flags.pickup_types || '');
            if (!raw) return new Set();
            return new Set(raw.split(''));
        };

        const saveTypes = (set) => {
            const sorted = Array.from(set).sort((a, b) =>
                (symbolOrder.get(a) ?? 999) - (symbolOrder.get(b) ?? 999));
            flags.pickup_types = sorted.join('');
            saveFlags(flags);
        };

        while (true) {
            const selected = parseTypes();
            const lines = ['Autopickup what?', ''];
            for (const choice of choices) {
                const mark = selected.has(choice.symbol) ? '+' : '-';
                lines.push(`${choice.key} ${mark} ${choice.glyph}  ${choice.label}`);
            }
            lines.push('');
            lines.push('A -    All classes of objects');
            lines.push('Note: when no choices are selected, "all" is implied.');
            lines.push("Toggle off 'autopickup' to not pick up anything.");
            lines.push('(end)');
            display.clearScreen();
            display.renderMap((game.map || game.map), player, game.fov, flags);
            // Session captures for this menu are column-shifted by one map cell.
            // Apply that shift in headless parity mode before drawing the right panel.
            if (Array.isArray(display.grid) && Array.isArray(display.colors) && Array.isArray(display.attrs)) {
                for (let row = 1; row <= 21 && row < display.rows; row++) {
                    for (let col = 0; col < display.cols - 1; col++) {
                        display.grid[row][col] = display.grid[row][col + 1];
                        display.colors[row][col] = display.colors[row][col + 1];
                        display.attrs[row][col] = display.attrs[row][col + 1];
                    }
                    display.grid[row][display.cols - 1] = ' ';
                    display.colors[row][display.cols - 1] = 7;
                    display.attrs[row][display.cols - 1] = 0;
                }
            }
            for (let i = 0; i < lines.length && i < display.rows; i++) {
                const text = lines[i].substring(0, Math.max(0, display.cols - 25));
                const attr = (i === 0) ? 1 : 0;
                await display.putstr(24, i, ' '.repeat(Math.max(0, display.cols - 24)));
                await display.putstr(25, i, text, undefined, attr);
            }

            const ch = await nhgetch();
            const c = String.fromCharCode(ch);
            if (ch === 27 || ch === 10 || ch === 13 || c === ' ' || c === 'q' || c === 'x') {
                return;
            }
            if (c === 'A') {
                selected.clear();
                saveTypes(selected);
                continue;
            }
            const choice = choices.find((entry) => entry.key === c);
            if (!choice) continue;
            if (selected.has(choice.symbol)) selected.delete(choice.symbol);
            else selected.add(choice.symbol);
            saveTypes(selected);
        }
    }

    // Interactive loop - C ref: options.c doset() menu loop
    while (true) {
        await drawOptions();

        // Get input - C ref: options.c menu input loop
        const ch = await nhgetch();
        const c = String.fromCharCode(ch);

        // Check for exit
        if (ch === 27 || ch === 10 || ch === 13 || c === 'q' || c === ' ') { // ESC, Enter, space, or q
            break;
        }

        // Check for navigation - C ref: MENU_NEXT_PAGE, MENU_PREVIOUS_PAGE, MENU_FIRST_PAGE
        // Also accept J/K (PageDown/PageUp from browser_input.js arrow key mapping)
        if (c === '>' || c === 'J') {
            const maxPage = getTotalPages(showHelp, showAdvanced);
            if (currentPage < maxPage) currentPage += 1;
            continue;
        }
        if (c === '<' || c === 'K') {
            if (currentPage > 1) currentPage -= 1;
            continue;
        }
        if (c === '^') {
            currentPage = 1;
            continue;
        }
        if (c === '?') {
            showHelp = !showHelp;
            currentPage = normalizeOptionsPage(currentPage, showHelp, showAdvanced);
            continue;
        }

        // Check for option selection
        const selected = getOptionByKey(currentPage, showHelp, c, showAdvanced);
        if (selected) {
            // Read-only options (identity fields during gameplay)
            if (selected.readonly) {
                continue;
            }
            if (selected.flag === 'number_pad') {
                await editNumberPadModeOption();
                continue;
            }
            if (selected.flag === 'autounlock') {
                await editAutounlockOption();
                currentPage = 1;
                showHelp = false;
                continue;
            }
            if (selected.flag === 'pickup_types') {
                await editPickupTypesOption();
                currentPage = 1;
                showHelp = false;
                continue;
            }
            if (selected.type === 'bool') {
                setOptionValue(currentPage, showHelp, c, null, flags);
                applyOptionSideEffects();
                continue;
            }

            if (selected.type === 'pick' && selected.choices) {
                await editPickOption(selected);
                continue;
            }

            if (selected.type === 'count') {
                if (selected.flag === 'statusconditions') {
                    await editStatusConditionsOption();
                    currentPage = 1;
                    showHelp = false;
                } else if (selected.flag === 'statushighlights') {
                    await editStatusHilitesOption();
                    currentPage = 1;
                    showHelp = false;
                } else {
                    await editDoWhatCountOption(selected);
                    currentPage = 1;
                    showHelp = false;
                }
                continue;
            }

            const prompt = `Set ${selected.name} to what? `;
            const newValue = await getlin(prompt, display);
            if (newValue !== null) {
                setOptionValue(currentPage, showHelp, c, newValue, flags);
                if (selected.flag === 'name') {
                    player.name = flags.name;
                }
                applyOptionSideEffects();
            }
        }
        // If invalid key, just loop again (menu stays open, no error message)
    }

    // Restore game display after exiting menu
    // Clear screen first to remove all menu text
    display.clearScreen();
    display.renderMap((game.map || game.map), player, game.fov, flags);
    display.renderStatus(player);

    return { moved: false, tookTime: false };
}

async function handlePickup(player, map, display, game = null) {
    const dismissOwnedMore = (gameCtx) => {
        if (!gameCtx?.display) return;
        if (Object.hasOwn(gameCtx.display, 'messageNeedsMore')) {
            gameCtx.display.messageNeedsMore = false;
        }
        if (Object.hasOwn(gameCtx.display, 'moreMarkerActive')) {
            gameCtx.display.moreMarkerActive = false;
        }
        if (typeof gameCtx.display.clearRow === 'function') {
            gameCtx.display.clearRow(0);
            if (gameCtx.display._topMessageRow1 !== undefined) {
                gameCtx.display.clearRow(1);
                gameCtx.display._topMessageRow1 = undefined;
            }
        }
    };
    const objs = map.objectsAt(player.x, player.y);
    if (objs.length === 0) {
        const loc = map.at(player.x, player.y);
        if (loc && loc.typ === THRONE) {
            await display.putstr_message(`It must weigh${loc.looted ? ' almost' : ''} a ton!`);
            return { moved: false, tookTime: false };
        }
        if (loc && loc.typ === SINK) {
            await display.putstr_message('The plumbing connects it to the floor.');
            return { moved: false, tookTime: false };
        }
        if (loc && loc.typ === GRAVE) {
            await display.putstr_message("You don't need a gravestone.  Yet.");
            return { moved: false, tookTime: false };
        }
        if (loc && loc.typ === FOUNTAIN) {
            await display.putstr_message('You could drink the water...');
            return { moved: false, tookTime: false };
        }
        if (loc && IS_DOOR(loc.typ) && (loc.flags & D_ISOPEN)) {
            await display.putstr_message("It won't come off the hinges.");
            return { moved: false, tookTime: false };
        }
        if (loc && loc.typ === ALTAR) {
            await display.putstr_message('Moving the altar would be a very bad idea.');
            return { moved: false, tookTime: false };
        }
        if (loc && loc.typ === STAIRS) {
            await display.putstr_message('The stairs are solidly affixed.');
            return { moved: false, tookTime: false };
        }
        await display.putstr_message('There is nothing here to pick up.');
        return { moved: false, tookTime: false };
    }

    // C ref: pickup.c query_objlist() only bypasses the pickup menu via
    // AUTOSELECT_SINGLE when exactly one eligible floor object exists.
    // Mixed piles with gold still enter "Pick up what?", with the first gold
    // stack using '$' as its selector.
    const gold = objs.find(o => o.oclass === COIN_CLASS);
    if (gold && objs.length === 1) {
        player.addToInventory(gold);
        map.removeObject(gold);
        await display.putstr_message(formatGoldPickupMessage(gold, player));
        return { moved: false, tookTime: true };
    }

    // C-faithful command boundary: ',' on a multi-object pile enters a
    // selector flow (same command) where letter keys are not global commands.
    if (objs.length > 1) {
        pickup_encumbrance = 0;
        const inv_order = game?.flags?.inv_order || '';
        const choiceObjs = [...objs].sort((a, b) => {
            // C-like pickup menu ordering: group by class per inv_order, then by name.
            const ac = Number(a?.oclass || 0);
            const bc = Number(b?.oclass || 0);
            if (ac !== bc) {
                // Sort by position in inv_order (C's def_inv_order)
                const ai = inv_order.indexOf(String.fromCharCode(ac));
                const bi = inv_order.indexOf(String.fromCharCode(bc));
                return (ai === -1 ? 999 : ai) - (bi === -1 ? 999 : bi);
            }
            // C ref: invent.c sortloot_cmp() uses loot_classify() within class,
            // so armor/tool/gem subclasses stay in C order before name tiebreaks.
            const sa = { orderclass: 0, subclass: 0, disco: 0, inuse: 0 };
            const sb = { orderclass: 0, subclass: 0, disco: 0, inuse: 0 };
            loot_classify(sa, a);
            loot_classify(sb, b);
            if (sa.subclass !== sb.subclass) return sa.subclass - sb.subclass;
            if (sa.disco !== sb.disco) return sa.disco - sb.disco;
            // C ref: invent.c sortloot_cmp() orders equal class/subclass items
            // by loot_xname(), which preserves known enchantment text like "+2 dart".
            const an = String(xname(a, player) || '');
            const bn = String(xname(b, player) || '');
            const byName = an.localeCompare(bn);
            if (byName !== 0) return byName;
            // C ref: sortloot uses stable sort; equal items preserve floor
            // chain order (LIFO = newest first).  Match by sorting higher
            // o_id first (higher o_id = created later = placed later =
            // first in C's LIFO chain).
            return Number(b?.o_id || 0) - Number(a?.o_id || 0);
        });
        const win = create_nhwindow(NHW_MENU);
        start_menu(win, MENU_BEHAVE_STANDARD);
        let lastClass = null;
        let assignedGoldSelector = false;
        for (const obj of choiceObjs) {
            const cls = Number(obj?.oclass || 0);
            if (cls !== lastClass) {
                const sym = CLASS_SYMBOLS[cls] || '*';
                add_menu(win, null, null, 0, 0, ATR_NONE, 0, classSymbolLabel(sym), 0);
                lastClass = cls;
            }
            const selector = (!assignedGoldSelector && obj?.oclass === COIN_CLASS) ? '$'.charCodeAt(0) : 0;
            if (selector) assignedGoldSelector = true;
            // C ref: pickup.c query_objlist() assigns '$' to the first gold
            // entry, otherwise lets the menu backend auto-assign letters.
            add_menu(win, null, obj, selector, 0, ATR_NONE, 0, doname(obj), 0);
        }
        end_menu(win, 'Pick up what?');
        const picks = await select_menu(win, PICK_ANY);
        destroy_nhwindow(win);

        if (!Array.isArray(picks) || picks.length === 0) {
            pickup_encumbrance = 0;
            return { moved: false, tookTime: false };
        }

        if (player.inventory) {
            for (const inv of player.inventory) {
                if (inv) inv.pickup_prev = 0;
            }
        }

        let nPicked = 0;
        for (const pick of picks) {
            const obj = pick?.identifier;
            if (!obj || !map.objects.includes(obj)) continue;
            const count = pick?.count && pick.count > 0 ? pick.count : (obj.quan || 0);
            const res = await pickup_object(obj, count, false, player, map);
            if (res < 0) break;
            nPicked += res;
        }
        pickup_encumbrance = 0;
        return { moved: false, tookTime: nPicked > 0 };
    }

    // C ref: pickup.c pickup_object() calls reset_justpicked(gi.invent) for
    // single-item pickup path (via query_objlist with AUTOSELECT_SINGLE).
    // Clears pickup_prev so only newly picked-up items get 'P' drop category.
    if (player.inventory) {
        for (const inv of player.inventory) {
            if (inv) inv.pickup_prev = 0;
        }
    }

    // Pick up first non-gold item in C floor-chain order.
    // C floor lists are prepended (newest first), while JS stores floor objects
    // in append order, so objectsAt() yields oldest->newest.
    // Select newest here to match C default ',' pickup target.
    // TODO: show menu if multiple items (like C NetHack)
    const obj = objs[objs.length - 1];
    if (!obj) {
        await display.putstr_message('There is nothing here to pick up.');
        return { moved: false, tookTime: false };
    }
    const cnt_p = { value: obj.quan || 1 };
    const liftResult = await lift_object(obj, null, cnt_p, false, player);
    if (liftResult <= 0 || cnt_p.value < 1) {
        return { moved: false, tookTime: liftResult < 0 };
    }

    const completePickup = async () => {
        let pickedObj = obj;
        if ((obj.quan || 1) !== cnt_p.value && obj.otyp !== LOADSTONE) {
            pickedObj = splitobj(obj, cnt_p.value);
            if (!pickedObj) {
                return { moved: false, tookTime: false };
            }
        }

        const finishPickupAfterBilling = async (displayCtx = display, gameCtx = game) => {
            const addResult = player.addToInventory(pickedObj, { withMeta: true });
            const inventoryObj = addResult.item;
            // C ref: invent.c:1142 — mark as just picked up for 'P' drop category
            if (inventoryObj) inventoryObj.pickup_prev = 1;
            // Note: obj was already removed from map above (before addtobill),
            // matching C's pick_obj() order: obj_extract_self → addtobill → addinv.
            // C pickup behavior can collect additional stacks for the same
            // selected type at this square.
            const px = obj.ox, py = obj.oy;
            while (true) {
                const extra = (map.objectsAt(px, py) || []).find((o) =>
                    o
                    && o !== pickedObj
                    && o.oclass !== COIN_CLASS
                    && o.otyp === pickedObj.otyp
                );
                if (!extra) break;
                const extraResult = player.addToInventory(extra, { withMeta: true });
                // C ref: invent.c:1142 — mark as just picked up for 'P' drop category
                if (extraResult?.item) extraResult.item.pickup_prev = 1;
                map.removeObject(extra);
            }
            await observeObject(pickedObj);
            if (addResult.discoveredByCompare) {
                await displayCtx.putstr_message('You learn more about your items by comparing them.');
            }
            const pickupMsg = formatInventoryPickupMessage(pickedObj, inventoryObj, player);
            const oldcapVal = Number.isInteger(player?._oldcap) ? player._oldcap : 0;
            const newcapVal = near_capacity(player);
            const encMsg = get_encumber_msg_for_change(oldcapVal, newcapVal);
            const combinedFits = !encMsg
                || ((pickupMsg.length + 2 + encMsg.length + 9) < Number(displayCtx?.cols || 80));

            // C ref: pickup() calls pline(pickupMsg) then encumber_msg() in
            // sequence. C's pline internally triggers --More-- via flush_screen
            // when toplin==1 (previous message pending). Both messages and their
            // More prompts are handled within a single nhgetch boundary. JS must
            // NOT split these into separate pendingPrompt steps — that creates
            // extra step boundaries that consume keys C doesn't consume.
            await pline("%s", pickupMsg);
            await encumber_msg(player);
            return { moved: false, tookTime: true };
        };

        // C ref: pick_obj() — obj_extract_self BEFORE addtobill, then addinv.
        // Remove object from floor first to match C's RNG ordering.
        if (pickedObj === obj) {
            map.removeObject(obj);
        }

        if (!player.uswallow && pickedObj !== player.uchain
            && costly_spot(obj.ox, obj.oy, map) && !pickedObj.no_charge) {
            await addtobill(pickedObj, true, false, false);
            if (game && display?.messageNeedsMore) {
                game.pendingPrompt = {
                    type: 'pickup_quote_more',
                    onKey: async (chCode, gameCtx) => {
                        if (chCode !== 32 && chCode !== 10 && chCode !== 13
                            && chCode !== 27 && chCode !== 16) {
                            return { handled: true, moved: false, tookTime: false, prompt: true };
                        }
                        dismissOwnedMore(gameCtx);
                        gameCtx.pendingPrompt = null;
                        const resumed = await finishPickupAfterBilling(gameCtx.display, gameCtx);
                        return { handled: true, ...(resumed || { moved: false, tookTime: true }) };
                    },
                };
                return { moved: false, tookTime: false, prompt: true };
            }
        }

        return finishPickupAfterBilling(display, game);
    };

    const saveQuan = obj.quan;
    const saveOwt = obj.owt;
    obj.quan = cnt_p.value;
    obj.owt = weight(obj);
    const addWt = obj.owt;
    const promptObjName = xname(obj);
    obj.quan = saveQuan;
    obj.owt = saveOwt;

    const prevEnc = near_capacity(player);
    const pickupBurden = parse_pickup_burden_level(game?.flags || player?.flags || {});
    const nextEnc = calc_capacity(player, addWt);
    if (game && nextEnc > Math.max(prevEnc, pickupBurden)) {
        await display.putstr_message(
            `${burden_prefix(nextEnc)} lifting ${promptObjName}.  Continue? [ynq] (q)`
        );
        game.pendingPrompt = {
            type: 'pickup_continue',
            onKey: async (chCode, gameCtx) => {
                if (chCode === 121 || chCode === 89) { // y/Y
                    gameCtx.pendingPrompt = null;
                    const pickupResult = await completePickup();
                    return { handled: true, ...pickupResult };
                }
                if (chCode === 110 || chCode === 78 // n/N
                    || chCode === 113 || chCode === 81 // q/Q
                    || chCode === 13 || chCode === 10
                    || chCode === 27) {
                    gameCtx.pendingPrompt = null;
                    return { handled: true, moved: false, tookTime: false };
                }
                if (chCode === 32) { // space: ack wrapped message; keep prompt active
                    return { handled: true, moved: false, tookTime: false };
                }
                return { handled: true, moved: false, tookTime: false };
            },
        };
        return { moved: false, tookTime: false, prompt: true };
    }

    return await completePickup();
}

