async function polymon(player, mntmp, map) {
    // cf. polyself.c:731 — polymon()
    // Transform player into specific monster type. Return 1 if successful.
    if (!player || mntmp < LOW_PM || mntmp >= mons.length) return 0;

    // Genocide check — mvitals not tracked yet, skip
    // if (mvitals[mntmp].mvflags & G_GENOD) {
    //     You_feel("rather %s-ish.", mons[mntmp].mname);
    //     exercise('A_WIS', true);
    //     return 0;
    // }

    // Conduct tracking
    if (!player.uconduct) player.uconduct = {};
    player.uconduct.polyselfs = (player.uconduct.polyselfs || 0) + 1;

    // Exercise — must match C RNG consumption order
    await exercise(player, A_CON, false);
    await exercise(player, A_WIS, true);

    const Upolyd = player.mtimedone > 0;

    if (!Upolyd) {
        // Human to monster; save human stats
        player.macurr = Object.assign({}, player.acurr || {});
        player.mamax = Object.assign({}, player.amax || {});
        player.mfemale = player.female;
    } else {
        // Monster to monster; restore human stats
        if (player.macurr) player.acurr = Object.assign({}, player.macurr);
        if (player.mamax) player.amax = Object.assign({}, player.mamax);
        player.female = player.mfemale;
        if (player.macurr && player.macurr.str !== undefined) {
            player.attributes[A_STR] = player.macurr.str;
        }
    }

    // Sex change check — matches C's dochange logic
    let dochange = false;
    if (is_male(mons[mntmp])) {
        if (player.female) dochange = true;
    } else if (is_female(mons[mntmp])) {
        if (!player.female) dochange = true;
    } else if (!is_neuter(mons[mntmp]) && mntmp !== player.ulycn) {
        if (player._sex_change_ok && !rn2(10))
            dochange = true;
    }

    const prevMonnum = player.umonnum;
    let buf = (player.umonnum !== mntmp) ? "" : "new ";
    if (dochange) {
        player.female = !player.female;
        if (is_male(mons[mntmp]) || is_female(mons[mntmp]))
            buf += "";
        else
            buf += player.female ? "female " : "male ";
    }
    buf += mons[mntmp].mname;
    if (player.umonnum !== mntmp)
        await You("turn into a %s!", buf);
    else
        await You("feel like a %s!", buf);

    // If stoned and poly_when_stoned, become stone golem
    if (player.stoned && poly_when_stoned(mons[mntmp])) {
        mntmp = PM_STONE_GOLEM;
        await pline("You turn to stone!");
        player.stoned = 0;
    }

    player.mtimedone = rn1(500, 500);
    player.umonnum = mntmp;
    set_uasmon(player);
    // C ref: polyself.c polymon() sets context.botl after updating monster form,
    // so the next pline() → flush_screen() → bot() picks up the new title/stats.
    player._botl = true;

    // New stats — currently only strength gets changed
    const newMaxStr = uasmon_maxStr(player);
    if (strongmonst(mons[mntmp])) {
        if (player.acurr) player.acurr.str = newMaxStr;
        if (player.amax) player.amax.str = newMaxStr;
        player.attributes[A_STR] = newMaxStr;
    } else {
        if (player.amax) player.amax.str = newMaxStr;
        if (player.acurr && player.acurr.str > newMaxStr)
            player.acurr.str = newMaxStr;
        player.attributes[A_STR] = Math.min(player.attributes[A_STR] || newMaxStr, newMaxStr);
    }

    // Stone_resistance && Stoned -> clear petrification
    if (player.stoned && ((mons[mntmp].mresists || 0) & MR_STONE)) {
        player.stoned = 0;
        await You("no longer seem to be petrifying.");
    }
    // Sick_resistance && Sick -> clear sickness
    if (player.sick && (mons[mntmp].mlet === S_FUNGUS || mons[mntmp] === mons[PM_GHOUL])) {
        player.sick = 0;
        await You("no longer feel sick.");
    }
    // Slimed handling
    if (player.slimed) {
        if (flaming(mons[mntmp])) {
            player.slimed = 0;
            await pline("The slime burns away!");
        } else if (mntmp === PM_GREEN_SLIME) {
            player.slimed = 0; // silently
        }
    }
    await check_strangling(player, false); // maybe stop strangling
    if (nohands(mons[mntmp])) {
        player.glib = 0;
    }

    // Hit point calculation — must match C's RNG consumption
    const mlvl = mons[mntmp].mlevel || 0;
    if (mons[mntmp].mlet === S_DRAGON && mntmp >= PM_GRAY_DRAGON) {
        const inEndgame = player.inEndgame || false;
        player.mhmax = inEndgame ? (8 * mlvl) : (4 * mlvl + c_d(mlvl, 4));
    } else if (is_golem(mons[mntmp])) {
        player.mhmax = golemhp(mntmp);
    } else {
        if (!mlvl)
            player.mhmax = rnd(4);
        else
            player.mhmax = c_d(mlvl, 8);
        if (is_home_elemental(mons[mntmp]))
            player.mhmax *= 3;
    }
    player.mh = player.mhmax;

    // Low level characters can't be high level monsters for long
    if ((player.ulevel || 1) < mlvl) {
        player.mtimedone = Math.floor(player.mtimedone * (player.ulevel || 1) / mlvl);
    }

    // Handle skin/armor/weapon
    if (player.uskin && mntmp !== armor_to_dragon((player.uskin.otyp || 0)))
        await skinback(player, false);
    await break_armor(player);
    await drop_weapon(player, 1);
    find_ac(player);

    // Pit escape timer reset
    if (player.utrap && player.utraptype === TT_PIT) {
        player.utrap = rn1(6, 2);
    }

    // Blindness: if was eyeless and now can see
    if (player.blind && haseyes(mons[mntmp])) {
        player.blind = 0;
        mark_vision_dirty();
    }

    // C ref: polyself.c:899 — newsym after break_armor/drop_weapon/find_ac/pit/blindness
    newsym(player.x, player.y, map || _gstate?.map || null);

    // Egg type learning
    if (lays_eggs(mons[mntmp])) {
        await learn_egg_type(mntmp, _gstate);
    }

    // Engulf/swallow handling
    if (player.uswallow && player.ustuck) {
        const usiz = mons[mntmp].msize || 0;
        const ustdata = player.ustuck.type || player.ustuck.data;
        if (unsolid(mons[mntmp])
            || usiz >= MZ_HUGE
            || (ustdata && ustdata.msize < usiz && !is_whirly(ustdata))) {
            if (unsolid(mons[mntmp])) {
                await pline("%s can no longer contain you.",
                    player.ustuck.name || "It");
            }
            await expels(player.ustuck, player.ustuck?.data, true, player);
        }
    } else if (player.ustuck && !player.uswallow) {
        // Being held; if now capable of holding or unsolid, release
        if (sticks(mons[mntmp]) || unsolid(mons[mntmp])) {
            const stuckName = (player.ustuck.name || "It");
            player.ustuck = null;
            await pline("%s loses its grip on you.", stuckName);
        }
    }

    // Steed handling
    if (player.usteed) {
        if (!can_ride(player.usteed, player)) {
            await dismount_steed(player);
        }
    }

    find_ac(player);

    // Pool/lava spoteffects
    await spoteffects(true, player, map || _gstate?.map || null, _gstate?.display || _gstate?.disp || null, _gstate || null);

    // Passes_walls trap handling
    if (passes_walls(mons[mntmp]) && player.utrap) {
        // TT_INFLOOR, TT_BURIEDBALL from trap.js
        if (player.utraptype === TT_INFLOOR) {
            await pline_The("rock seems to no longer trap you.");
            player.utrap = 0;
        } else if (player.utraptype === TT_BURIEDBALL) {
            await pline_The("buried ball is no longer bound to you.");
            player.utrap = 0;
        }
    }

    // Lava-loving creatures
    if (likes_lava(mons[mntmp]) && player.utrap && player.utraptype === TT_LAVA) {
        await pline_The("lava now feels soothing.");
        player.utrap = 0;
    }

    // Amorphous/whirly/unsolid: slip out of chains, traps
    if (amorphous(mons[mntmp]) || is_whirly(mons[mntmp]) || unsolid(mons[mntmp])) {
        if (player.punished) {
            await You("slip out of the iron chain.");
            player.punished = false;
        }
        // TT_WEB, TT_BEARTRAP from trap.js
        if (player.utrap && (player.utraptype === TT_WEB || player.utraptype === TT_BEARTRAP)) {
            await You("are no longer stuck in the %s.",
                player.utraptype === TT_WEB ? "web" : "bear trap");
            player.utrap = 0;
        }
    }

    // Small creatures can escape bear traps and webs
    if (player.utrap) {
        // TT_WEB, TT_BEARTRAP from trap.js
        if ((player.utraptype === TT_WEB || player.utraptype === TT_BEARTRAP)
            && (mons[mntmp].msize !== undefined && mons[mntmp].msize <= MZ_SMALL)) {
            await You("are no longer stuck in the %s.",
                player.utraptype === TT_WEB ? "web" : "bear trap");
            player.utrap = 0;
        }
    }

    // Webmaker in web: orient yourself
    if (webmaker(mons[mntmp]) && player.utrap && player.utraptype === TT_WEB) {
        await You("orient yourself on the web.");
        player.utrap = 0;
    }

    await check_strangling(player, true); // maybe start strangling

    player._botl = true; // C: disp.botl = TRUE (polymon end)
    // Encumbrance, retouch equipment, selftouch
    await encumber_msg(player);
    await retouch_equipment(2, player);
    if (!player.gloves) {
        selftouch("No longer petrify-resistant, you", player);
    }

    // Verbose #monster hints
    const uptr = mons[mntmp];
    const might_hide = (is_hider(uptr) || hides_under(uptr));

    if (can_breathe(uptr))
        await pline("Use the command #monster to use your breath weapon.");
    if (attacktype(uptr, AT_SPIT))
        await pline("Use the command #monster to spit venom.");
    if (uptr.mlet === S_NYMPH)
        await pline("Use the command #monster to remove an iron ball.");
    if (attacktype(uptr, AT_GAZE))
        await pline("Use the command #monster to gaze at monsters.");
    if (might_hide && webmaker(uptr))
        await pline("Use the command #monster to hide or to spin a web.");
    else if (might_hide)
        await pline("Use the command #monster to hide.");
    else if (webmaker(uptr))
        await pline("Use the command #monster to spin a web.");
    if (is_were(uptr))
        await pline("Use the command #monster to summon help.");
    if (mntmp === PM_GREMLIN)
        await pline("Use the command #monster to multiply in a fountain.");
    if (is_unicorn(uptr))
        await pline("Use the command #monster to use your horn.");
    if (is_mind_flayer(uptr))
        await pline("Use the command #monster to emit a mental blast.");
    if (uptr.msound === MS_SHRIEK)
        await pline("Use the command #monster to shriek.");
    if (is_vampire(uptr))
        await pline("Use the command #monster to change shape.");
    if (lays_eggs(uptr) && player.female
        && !(uptr === mons[PM_GIANT_EEL] || uptr === mons[PM_ELECTRIC_EEL]))
        await pline("Use the command #sit to lay an egg.");

    return 1;
}

async function dogaze(player, map) {
    // cf. polyself.c:1626 — dogaze()
    // Gaze attack for polymorphed player (umber hulk confuse, flaming sphere fire).
    if (!player || !player.type) return 0;

    let adtyp = 0;
    const attacks = player.type.mattk || player.type.attacks || [];
    for (let i = 0; i < attacks.length; i++) {
        if (attacks[i].aatyp === AT_GAZE) {
            adtyp = attacks[i].adtyp;
            break;
        }
    }
    if (adtyp !== AD_CONF && adtyp !== AD_FIRE) {
        await pline("gaze attack %d?", adtyp); // impossible in C
        return 0;
    }

    if (player.blind) {
        await You_cant("see anything to gaze at.");
        return 0;
    } else if (player.hallucination) {
        await You_cant("gaze at anything you can see.");
        return 0;
    }
    if ((player.uen || 0) < 15) {
        await You("lack the energy to use your special gaze!");
        return 0;
    }
    player.uen -= 15;
    player._botl = true; // C: disp.botl = TRUE

    let looked = 0;
    const monsters = map ? map.monsters || [] : [];

    for (const mtmp of monsters) {
        if (!mtmp || mtmp.dead || (mtmp.mhp || 0) <= 0) continue;
        // Check visibility — simplified: use distance and LOS
        // In C: canseemon(mtmp) && couldsee(mtmp->mx, mtmp->my)
        const mx = mtmp.x !== undefined ? mtmp.x : (mtmp.mx || 0);
        const my = mtmp.y !== undefined ? mtmp.y : (mtmp.my || 0);
        const d2 = dist2(player.x, player.y, mx, my);
        if (d2 > BOLT_LIM * BOLT_LIM) continue;
        // Simplified visibility check
        if (!mtmp.visible && !mtmp.detected) continue;

        looked++;
        const mdata = mtmp.data || mtmp.type;
        if (!mdata) continue;

        // Invisible player check
        if (player.Invis && !perceives(mdata)) {
            await pline("%s seems not to notice your gaze.", Monnam(mtmp));
        } else if (mtmp.invisible && !player.seeInvisible) {
            await You_cant("see where to gaze at %s.", Monnam(mtmp));
        } else if (player.safeDog && mtmp.mtame && !player.confused) {
            await You("avoid gazing at %s.", mon_nam(mtmp));
        } else {
            // Peaceful monster confirmation check
            if (player.confirm && mtmp.mpeaceful && !player.confused) {
                // In C, yn query "Really confuse/attack <mon>?"
                // Skip if y_n returns 'n'; for JS, proceed by default
            }
            setmangry(mtmp, true, map, player);

            // Skip helpless, stunned, blind, eyeless targets
            if (mtmp.helpless || mtmp.mstun
                || !mtmp.canSee || !haseyes(mdata)) {
                looked--;
                continue;
            }

            if (adtyp === AD_CONF) {
                if (!mtmp.mconf)
                    await Your("gaze confuses %s!", mon_nam(mtmp));
                else
                    await pline("%s is getting more and more confused.", Monnam(mtmp));
                mtmp.mconf = 1;
            } else if (adtyp === AD_FIRE) {
                // RNG: d(2,6) for fire damage, rn2(20) for item destroy chance
                let dmg = c_d(2, 6);
                const orig_dmg = dmg;
                const lev = player.ulevel || 1;

                await You("attack %s with a fiery gaze!", mon_nam(mtmp));
                if (resists_fire(mtmp)) {
                    await pline_The("fire doesn't burn %s!", mon_nam(mtmp));
                    dmg = 0;
                }
                if (lev > rn2(20)) {
                    // TODO: C calls destroy_mitem(mtmp, AD_FIRE, orig_dmg) here
                // but destroy_mitem signature is (mon, osym, dmgtyp) — needs audit
                    ignite_items(player, _gstate);
                }
                if (dmg) {
                    mtmp.mhp = (mtmp.mhp || 0) - dmg;
                }
                if ((mtmp.mhp || 0) <= 0) {
                    await killed(mtmp, map, player);
                }
            }

            // Counterattacks from gazed monsters
            if ((mtmp.mhp || 0) <= 0) continue;

            // Floating eye freeze — RNG: rn2(4), d(mlev+1, damd)
            if (mdata === mons[PM_FLOATING_EYE] && !mtmp.cancelled) {
                const Free_action = player.freeAction || false;
                if (!Free_action) {
                    await You("are frozen by %s gaze!", s_suffix(mon_nam(mtmp)));
                    const mlev = mdata.mlevel || 0;
                    const damd = (mdata.attacks && mdata.attacks[0])
                        ? (mdata.attacks[0].damd || 1) : 1;
                    const freezeTime = ((player.ulevel || 1) > 6 || rn2(4))
                        ? -d(mlev + 1, damd)
                        : -200;
                    nomul(freezeTime, _gstate);
                    if (_gstate) _gstate.multi_reason = "frozen by a monster's gaze";
                    return 1;
                } else {
                    await You("stiffen momentarily under %s gaze.",
                        s_suffix(mon_nam(mtmp)));
                }
            }

            // Medusa gaze counter
            if (mdata === mons[PM_MEDUSA] && !mtmp.cancelled) {
                await pline("Gazing at the awake %s is not a very good idea.",
                    mon_nam(mtmp));
                await pline("You turn to stone...");
                await done(STONING, _gstate);
            }
        }
    }

    if (!looked) {
        await You("gaze at no place in particular.");
    }
    return 1; // ECMD_TIME
}

async function potionhit(mon, obj, how, player, map) {
    const isyou = (mon === player);
    const botlnam = bottlename(player);
    const your_fault = (how <= 1); // POTHIT_HERO_THROW = 1

    if (isyou) {
        await pline("The %s crashes on your %s and breaks into shards.", botlnam, body_part(HEAD));
        // losehp(rnd(2)) — damage from bottle
        const bottleDmg = rnd(2);
        player.uhp -= bottleDmg;
        if (player.uhp < 1) player.uhp = 1;
    } else {
        // C ref: potion.c:1649-1672 — crash message + bottle damage for monster target
        const mdat = mon.data || (mons ? mons[mon.mndx] : null) || {};
        if (player.blind) {
            await pline("Crash!");
        } else {
            let buf;
            if (has_head(mdat)) {
                buf = `${mon_nam(mon)}'s head`;
            } else {
                buf = mon_nam(mon);
            }
            await pline("The %s crashes on %s and breaks into shards.", botlnam, buf);
        }
        if (rn2(5) && mon.mhp > 1)
            mon.mhp--;
    }

    // C ref: potion.c:1676-1677 — evaporate message
    if (obj.otyp !== POT_OIL && !player.blind) {
        await pline("%s.", Tobjnam(obj, "evaporate"));
    }

    if (isyou) {
        // hero potion effects from being hit
        switch (obj.otyp) {
        case POT_ACID:
            if (!(player.uprops[ACID_RES] &&
                  (player.uprops[ACID_RES].intrinsic || player.uprops[ACID_RES].extrinsic))) {
                await pline("This burns%s!",
                      obj.blessed ? " a little" : obj.cursed ? " a lot" : "");
                const dmg = c_d(obj.cursed ? 2 : 1, obj.blessed ? 4 : 8);
                player.uhp -= dmg;
                if (player.uhp < 1) player.uhp = 1;
            }
            break;
        case POT_POLYMORPH:
            await You_feel("a little %s.", player.hallucinating ? "normal" : "strange");
            break;
        // other potion types: oil lamp explosion, etc. omitted
        }
    } else {
        // monster potion effects
        let angermon = your_fault;
        let cureblind = false;

        switch (obj.otyp) {
        case POT_FULL_HEALING:
            cureblind = true;
            // fallthrough
        case POT_EXTRA_HEALING:
            if (obj.otyp === POT_EXTRA_HEALING || obj.otyp === POT_FULL_HEALING) {
                if (!obj.cursed) cureblind = true;
            }
            // fallthrough
        case POT_HEALING:
            if (obj.otyp === POT_HEALING && obj.blessed) cureblind = true;
            // fallthrough
        case POT_RESTORE_ABILITY:
        case POT_GAIN_ABILITY:
            // C ref: potion.c:1745-1753 — do_healing label
            angermon = false;
            if (mon.mhp < (mon.mhpmax || mon.mhp)) {
                healmon(mon, mon.mhpmax || mon.mhp, 0);
                if (canspotmon(mon, player))
                    await pline("%s looks sound and hale again.", Monnam(mon));
            }
            if (cureblind)
                await mcureblindness(mon, canspotmon(mon, player), player);
            break;
        case POT_SICKNESS: {
            // C ref: potion.c:1755-1773 — disease/poison resist checks
            const monData = mon.data || (mons ? mons[mon.mndx] : {});
            if (dmgtype(monData, AD_DISE) || dmgtype(monData, AD_PEST)
                || resists_poison(mon)) {
                if (canspotmon(mon, player))
                    await pline("%s looks unharmed.", Monnam(mon));
                break;
            }
            if (mon.mhp > 2) {
                mon.mhp = Math.floor(mon.mhp / 2);
                if (canspotmon(mon, player))
                    await pline("%s looks rather ill.", Monnam(mon));
            }
            break;
        }
        case POT_CONFUSION:
        case POT_BOOZE:
            // C ref: potion.c:1776 — resist gate before applying confusion
            if (!resist(mon, POTION_CLASS))
                mon.mconf = true;
            break;
        case POT_INVISIBILITY:
            angermon = false;
            mon_set_minvis(mon, map);
            break;
        case POT_SLEEPING: {
            // C ref: potion.c:1788-1793 — sleep_monst(mon, rnd(12), POTION_CLASS)
            // C does NOT set angermon=FALSE for sleeping potions.
            // wakeup(mon, TRUE) clears msleeping and makes hostile, but doesn't
            // undo the mcanmove=0/mfrozen from sleep_monst.
            const sleepamt = rnd(12);
            if (!resist(mon, POTION_CLASS) && mon.mcanmove !== false) {
                mon.mcanmove = false;
                mon.mfrozen = Math.min((mon.mfrozen || 0) + sleepamt, 127);
                // C ref: potionhit() — print "falls asleep" and makeknown on success
                // C does NOT gate on canspotmon here (unlike some other potion cases)
                await pline("%s falls asleep.", Monnam(mon));
                await discoverObject(obj.otyp, true, true, false);
            }
            break;
        }
        case POT_PARALYSIS:
            if (mon.mcanmove !== false) {
                mon.mcanmove = false;
                mon.mfrozen = rnd(25);
            }
            break;
        case POT_SPEED:
            angermon = false;
            mon_adjust_speed(mon, 1, obj);
            break;
        case POT_BLINDNESS: {
            // C ref: potion.c:1808-1815
            // C: if (haseyes(mon->data) && !mon_perma_blind(mon))
            //    btmp = 64 + rn2(32) + rn2(32) * !resist(mon, POTION_CLASS, 0, NOTELL);
            const monData = mon.data || (mons ? mons[mon.mndx] : {});
            if (haseyes(monData) && mon.mcansee !== false) {
                const r1 = rn2(32);
                const r2 = rn2(32);
                const resisted = resist(mon, POTION_CLASS) ? 0 : 1;
                const btmp = Math.min(64 + r1 + r2 * resisted + (mon.mblinded || 0), 127);
                mon.mblinded = btmp;
                mon.mcansee = false;
            }
            break;
        }
        case POT_ACID: {
            // C ref: potion.c:1857 — resists_acid + resist gate
            if (!resists_acid(mon) && !resist(mon, POTION_CLASS)) {
                const acidDmg = c_d(obj.cursed ? 2 : 1, obj.blessed ? 4 : 8);
                mon.mhp -= acidDmg;
            }
            break;
        }
        case POT_WATER: {
            // C ref: potion.c:1817-1851 — holy/unholy water effects
            const monData = mon.data || (mons ? mons[mon.mndx] : {});
            if (mon_hates_blessings(mon) || is_were(monData) || is_vampshifter(mon)) {
                if (obj.blessed) {
                    if (is_silent(monData))
                        await pline("%s writhes in pain!", Monnam(mon));
                    else
                        await pline("%s shrieks in pain!", Monnam(mon));
                    mon.mhp -= c_d(2, 6);
                    if (mon.mhp <= 0) {
                        await mondead_full(mon, map);
                    } else if (is_were(monData) && !is_human(monData)) {
                        await new_were(mon);
                    }
                } else if (obj.cursed) {
                    angermon = false;
                    if (canspotmon(mon, player))
                        await pline("%s looks healthier.", Monnam(mon));
                    healmon(mon, c_d(2, 6), 0);
                    if (is_were(monData) && is_human(monData))
                        await new_were(mon);
                }
            } else if (mon.mndx === PM_GREMLIN) {
                angermon = false;
                await split_mon(mon, null);
            } else if (mon.mndx === PM_IRON_GOLEM) {
                if (canspotmon(mon, player))
                    await pline("%s rusts.", Monnam(mon));
                mon.mhp -= c_d(1, 6);
                if (mon.mhp <= 0)
                    await mondead_full(mon, map);
            }
            break;
        }
        case POT_POLYMORPH:
            // C ref: potion.c:1871-1873 — bhitm(mon, obj) for polymorph
            await bhitm(mon, obj, map, player);
            break;
        } // close switch (obj.otyp)

        // C ref: potion.c:1884-1889 — post-switch wake logic
        if (mon.mhp > 0) {
            if (angermon) {
                // C: wakeup(mon, TRUE) — clears msleeping, sets hostile
                mon.msleeping = false;
                mon.mpeaceful = false;
            } else {
                // C: mon->msleeping = 0 — clear natural sleep flag
                // (frozen sleep via mcanmove/mfrozen is unaffected)
                mon.msleeping = false;
            }
        }
    }

    // C ref: potion.c potionhit() end — potionbreathe gate
    // potionbreathe() does its own docall()
    // distance == 0 when hero is the target; distu(tx,ty) otherwise
    // Gate: (distance == 0 || (distance < 3 && !rn2((1+ACURR(A_DEX))/2)))
    //       && (!breathless(youmonst.data) || haseyes(youmonst.data))
    let distance;
    if (isyou) {
        distance = 0;
    } else {
        const mx = mon.mx ?? mon.x ?? 0;
        const my = mon.my ?? mon.y ?? 0;
        distance = (player.x - mx) * (player.x - mx) + (player.y - my) * (player.y - my);
    }
    const playerData = player.youmonst?.data || player.data || {};
    if ((distance === 0 || (distance < 3 && !rn2(Math.floor((1 + acurr(player, A_DEX)) / 2))))
        && (!breathless(playerData) || haseyes(playerData))) {
        await potionbreathe(player, obj);
    }
    // C ref: potion.c:2113 — if effect was observed, makeknown; else trycall
    // The per-case discoverObject calls (e.g., POT_SLEEPING) set kn implicitly.
    // For cases without explicit discovery, fall through to trycall.
    if (obj.dknown && !obj._potionhitKnown) {
        await trycall(obj);
    }
}

