async function replaySession(seed, opts, keys) {
    if (typeof globalThis.window === 'undefined') {
        globalThis.window = {};
    }
    enableRngLog();

    const display = new Display();
    const input = createHeadlessInput();
    const game = new NetHackGame({ display, input });
    const synclockDiagTypes = [
        'boundary.more.owner-missing',
        'boundary.more.fallback-no-owner',
        'boundary.more.fallback-synced',
        'boundary.more.clear-missing',
    ];
    const synclockDiagCounts = Object.fromEntries(synclockDiagTypes.map((type) => [type, 0]));
    let synclockDiagTotal = 0;
    const unsubscribeDiagnostics = (typeof game.subscribeDiagnostics === 'function')
        ? game.subscribeDiagnostics((ev) => {
            const type = String(ev?.type || '');
            if (!Object.hasOwn(synclockDiagCounts, type)) return;
            synclockDiagCounts[type] += 1;
            synclockDiagTotal += 1;
        })
        : null;
    // Pre-push chargen keys if provided.
    if (Array.isArray(opts.chargenKeys)) {
        for (const key of opts.chargenKeys) {
            for (let i = 0; i < key.length; i++) {
                input.pushKey(key.charCodeAt(i));
            }
        }
    }

    const initOpts = { seed, ...(opts.initOpts || {}) };
    let initPromise = null;
    let startupPending = false;
    initPromise = game.init(initOpts);
    const settled = await drainUntilInput(initPromise, game.input);
    if (settled.done) {
        settleStartupInputBoundaries(game, opts);
        emitStartupRunstepIfEnabled(game);
        initPromise = null;
    } else {
        startupPending = true;
    }

    // The welcome/lore message from init may still be visible on the topline.
    // Leave it in place so step 0 shows the natural post-init screen state.
    // The first keystroke (typically space) will dismiss it via --More--.

    // Apply display flags.
    if (opts.displayFlags && typeof opts.displayFlags === 'object') {
        Object.assign(game.display.flags, opts.displayFlags);
        Object.assign(game.flags, opts.displayFlags);
        const player = game.u || game.u;
        if (player) {
            player.showExp = !!opts.displayFlags.showexp;
            player.showTime = !!opts.displayFlags.time;
            player.showScore = !!opts.displayFlags.showscore;
        }
        // C ref: game.init() renders with default flags; if DECgraphics changed,
        // clear remembered terrain chars and re-render so step 0 captures correct symbols.
        const map = game.map || game.map;
        if (map && opts.displayFlags.DECgraphics != null) {
            for (let x = 1; x < 80; x++) {
                for (let y = 0; y < 21; y++) {
                    const loc = map.at(x, y);
                    if (loc) delete loc.mem_terrain_ch;
                }
            }
            const player = game.u || game.u;
            if (player && typeof game.display?.renderMap === 'function') {
                game.display.renderMap(map, player, game.fov, game.flags);
            }
        }
    }

    // steps[0]: startup frame
    const startupRng = getRngLog().map(toCompactRng);
    const steps = [{
        key: null,
        rng: startupRng,
        screen: opts.captureScreens ? captureScreen(display) : '',
        cursor: captureCursor(display),
    }];

    // Feed each keystroke to the game, record results.
    let pendingCommand = null;

    const drainCommandForCurrentStep = async (commandPromise) => {
        const settled = await drainUntilInput(commandPromise, game.input);
        if (!settled.done) {
            pendingCommand = commandPromise;
            return;
        }
        pendingCommand = null;
    };

    for (let i = 0; i < keys.length; i++) {
        const preMap = game.map || game.map || null;
        if (preMap) preMap._replayStepIndex = i;
        const prevCount = getRngLog().length;
        const ch = keys.charCodeAt(i);
        // Expose current replay step to runtime diagnostics (run/monmove traces).
        // This is debug-only metadata and does not affect game logic.
        if (game?.map) game.map._replayStepIndex = i;
        if (game?.lev) game.map._replayStepIndex = i;

        if (startupPending && initPromise) {
            replayPendingTrace(
                `step=${i + 1}`,
                `key=${JSON.stringify(String.fromCharCode(ch))}`,
                'mode=startup',
                replayBoundaryState(game, game.input)
            );
            pushInput(ch);
            const settled = await drainUntilInput(initPromise, game.input);
            if (settled.done) {
                startupPending = false;
                settleStartupInputBoundaries(game, opts);
                emitStartupRunstepIfEnabled(game);
                initPromise = null;
                replayPendingTrace(
                    `step=${i + 1}`,
                    'startup=done',
                    replayBoundaryState(game, game.input)
                );
            } else {
                replayPendingTrace(
                    `step=${i + 1}`,
                    'startup=waiting',
                    pendingWaitSite(game.input),
                    replayBoundaryState(game, game.input)
                );
            }
        } else if (pendingCommand) {
            replayPendingTrace(
                `step=${i + 1}`,
                `key=${JSON.stringify(String.fromCharCode(ch))}`,
                'mode=resume',
                replayBoundaryState(game, game.input)
            );
            pushInput(ch);
            await drainCommandForCurrentStep(pendingCommand);
            if (!pendingCommand) {
                replayPendingTrace(
                    `step=${i + 1}`,
                    'resume=done',
                    pendingWaitSite(game.input),
                    replayBoundaryState(game, game.input)
                );
            } else {
                replayPendingTrace(
                    `step=${i + 1}`,
                    'resume=waiting',
                    pendingWaitSite(game.input),
                    replayBoundaryState(game, game.input)
                );
            }
        } else {
            pushInput(ch);
            const commandPromise = game._gameLoopStep();
            await drainCommandForCurrentStep(commandPromise);
            if (pendingCommand) {
                replayPendingTrace(
                    `step=${i + 1}`,
                    `key=${JSON.stringify(String.fromCharCode(ch))}`,
                    'mode=start-gameloop',
                    'start=waiting',
                    pendingWaitSite(game.input),
                    replayBoundaryState(game, game.input)
                );
            } else {
                replayPendingTrace(
                    `step=${i + 1}`,
                    `key=${JSON.stringify(String.fromCharCode(ch))}`,
                    'mode=start-gameloop',
                    'start=done',
                    replayBoundaryState(game, game.input)
                );
            }
        }

        // Rendering ownership lives in run_command/game runtime paths.
        // Replay captures the already-rendered screen after each consumed key.
        const postMap = game.map || game.map || null;
        if (postMap) postMap._replayStepIndex = i;

        // C ref: the C harness captures the tmux screen AFTER the key is
        // fully processed (including deferred_goto which runs inside
        // run_command). Screen capture here reflects the post-command state.
        // When a command completes (!pendingCommand), C's bot() has run and the
        // terminal reflects the updated status. Force a renderStatus refresh
        // to match, since JS only calls renderStatus at explicit boundaries.
        await Promise.resolve();
        const startupHasLiveMap = !!(game?.map || game?.lev);
        const startupLoreVisible = game?.pendingPrompt?.source === 'startup_lore';
        // When a command completes (!pendingCommand), C's bot() has run and the
        // terminal reflects the updated status. Force a renderStatus refresh
        // to match, since JS only calls renderStatus at explicit boundaries.
        if ((!startupPending || startupHasLiveMap) && !pendingCommand && !startupLoreVisible
            && opts.captureScreens && !game.gameOver) {
            const player = game.u || game.u;
            if (player && typeof display.renderStatus === 'function') {
                display._suppressReplayCaptureRepaint = true;
                try {
                    display.renderStatus(player);
                } finally {
                    display._suppressReplayCaptureRepaint = false;
                }
            }
        }
        const screenCapture = opts.captureScreens ? captureScreen(display) : '';
        const cursorCapture = captureCursor(display);

        const raw = getRngLog().slice(prevCount);
        const step = {
            key: keys[i],
            rng: raw.map(toCompactRng),
            screen: screenCapture,
            cursor: cursorCapture,
        };
        steps.push(step);

        if (typeof opts.onKey === 'function') {
            opts.onKey({ index: i, ch: keys[i], game, step });
        }
    }

    // If session ends while a command is waiting for input, cancel with ESC.
    if (pendingCommand) {
        pushInput(27);
        const settled = await Promise.race([
            pendingCommand.then(() => true, () => true),
            new Promise((resolve) => setTimeout(() => resolve(false), 20)),
        ]);
        if (!settled) {
            pushInput(13);
            await Promise.race([
                pendingCommand.then(() => true, () => true),
                new Promise((resolve) => setTimeout(() => resolve(false), 20)),
            ]);
        }
    }

    disableRngLog();

    const checkpoints = consumeHarnessMapdumpPayloads();
    if (typeof unsubscribeDiagnostics === 'function') unsubscribeDiagnostics();

    return {
        version: 3,
        seed,
        source: 'js',
        steps,
        checkpoints,
        synclockDiagnostics: {
            total: synclockDiagTotal,
            counts: synclockDiagCounts,
        },
    };
}

async function dopay(game) {
    const { map, u: player } = game;
    if (!map) return 0;
    let tookTime = false;
    const moneyOnHand = () => {
        let total = Number(player?.gold || 0);
        const inv = Array.isArray(player?.inventory) ? player.inventory : [];
        for (const otmp of inv) {
            if (!otmp) continue;
            if (otmp.oclass === COIN_CLASS || otmp.otyp === GOLD_PIECE) {
                total += Number(otmp.quan || 0);
            }
        }
        return total;
    };

    const monsters = map.monsters || [];
    const hereRooms = in_rooms(map, player.x, player.y, SHOPBASE);
    let sk = 0, seensk = 0, nexttosk = 0;
    let nxtm = null;
    let resident = null;

    for (const m of monsters) {
        if (!m || m.dead || !m.isshk) continue;
        sk++;
        if (m_next2u(m, player)) {
            nexttosk++;
            if (!nxtm || nxtm.mpeaceful !== false) nxtm = m;
        }
        if (canspotmon(m)) seensk++;
        if (hereRooms.length > 0 && Number(m.shoproom || 0) === hereRooms[0] && inhishop(m, map)) {
            resident = m;
        }
    }
    let shkp = null;
    if (nxtm && nexttosk === 1) {
        shkp = nxtm;
    } else if (!sk) {
        await There("appears to be no shopkeeper here to receive your payment.");
        return 0;
    } else if (!seensk) {
        await You_cant("see...");
        return 0;
    } else if (sk === 1 && resident) {
        shkp = resident;
    } else if (seensk === 1) {
        shkp = monsters.find((m) => m && !m.dead && m.isshk && canspotmon(m)) || null;
        if (shkp && shkp !== resident && !m_next2u(shkp, player)) {
            await pline("%s is not near enough to receive your payment.", Shknam(shkp));
            return 0;
        }
    } else if (resident) {
        shkp = resident;
    } else {
        await pline("Pay whom?");
        const cc = { x: Number(player?.x || 1), y: Number(player?.y || 0) };
        const pick = await getpos_async(cc, true, "the creature you want to pay", { map, display: game?.display, player });
        if (pick < 0) return 0;
        const cx = Number(cc.x);
        const cy = Number(cc.y);
        if (cx < 0) {
            await pline("Try again...");
            return 0;
        }
        if (cx === Number(player?.x) && cy === Number(player?.y)) {
            await You("are generous to yourself.");
            return 0;
        }
        const mtmp = (typeof map.monsterAt === 'function')
            ? map.monsterAt(cx, cy)
            : (map.monsters || []).find((m) => m && !m.dead && Number(m.mx) === cx && Number(m.my) === cy);
        if (!mtmp || !canspotmon(mtmp)) {
            await You("can't see anyone there.");
            return 0;
        }
        if (!mtmp.isshk) {
            await pline("%s is not interested in your payment.", y_monnam(mtmp));
            return 0;
        }
        if (mtmp !== resident && !m_next2u(mtmp, player)) {
            await pline("%s is too far to receive your payment.", Shknam(mtmp));
            return 0;
        }
        shkp = mtmp;
    }

    if (!shkp) return 0;
    const robbed = Number(shkp.robbed || 0);
    if (robbed || Number(ESHK(shkp)?.billct || 0) || Number(ESHK(shkp)?.debit || 0)) {
        await rouse_shk(shkp, true);
    }
    if (monHelpless(shkp)) {
        await pline("%s %s.", Shknam(shkp), rn2(2) ? "seems to be napping" : "doesn't respond");
        return 0;
    }

    if (shkp !== resident && shkp.mpeaceful !== false) {
        const umoney = moneyOnHand();
        if (!robbed) {
            await You("do not owe %s anything.", shkname(shkp));
            tookTime = true;
        } else if (!umoney) {
            await You("have no gold.");
            tookTime = true;
        } else {
            await pay(Math.min(umoney, robbed), shkp, game);
            if (umoney >= robbed) {
                await make_happy_shk(shkp, false, map);
            }
            tookTime = true;
        }
        return tookTime ? 1 : 0;
    }

    let paid = false;
    let pay_done = true;
    const eshkp = ESHK(shkp);

    if (!eshkp.billct && !eshkp.debit) {
        const umoney = moneyOnHand();
        if (!robbed && shkp.mpeaceful !== false) {
            await You("do not owe %s anything.", shkname(shkp));
            if (!umoney) await pline("You have no money.");
            tookTime = true;
        } else if (robbed) {
            await pline("%s is after blood, not gold!", shkname(shkp));
            if (umoney < Math.floor(robbed / 2)) {
                if (!umoney) await pline("You have no money.");
                else await pline("You don't have enough to interest %s.", mhim(shkp));
                return 1;
            }
            await pline("But since %s shop has been robbed recently,", mhis(shkp));
            await pline("you %scompensate %s for %s losses.",
                (umoney < robbed) ? "partially " : "", shkname(shkp), mhis(shkp));
            await pay(umoney < robbed ? umoney : robbed, shkp, game);
            await make_happy_shk(shkp, false, map);
            tookTime = true;
        } else {
            await pline("%s is after your hide, not your gold!", Shknam(shkp));
            if (umoney < 1000) {
                if (!umoney) await pline("You have no money.");
                else await pline("You don't have enough to interest %s.", mhim(shkp));
                return 1;
            }
            await You("try to appease %s by giving %s 1000 gold pieces.",
                canspotmon(shkp) ? `the angry ${shkname(shkp)}` : shkname(shkp), mhim(shkp));
            await pay(1000, shkp, game);
            if (rn2(3)) {
                await make_happy_shk(shkp, false, map);
            } else {
                await pline("But %s is as angry as ever.", shkname(shkp));
            }
            tookTime = true;
        }
        return tookTime ? 1 : 0;
    }

    if (shkp !== resident) {
        impossible("dopay: not to shopkeeper?");
        if (resident) setpaid(resident);
        return 0;
    }

    if (eshkp.debit) {
        let dtmp = Number(eshkp.debit || 0);
        const loan = Number(eshkp.loan || 0);
        const umoney = moneyOnHand();
        let debtMsg = `You owe ${shkname(shkp)} ${dtmp} ${currency(dtmp)} `;
        if (loan) {
            debtMsg += (loan === dtmp)
                ? "you picked up in the store."
                : "for gold picked up and the use of merchandise.";
        } else {
            debtMsg += "for the use of merchandise.";
        }
        await pline("%s", debtMsg);

        if (umoney + Number(eshkp.credit || 0) < dtmp) {
            await pline("But you don't have enough gold%s.", eshkp.credit ? " or credit" : "");
            return 1;
        }

        if (Number(eshkp.credit || 0) >= dtmp) {
            eshkp.credit = Number(eshkp.credit || 0) - dtmp;
            eshkp.debit = 0;
            eshkp.loan = 0;
            await Your("debt is covered by your credit.");
        } else if (!Number(eshkp.credit || 0)) {
            money2mon(shkp, dtmp);
            eshkp.debit = 0;
            eshkp.loan = 0;
            await You("pay that debt.");
        } else {
            dtmp -= Number(eshkp.credit || 0);
            eshkp.credit = 0;
            money2mon(shkp, dtmp);
            eshkp.debit = 0;
            eshkp.loan = 0;
            await pline("That debt is partially offset by your credit.");
            await You("pay the remainder.");
        }
        paid = true;
        tookTime = true;
    }

    if (eshkp.billct) {
        const ibill = make_itemized_bill(shkp);
        const paidRef = { paid };
        if (!await pay_billed_items(shkp, ibill.length, ibill, false, paidRef)) {
            pay_done = false;
        } else {
            paid = paidRef.paid;
            if (paid) tookTime = true;
        }
    }

    if (pay_done && shkp.mpeaceful !== false && paid) {
        if (!muteshk(shkp)) {
            await verbalize("Thank you for shopping in %s %s%s",
                sSuffix(shkname(shkp)),
                shtypes[Number(shkp.shoptype || SHOPBASE) - SHOPBASE]?.name || "shop",
                !shkp.surcharge ? "!" : ".");
        } else {
            await pline("%s nods%s at you for shopping in %s %s%s",
                Shknam(shkp),
                !shkp.surcharge ? " appreciatively" : "",
                mhis(shkp),
                shtypes[Number(shkp.shoptype || SHOPBASE) - SHOPBASE]?.name || "shop",
                !shkp.surcharge ? "!" : ".");
        }
    }

    return (paid || tookTime) ? 1 : 0;
}

