async function dosit(player, map, display) {
    const sit_message = "sit on the %s.";
    const px = player.x, py = player.y;
    const trap = map.trapAt ? map.trapAt(px, py) : null;
    const loc = map.at(px, py);
    const typ = loc ? loc.typ : 0;

    if (player.usteed) {
        await You("are already sitting on %s.", mon_nam(player.usteed));
        return 0; // ECMD_OK
    }

    // Un-hide from ceiling
    const playerType = player.type || {};
    if (player.uundetected && is_hider(playerType)
        && (player.umonnum || 0) !== PM_TRAPPER) {
        player.uundetected = false;
    }

    if (player.levitating || player.uswallow) {
        // can't reach floor
        if (player.uswallow)
            await pline("There are no seats in here!");
        else if (player.levitating)
            await You("tumble in place.");
        else
            await You("are sitting on air.");
        return 0; // ECMD_OK
    } else if (player.ustuck && !sticks(playerType)) {
        if (is_humanoid(player.ustuck.data || {}))
            await pline("%s won't offer a lap.", Monnam(player.ustuck));
        else
            await pline("%s has no lap.", Monnam(player.ustuck));
        return 0; // ECMD_OK
    } else if (is_pool(px, py, map) && !player.underwater) {
        // water sitting — fall through to in_water
        await You("sit in the water.");
        if (!rn2(10) && player.armor)
            ; // TODO: water_damage(uarm, "armor", TRUE)
        if (!rn2(10) && player.boots)
            ; // TODO: water_damage(uarmf, "armor", TRUE)
        return 1; // ECMD_TIME
    }

    // Check for objects on the tile
    const objs = map.objectsAt ? map.objectsAt(px, py) : [];
    if (objs.length > 0 && !(trap && (trap.ttyp === PIT || trap.ttyp === SPIKED_PIT))) {
        // Not teetering at a pit — sit on objects
        const obj = objs[0]; // top object
        if (playerType.mlet === S_DRAGON && obj.oclass === COIN_CLASS) {
            await You("coil up around your hoard.");
        } else {
            const objLabel = the(xname(obj));
            if (slithy(playerType))
                await You("coil up around %s.", objLabel);
            else
                await You("sit on %s.", objLabel);
            if (!obj.otyp) {
                // generic
            } else {
                await pline("It's not very comfortable...");
            }
        }
    } else if (trap || (player.utrap && (player.utraptype || 0) >= TT_LAVA)) {
        if (player.utrap) {
            await exercise(player, A_WIS, false);
            if (player.utraptype === TT_BEARTRAP) { // TT_BEARTRAP
                await You_cant("sit down with your foot in the bear trap.");
                player.utrap++;
            } else if (player.utraptype === TT_PIT) { // TT_PIT
                if (trap && trap.ttyp === SPIKED_PIT) {
                    await You("sit down on a spike.  Ouch!");
                    // RNG parity: rn2(2) for half phys damage
                    const dmg = player.half_physical_damage ? rn2(2) : 1;
                    await losehp(dmg, "sitting on an iron spike", 0, player, _gstate?.display, _gstate);
                    await exercise(player, A_STR, false);
                } else {
                    await You("sit down in the pit.");
                }
                player.utrap += rn2(5);
            } else if (player.utraptype === TT_WEB) { // TT_WEB
                await You("sit in the spider web and get entangled further!");
                player.utrap += rn1(10, 5);
            } else if (player.utraptype === TT_LAVA) { // TT_LAVA
                await You("sit in the lava!");
                player.utrap += rnd(4);
                const dmg = c_d(2, 10);
                await losehp(dmg, "sitting in lava", 0, player, _gstate?.display, _gstate);
            } else if (player.utraptype === TT_INFLOOR || player.utraptype === TT_BURIEDBALL) {
                // TT_INFLOOR or TT_BURIEDBALL
                await You_cant("maneuver to sit!");
                player.utrap++;
            }
        } else {
            await You(player.flying ? "land." : "sit down.");
            // TODO: dotrap(trap, VIASITTING)
        }
    } else if (player.underwater) {
        await You("sit down on the muddy bottom.");
    } else if (typ === SINK) {
        await You(sit_message, "sink");
        await Your("rump gets wet.");
    } else if (typ === ALTAR) {
        await You(sit_message, "altar");
        // TODO: altar_wrath(px, py)
    } else if (typ === GRAVE) {
        await You(sit_message, "grave");
    } else if (typ === STAIRS) {
        await You(sit_message, "stairs");
    } else if (typ === LADDER) {
        await You(sit_message, "ladder");
    } else if (is_lava(px, py, map)) {
        await You(sit_message, "lava");
        await burn_away_slime();
        if (likes_lava(playerType)) {
            await pline_The("lava feels warm.");
            return 1; // ECMD_TIME
        }
        await pline_The("lava burns you!");
        {
            const dmg = c_d(player.hasProp(FIRE_RES) ? 2 : 10, 10);
            await losehp(dmg, "sitting on lava", 0, player, _gstate?.display, _gstate);
        }
    } else if (is_ice(px, py, map)) {
        await You(sit_message, "ice");
        if (!player.hasProp(COLD_RES))
            await pline_The("ice feels cold.");
    } else if (typ === DRAWBRIDGE_DOWN) {
        await You(sit_message, "drawbridge");
    } else if (typ === THRONE) {
        await You(sit_message, "throne");
        await throne_sit_effect(player, map, display);
    } else if (lays_eggs(playerType)) {
        return await lay_an_egg(player, map, display);
    } else {
        // C ref: sit.c:558 — uses surface(u.ux, u.uy) for "floor"/"ground"/etc.
        // Inline the common cases to avoid surface()'s IS_AIR dependency issue.
        const surfName = (typ === ROOM) ? "floor" : "ground";
        await pline("Having fun sitting on the %s?", surfName);
    }
    return 1; // ECMD_TIME
}

async function dosounds(game) {
    // C ref: if (Deaf || !flags.acoustics || u.uswallow || Underwater) return;
    if ((game.u || game.u)?.deaf) return;
    if (game.flags && game.flags.acoustics === false) return;
    if ((game.u || game.u)?.uswallow) return;
    if ((game.u || game.u)?.underwater) return;

    const hallu = (game.u || game.u)?.hallucinating ? 1 : 0;
    const f = (game.map || game.map).flags || {};
    const map = (game.map || game.map);

    // --- Fountains (rn2(400)) — does NOT return early ---
    if (f.nfountains && !rn2(400)) {
        const fountain_msg = [
            'bubbling water.',
            'water falling on coins.',
            'the splashing of a naiad.',
            'a soda fountain!',
        ];
        await game.display.putstr_message(`You hear ${fountain_msg[rn2(3) + hallu]}`);
    }

    // --- Sinks (rn2(300)) — does NOT return early ---
    if (f.nsinks && !rn2(300)) {
        const sink_msg = [
            'a slow drip.',
            'a gurgling noise.',
            'dishes being washed!',
        ];
        await game.display.putstr_message(`You hear ${sink_msg[rn2(2) + hallu]}`);
    }

    // --- Court / throne room (rn2(200)) ---
    if (f.has_court && !rn2(200)) {
        // C: get_iter_mons(throne_mon_sound) — iterate all monsters
        for (const mtmp of map.monsters) {
            if (mtmp.dead) continue;
            if (await throne_mon_sound(mtmp, hallu, game)) return;
        }
    }

    // --- Swamp (rn2(200)) ---
    if (f.has_swamp && !rn2(200)) {
        const swamp_msg = [
            'You hear mosquitoes!',
            'You smell marsh gas!',
            'You hear Donald Duck!',
        ];
        await game.display.putstr_message(swamp_msg[rn2(2) + hallu]);
        return;
    }

    // --- Vault (rn2(200)) ---
    if (f.has_vault && !rn2(200)) {
        // C sounds.c:244: if (gd_sound()) — skip sounds if vault occupied or guard exists
        // vault_occupied returns null for "not in vault", room char for "in vault"
        const player = game.u || game.u;
        const vaultOcc = vault_occupied(player?.urooms || '', map);
        const gdSound = !(vaultOcc || findgd(map, player));
        if (gdSound)
        switch (rn2(2) + hallu) {
        case 1:
            // C: checks gold_in_vault and vault_occupied; simplified here
            await game.display.putstr_message('You hear someone counting gold coins.');
            break;
        case 0:
            await game.display.putstr_message('You hear the footsteps of a guard on patrol.');
            break;
        case 2:
            await game.display.putstr_message('You hear Ebenezer Scrooge!');
            break;
        }
        return;
    }

    // --- Beehive (rn2(200)) ---
    if (f.has_beehive && !rn2(200)) {
        for (const mtmp of map.monsters) {
            if (mtmp.dead) continue;
            if (await beehive_mon_sound(mtmp, hallu, game)) return;
        }
    }

    // --- Morgue (rn2(200)) ---
    if (f.has_morgue && !rn2(200)) {
        for (const mtmp of map.monsters) {
            if (mtmp.dead) continue;
            if (await morgue_mon_sound(mtmp, hallu, game)) return;
        }
    }

    // --- Barracks (rn2(200)) ---
    if (f.has_barracks && !rn2(200)) {
        const barracks_msg = [
            'blades being honed.',
            'loud snoring.',
            'dice being thrown.',
            'General MacArthur!',
        ];
        let count = 0;
        for (const mtmp of map.monsters) {
            if (mtmp.dead) continue;
            if (is_mercenary(mtmp.data || mtmp.type)
                && mon_in_room(mtmp, BARRACKS, map)
                && (mtmp.msleeping || ++count > 5)) {
                await game.display.putstr_message(`You hear ${barracks_msg[rn2(3) + hallu]}`);
                return;
            }
        }
    }

    // --- Zoo (rn2(200)) ---
    if (f.has_zoo && !rn2(200)) {
        for (const mtmp of map.monsters) {
            if (mtmp.dead) continue;
            if (await zoo_mon_sound(mtmp, hallu, game)) return;
        }
    }

    // --- Shop (rn2(200)) ---
    if (f.has_shop && !rn2(200)) {
        // C: search_special(ANY_SHOP), tended_shop(sroom), ushops check
        // Simplified: check if any shopkeeper is alive & player not in shop
        const tendedShop = (map.monsters || []).some(
            (m) => m && !m.dead && m.isshk
        );
        const playerInShop = (() => {
            const loc = map.at?.((game.u || game.u).x, (game.u || game.u).y);
            if (!loc || !Number.isFinite(loc.roomno)) return false;
            const ridx = loc.roomno - ROOMOFFSET;
            const room = map.rooms?.[ridx];
            return !!(room && Number.isFinite(room.rtype)
                      && room.rtype >= SHOPBASE);
        })();
        if (tendedShop && !playerInShop) {
            const shop_msg = [
                'someone cursing shoplifters.',
                'the chime of a cash register.',
                'Neiman and Marcus arguing!',
            ];
            await game.display.putstr_message(`You hear ${shop_msg[rn2(2) + hallu]}`);
            // C: noisy_shop(sroom) — not ported, skip
        }
        return;
    }

    // --- Leprechaun hall (rn2(200)) ---
    // C: has_leprehall check but no get_iter_mons — just returns.
    // No messages in C either (the feature flag exists but dosounds
    // doesn't print anything for leprehall; it just falls through).
    // Actually looking at C more carefully: leprehall is NOT in dosounds.
    // The comment in the stub was wrong. C goes: court→swamp→vault→
    //   beehive→morgue→barracks→zoo→shop→temple→oracle.
    // There is no leprehall check in C's dosounds(). Skip it.

    // --- Temple (rn2(200)) ---
    // C sounds.c:330: if (has_temple && !rn2(200) && !(Is_astralevel || Is_sanctum))
    // Is_astralevel/Is_sanctum are stubs (false) so guard is a no-op for now.
    if (f.has_temple && !rn2(200) && !(f.is_astral || f.is_sanctum)) {
        for (const mtmp of map.monsters) {
            if (mtmp.dead) continue;
            if (await temple_priest_sound(mtmp, hallu, game)) return;
        }
    }

    // --- Oracle (rn2(400)) ---
    // C: if (Is_oracle_level(&u.uz) && !rn2(400))
    if (f.is_oracle_level && !rn2(400)) {
        for (const mtmp of map.monsters) {
            if (mtmp.dead) continue;
            if (await oracle_sound(mtmp, hallu, game)) return;
        }
    }
}

