async function select_menu(win, how, opts = null) {
    const w = wins[win];
    if (!w) return null;
    w.how = how;
    const displayRows = Number.isInteger(_display?.rows) ? _display.rows : 24;

    // C tty parity: menu selection windows do not render over a pending
    // topline --More-- page. Resolve that boundary first, then paint the menu.
    if (ttyDisplay.toplin === TOPLINE_NON_EMPTY || _display?.messageNeedsMore) {
        await more(_display, { site: 'windows.select_menu.pre-menu', forceVisual: true });
        if (_display?.clearRow) _display.clearRow(0);
        ttyDisplay.toplin = TOPLINE_EMPTY;
        if (_display) {
            _display.messageNeedsMore = false;
            _display.topMessage = null;
        }
    }

    const renderMenu = (selected = null, currentPage = 0) => {
        const builtLines = buildMenuLines(w, selected, how);
        const paged = (how === PICK_ANY)
            ? paginateMenuLines(builtLines, displayRows, currentPage)
            : { lines: builtLines, totalPages: 1, currentPage: 0 };
        const lines = paged.lines;
        if (_display) {
            let offx = 0;
            const isPickupMenu = typeof w.prompt === 'string' && w.prompt === 'Pick up what?';
            if (typeof _display.renderOverlayMenu === 'function') {
                offx = isPickupMenu
                    ? (_display.renderOverlayMenu(lines, { capHalf: true }) || 0)
                    : (_display.renderOverlayMenu(lines) || 0);
            } else if (typeof _display.renderChargenMenu === 'function') {
                offx = _display.renderChargenMenu(lines, false) || 0;
            }
            if (typeof _display.setCursor === 'function') {
                const lastRow = Math.max(0, lines.length - 1);
                const lastLine = lines[lastRow] || '';
                const col = Math.min((_display.cols || 80) - 1, offx + lastLine.length + 1);
                _display.setCursor(col, lastRow);
            }
        }
        return paged;
    };
    let currentPage = 0;
    let paged = renderMenu(null, currentPage);

    if (how === PICK_NONE) {
        await _nhgetch();
        return null;
    }

    if (how === PICK_ONE) {
        const preselectedItem = w.mlist.find((item) => (
            item?.id !== null
            && !!(item.itemflags & MENU_ITEMFLAGS_SELECTED)
        )) || null;
        const acceptPreselectedOnSpace = !!opts?.acceptPreselectedOnSpace;
        while (true) {
            const ch = await _nhgetch();
            // ESC, 'q' — cancel
            if (ch === 27 || ch === 'q'.charCodeAt(0)) {
                return null;
            }
            // Optional C-faithful mode for menus with a preselected entry.
            if (ch === ' '.charCodeAt(0) || ch === 13 || ch === 10) {
                if (!acceptPreselectedOnSpace) return null;
                if (!preselectedItem) return null;
                return [{ identifier: preselectedItem.id, count: -1 }];
            }
            const item = w.mlist.find(i => i.ch === ch);
            if (item) return [{ identifier: item.id, count: -1 }];
        }
    }

    if (how === PICK_ANY) {
        const selected = new Set();
        const counts = new Map(); // C ref: item-specific counts from digit prefix
        let countPrefix = 0;     // Accumulates digit prefix for next item selection
        // C ref: tty_select_menu — pre-selected items start toggled on
        for (const item of w.mlist) {
            if (item.ch && (item.itemflags & MENU_ITEMFLAGS_SELECTED)) {
                selected.add(item.ch);
            }
        }

        // C ref: wintty.c process_menu_window — item letters only select items
        // on the current page. Items on other pages are rejected. Group
        // accelerators (gch) toggle across ALL pages.
        // Compute which mlist items are visible on the current page.
        const headerLines = (w.prompt ? 2 : 1); // prompt + blank, or just blank
        const contentRows = Math.max(1, displayRows - 1); // 1 row for page indicator
        const totalContentLines = headerLines + w.mlist.length;
        const totalPages = Math.max(1, Math.ceil(totalContentLines / contentRows));
        const itemsOnPage = (page) => {
            const normPage = Math.max(0, Math.min(page, totalPages - 1));
            const start = normPage * contentRows;
            // mlist[i] maps to content line (headerLines + i)
            const firstItem = Math.max(0, start - headerLines);
            const lastItem = Math.min(w.mlist.length, start + contentRows - headerLines);
            return { firstItem, lastItem };
        };

        // C ref: wintty.c — menus are paged. Space advances to next page.
        // On the last page, space confirms selections (or cancels if none).
        // C's page_lines is typically LI-4 = 20 lines per page.
        while (true) {
            const ch = normalizeMenuCommand(await _nhgetch());
            if (ch === 13 || ch === 10) {
                // Enter — confirm selection (return [] if nothing selected)
                const result = [];
                for (const item of w.mlist) {
                    if (item.ch && selected.has(item.ch)) {
                        const cnt = counts.has(item.ch) ? counts.get(item.ch) : -1;
                        result.push({ identifier: item.id, count: cnt });
                    }
                }
                return result.length ? result : null;
            }
            if (ch === 27 || ch === 'q'.charCodeAt(0)) return null;
            if (ch === '.'.charCodeAt(0)) {
                for (const item of w.mlist) if (item.ch) selected.add(item.ch);
            } else if (ch === '-'.charCodeAt(0)) {
                selected.clear();
            } else {
                // C ref: wintty.c — group accelerators toggle ALL items with
                // that group across ALL pages.
                const grouped = w.mlist.filter((item) => item.gch === ch && item.ch);
                if (grouped.length > 0) {
                    for (const item of grouped) selected.add(item.ch);
                } else if (ch === ' '.charCodeAt(0)) {
                    // C ref: wintty.c — space pages forward; on last page, closes menu.
                    if (currentPage < paged.totalPages - 1) {
                        currentPage++;
                    } else {
                        const result = [];
                        for (const item of w.mlist) {
                            if (item.ch && selected.has(item.ch)) {
                                const cnt = counts.has(item.ch) ? counts.get(item.ch) : -1;
                                result.push({ identifier: item.id, count: cnt });
                            }
                        }
                        return result.length ? result : null;
                    }
                } else if (ch >= 48 && ch <= 57) {
                    // C ref: wintty.c — digit keys accumulate count prefix
                    countPrefix = countPrefix * 10 + (ch - 48);
                    if (countPrefix > 999999) countPrefix = 999999;
                    continue; // don't reset countPrefix or re-render
                } else {
                    // C ref: wintty.c — item letters only match items on the
                    // CURRENT page. Items on other pages are silently rejected.
                    const { firstItem, lastItem } = itemsOnPage(currentPage);
                    let matched = null;
                    for (let idx = firstItem; idx < lastItem; idx++) {
                        if (w.mlist[idx].ch === ch) { matched = w.mlist[idx]; break; }
                    }
                    if (matched && matched.ch) {
                        if (selected.has(matched.ch)) {
                            selected.delete(matched.ch);
                            counts.delete(matched.ch);
                        } else {
                            selected.add(matched.ch);
                            if (countPrefix > 0) {
                                counts.set(matched.ch, countPrefix);
                            }
                        }
                    }
                    countPrefix = 0;
                }
            }
            paged = renderMenu(selected, currentPage);
        }
    }

    return null;
}

