async function zhitm(mon, type, nd, map, player) {
    const mdat = mons[mon.mndx];
    let tmp = 0;
    const damgtype = zaptype(type) % 10;
    const spellcaster = is_hero_spell(type);

    switch (damgtype) {
    case ZT_MAGIC_MISSILE:
        // C: resists_magm(mon) || defended(mon, AD_MAGM)
        if (resists_magm(mon)) {
            break;
        }
        tmp = c_d(nd, 6);
        if (spellcaster)
            tmp = spell_damage_bonus(tmp, player);
        break;
    case ZT_FIRE:
        if (mdat.mresists & MR_FIRE) {
            break; // resistant — no damage
        }
        tmp = c_d(nd, 6);
        if (spellcaster)
            tmp = spell_damage_bonus(tmp, player);
        if (mdat.mresists & MR_COLD) tmp += 7; // cold-resistant takes extra fire
        // C ref: if (burnarmor(mtmp)) { if (!rn2(3)) destroy_items(mtmp, AD_FIRE, tmp); }
        if (burnarmor(mon)) {
            if (!rn2(3)) {
                await destroy_items_rng_only(mon, AD_FIRE, tmp, null);
            }
        }
        break;
    case ZT_COLD:
        if (mdat.mresists & MR_COLD) {
            break; // resistant
        }
        tmp = c_d(nd, 6);
        if (spellcaster)
            tmp = spell_damage_bonus(tmp, player);
        if (mdat.mresists & MR_FIRE) tmp += c_d(nd, 3); // fire-resistant takes extra cold
        if (!rn2(3)) {
            await destroy_items_rng_only(mon, AD_COLD, tmp, null);
        }
        break;
    case ZT_SLEEP:
        tmp = 0;
        sleep_monst(mon, c_d(nd, 25), type === ZT_WAND(ZT_SLEEP) ? WAND_CLASS : 0);
        break;
    case ZT_DEATH:
        if (Math.abs(type) !== ZT_BREATH(ZT_DEATH)) {
            // death ray (not disintegration)
            if (mon.mndx === PM_DEATH) {
                // PM_DEATH absorbs death ray, heals
                healmon(mon, Math.floor(mon.mhpmax * 3 / 2), Math.floor(mon.mhpmax / 2));
                if (mon.mhpmax >= MAGIC_COOKIE)
                    mon.mhpmax = MAGIC_COOKIE - 1;
                tmp = 0;
                break;
            }
            if (nonliving(mdat) || is_demon(mdat)) {
                break; // immune
            }
            type = -1; // no saving throw
        } else {
            // disintegration breath
            if (mdat.mresists & MR_DISINT) {
                break; // resistant
            }
            // No armor handling — simplified; full kill
            tmp = MAGIC_COOKIE;
            type = -1;
            break;
        }
        tmp = mon.mhp + 1;
        break;
    case ZT_LIGHTNING:
        tmp = c_d(nd, 6);
        if (spellcaster)
            tmp = spell_damage_bonus(tmp, player);
        if (mdat.mresists & MR_ELEC) {
            tmp = 0; // resistant, but still rolls damage for RNG
        }
        // blindness from lightning
        if (!resists_blnd(mon) && nd > 2) {
            const rnd_tmp = rnd(50);
            mon.mcansee = 0;
            if (((mon.mblinded || 0) + rnd_tmp) > 127)
                mon.mblinded = 127;
            else
                mon.mblinded = (mon.mblinded || 0) + rnd_tmp;
        }
        if (!rn2(3)) {
            await destroy_items_rng_only(mon, AD_ELEC, tmp, null);
        }
        break;
    case ZT_POISON_GAS:
        if (mdat.mresists & MR_POISON) {
            break;
        }
        tmp = c_d(nd, 6);
        break;
    case ZT_ACID:
        if (mdat.mresists & MR_ACID) {
            break;
        }
        tmp = c_d(nd, 6);
        if (!rn2(6)) { /* acid_damage(MON_WEP) */ }
        if (!rn2(6)) { /* erode_armor */ }
        break;
    }

    // C ref: zap.c:4375-4377 — resist halves damage
    if (tmp > 0 && type >= 0 &&
        resist(mon, type < ZT_SPELL(0) ? WAND_CLASS : 0)) {
        tmp = Math.floor(tmp / 2);
    }
    if (tmp < 0) tmp = 0;

    mon.mhp -= tmp;
    return tmp;
}

