async function bhitm(mon, otmp, map, player) {
  if (!mon || !otmp) return 0;
  let ret = 0;
  let wake = true;
  const otyp = otmp.otyp;

  switch (otyp) {
  case WAN_STRIKING:
  case SPE_FORCE_BOLT: {
    // C ref: zap.c:186-215 bhitm WAN_STRIKING/SPE_FORCE_BOLT
    const zap_type_text = otyp === WAN_STRIKING ? 'wand' : 'spell';
    const mac = find_mac ? find_mac(mon) : (mon.mac || 10);
    if (resists_magm(mon)) {
      // C ref: zap.c:194-199 — magic resistance blocks entirely
      // shieldeff + "Boing!" — no rnd(20), no damage, no resist() RNG
      await pline("Boing!");
    } else if (player?.uswallow || rnd(20) < 10 + mac) {
      let dmg = c_d(2, 12);
      if (otyp === SPE_FORCE_BOLT) {
        dmg = spell_damage_bonus(dmg, player);
      }
      await hit(zap_type_text, mon, exclam(dmg));
      // C ref: zap.c:209 — resist() applies damage (halved if resisted)
      if (resist(mon, otmp.oclass)) {
        dmg = Math.floor((dmg + 1) / 2);
      }
      mon.mhp -= dmg;
      // C ref: zap.c:6118-6125 — C's resist() applies damage and checks death
      if (mon.mhp <= 0) {
        await killed(mon, map, player);
      }
    } else {
      await miss(zap_type_text, mon);
    }
    break;
  }
  case WAN_SLOW_MONSTER:
  case SPE_SLOW_MONSTER:
    if (!resist(mon, otmp.oclass)) {
      mon_adjust_speed(mon, -1, otmp);
    }
    break;
  case WAN_SPEED_MONSTER:
    if (!resist(mon, otmp.oclass)) {
      mon_adjust_speed(mon, 1, otmp);
    }
    break;
  case WAN_UNDEAD_TURNING:
  case SPE_TURN_UNDEAD: {
    wake = false;
    const mdat = mons[mon.mndx];
    if (is_undead(mdat)) {
      wake = true;
      let dmg = rnd(8);
      if (otyp === SPE_TURN_UNDEAD) {
        dmg = spell_damage_bonus(dmg, player);
      }
      // C ref: zap.c:255 — resist() applies dmg (halved if resisted),
      // then monflee only if NOT resisted
      const resisted = resist(mon, otmp.oclass);
      if (resisted) {
        dmg = Math.floor((dmg + 1) / 2);
      }
      mon.mhp -= dmg;
      // C ref: zap.c:6118-6125 — C's resist() applies damage and checks death
      if (mon.mhp <= 0) {
        await killed(mon, map, player);
      } else if (!resisted) {
        await monflee(mon, 0, false, true);
      }
    }
    break;
  }
  case WAN_POLYMORPH:
  case SPE_POLYMORPH:
  case POT_POLYMORPH:
    // C: resists_magm gate (no RNG) before resist() call
    if (resists_magm(mon)) {
      // C ref: zap.c:268 — magic resistance blocks polymorph, no RNG consumed
    } else if (!resist(mon, otmp.oclass)) {
      // C: rn2(25) only for natural (non-shapechanger) monsters
      const NON_PM = -1;
      if ((mon.cham === undefined || mon.cham === NON_PM) && !rn2(25)) {
        // system shock — kills the monster
        mon.mhp = 0;
      }
      // else: would call newcham() — simplified, no actual poly
    }
    break;
  case WAN_CANCELLATION:
  case SPE_CANCELLATION:
    cancel_monst(mon, otmp, true, true, false);
    break;
  case WAN_TELEPORTATION:
  case SPE_TELEPORT_AWAY:
    // C: no resist() check — just teleport directly
    await u_teleport_mon(mon, true, map, player, null, null);
    break;
  case WAN_MAKE_INVISIBLE:
    mon_set_minvis(mon, map);
    break;
  case WAN_LOCKING:
  case SPE_WIZARD_LOCK:
    wake = false;
    break;
  case WAN_PROBING:
    wake = false;
    await probe_monster(mon);
    break;
  case WAN_OPENING:
  case SPE_KNOCK:
    wake = false;
    break;
  case SPE_HEALING:
  case SPE_EXTRA_HEALING: {
    const healamt = c_d(6, otyp === SPE_EXTRA_HEALING ? 8 : 4);
    wake = false;
    if (mon.mndx !== PM_DEATH - 1) { // not Pestilence
      healmon(mon, healamt, 0);
    } else {
      // C ref: zap.c:468 — Pestilence always resists; damage = (healamt/2 + 1) / 2
      let pdmg = Math.floor(healamt / 2);
      if (resist(mon, otmp.oclass)) {
        pdmg = Math.floor((pdmg + 1) / 2);
      }
      mon.mhp -= pdmg;
      // C ref: zap.c:6118-6125 — C's resist() applies damage and checks death
      if (mon.mhp <= 0) {
        await killed(mon, map, player);
      }
    }
    break;
  }
  case WAN_LIGHT:
    // broken wand light effect — simplified
    break;
  case WAN_SLEEP:
    // broken wand sleep effect
    if (sleep_monst(mon, c_d(1 + (otmp.spe || 0), 12), WAND_CLASS))
      slept_monst(mon);
    break;
  case SPE_DRAIN_LIFE: {
    // C ref: zap.c:519-541 — drain life spell
    let dmg = monhp_per_lvl(mon);
    dmg = spell_damage_bonus(dmg, player);
    if (resists_drli(mon)) {
      // C: shieldeff_mon — drain resistance blocks entirely, no resist() RNG
    } else {
      // C: resist() applies dmg (halved if resisted), then additional drain
      const resisted_drain = resist(mon, otmp.oclass);
      if (resisted_drain) {
        dmg = Math.floor((dmg + 1) / 2);
      }
      mon.mhp -= dmg;
      // C ref: zap.c:6118-6125 — C's resist() applies damage and checks death
      if (mon.mhp <= 0) {
        await killed(mon, map, player);
      } else if (!resisted_drain) {
        mon.mhp -= dmg;
        mon.mhpmax -= dmg;
        if (mon.mhp <= 0 || mon.mhpmax <= 0 || mon.m_lev < 1) {
          await killed(mon, map, player);
        } else {
          mon.m_lev--;
        }
      }
    }
    break;
  }
  default:
    ret = 0;
    break;
  }

  // Wake the monster (if appropriate)
  if (wake && mon.mhp > 0) {
    if (mon.msleeping) {
        mon.msleeping = 0;
        mon.msleeping = 0;
    }
    if (mon.mcanmove === false || mon.mcanmove === 0) { mon.mcanmove = 1; mon.mfrozen = 0; }
  }

  return ret;
}

