import {
  GOLD, POTION, SCROLL, FOOD, WEAPON, ARMOR, RING, AMULET, STICK,
  FLOOR, PASSAGE, LINES, S_SCARE, CALLABLE, ESCAPE, MAXPACK, ISFOUND,
