function loadGameState(g) {
  const raw = localStorage.getItem(SAVE_KEY);
  if (!raw) return false;

  let s;
  try {
    s = JSON.parse(raw);
  } catch (e) {
    return false;
  }

  setRngSeed(s.rngSeed);

  // Player
  g.player.t_pos.x = s.player.t_pos.x;
  g.player.t_pos.y = s.player.t_pos.y;
  g.player.t_turn = s.player.t_turn;
  g.player.t_type = s.player.t_type;
  g.player.t_disguise = s.player.t_disguise;
  g.player.t_oldch = s.player.t_oldch;
  g.player.t_flags = s.player.t_flags;
  g.player.t_stats.s_str.st_str = s.player.t_stats.s_str.st_str;
  g.player.t_stats.s_str.st_add = s.player.t_stats.s_str.st_add;
  g.player.t_stats.s_exp = s.player.t_stats.s_exp;
  g.player.t_stats.s_lvl = s.player.t_stats.s_lvl;
  g.player.t_stats.s_arm = s.player.t_stats.s_arm;
  g.player.t_stats.s_hpt = s.player.t_stats.s_hpt;
  g.player.t_stats.s_dmg = s.player.t_stats.s_dmg;

  Object.assign(g.max_stats, {
    s_str: { ...s.max_stats.s_str },
    s_exp: s.max_stats.s_exp,
    s_lvl: s.max_stats.s_lvl,
    s_arm: s.max_stats.s_arm,
    s_hpt: s.max_stats.s_hpt,
    s_dmg: s.max_stats.s_dmg,
  });

  g.level = s.level;
  g.max_level = s.max_level;

  for (let i = 0; i < s.rooms.length && i < g.rooms.length; i++) {
    const r = s.rooms[i], gr = g.rooms[i];
    gr.r_pos = { ...r.r_pos };
    gr.r_max = { ...r.r_max };
    gr.r_gold = { ...r.r_gold };
    gr.r_goldval = r.r_goldval;
    gr.r_flags = r.r_flags;
    gr.r_nexits = r.r_nexits;
    gr.r_exit = r.r_exit.map(e => ({ ...e }));
  }

  g.ntraps = s.ntraps;
  for (let i = 0; i < s.traps.length && i < g.traps.length; i++) {
    g.traps[i] = { tr_pos: { ...s.traps[i].tr_pos }, tr_type: s.traps[i].tr_type, tr_flags: s.traps[i].tr_flags };
  }

  g.lvl_obj = deserializeList(s.lvl_obj, deserializeItem);
  g.mlist = deserializeList(s.mlist, d => deserializeMonster(d, g.player.t_pos));

  // Pack + equipment back-references
  g.pack = deserializeList(s.pack, deserializeItem);
  const packNodes = packListToArray(g.pack);
  g.cur_weapon = s.cur_weapon_idx >= 0 && packNodes[s.cur_weapon_idx] ? packNodes[s.cur_weapon_idx].l_data : null;
  g.cur_armor  = s.cur_armor_idx  >= 0 && packNodes[s.cur_armor_idx]  ? packNodes[s.cur_armor_idx].l_data  : null;
  g.cur_ring[0] = s.cur_ring_idx[0] >= 0 && packNodes[s.cur_ring_idx[0]] ? packNodes[s.cur_ring_idx[0]].l_data : null;
  g.cur_ring[1] = s.cur_ring_idx[1] >= 0 && packNodes[s.cur_ring_idx[1]] ? packNodes[s.cur_ring_idx[1]].l_data : null;
  // Also sync player.t_pack to pack (some code accesses both)
  g.player.t_pack = g.pack;

  // Numeric stats
  const numFields = ['purse','mpos','no_move','no_command','inpack','max_hp','total',
    'no_food','count','fung_hit','quiet','food_left','group','hungry_state',
    'lastscore','dnum','seed','take'];
  for (const f of numFields) if (s[f] !== undefined) g[f] = s[f];

  // Booleans
  const boolFields = ['running','wizard','after','notify','fight_flush','terse','door_stop',
    'jump','slow_invent','firstmove','askme','waswizard','amulet','in_shell'];
  for (const f of boolFields) if (s[f] !== undefined) g[f] = s[f];

  // Strings
  const strFields = ['prbuf','runch','huh','whoami','fruit','file_name'];
  for (const f of strFields) if (s[f] !== undefined) g[f] = s[f];

  g.oldpos = { ...s.oldpos };
  g.delta = { ...s.delta };

  // Monster table
  if (s.monsters) {
    g.monsters = s.monsters.map(m => ({
      m_name: m.m_name,
      m_carry: m.m_carry,
      m_flags: m.m_flags,
      m_stats: {
        s_str: { st_str: m.m_stats.s_str.st_str, st_add: m.m_stats.s_str.st_add },
        s_exp: m.m_stats.s_exp,
        s_lvl: m.m_stats.s_lvl,
        s_arm: m.m_stats.s_arm,
        s_hpt: m.m_stats.s_hpt,
        s_dmg: m.m_stats.s_dmg,
      },
    }));
  }

  if (s.s_names) g.s_names = s.s_names;
  if (s.p_colors) g.p_colors = s.p_colors;
  if (s.r_stones) g.r_stones = s.r_stones;
  if (s.ws_made) g.ws_made = s.ws_made;
  if (s.ws_type) g.ws_type = s.ws_type;

  if (s.s_know) g.s_know = s.s_know;
  if (s.p_know) g.p_know = s.p_know;
  if (s.r_know) g.r_know = s.r_know;
  if (s.ws_know) g.ws_know = s.ws_know;
  if (s.s_guess) g.s_guess = s.s_guess;
  if (s.p_guess) g.p_guess = s.p_guess;
  if (s.r_guess) g.r_guess = s.r_guess;
  if (s.ws_guess) g.ws_guess = s.ws_guess;

  if (s.lvl_mons) g.lvl_mons = s.lvl_mons;
  if (s.wand_mons) g.wand_mons = s.wand_mons;

  // Daemon/fuse system
  for (let i = 0; i < s.d_list.length && i < g.d_list.length; i++) {
    const d = s.d_list[i];
    g.d_list[i] = {
      d_type: d.d_type,
      d_func: deserializeDaemonFn(d.d_func),
      d_arg: d.d_arg,
      d_time: d.d_time,
    };
  }

  // Screens
  if (s.stdscr) g.stdscr = deserializeScreen(s.stdscr);
  if (s.cw) g.cw = deserializeScreen(s.cw);
  if (s.mw) g.mw = deserializeScreen(s.mw);

  return true;
}

async function read_scroll() {
  const g = game();
  const item = await _get_item('read', SCROLL);
  if (item === null) return;
  const obj = item.l_data;
  if (obj.o_type !== SCROLL) {
    if (!g.terse) await _msg('There is nothing on it to read');
    else await _msg('Nothing to read');
    return;
  }
  await _msg('As you read the scroll, it vanishes.');

  if (obj === g.cur_weapon) g.cur_weapon = null;

  switch (obj.o_which) {
    case S_CONFUSE:
      // Scroll of monster confusion — give player CANHUH
      await _msg('Your hands begin to glow red');
      g.player.t_flags |= CANHUH;
      break;

    case S_LIGHT: {
      g.s_know[S_LIGHT] = true;
      const rp = _roomin(g.player.t_pos);
      if (rp === null) {
        await _msg('The corridor glows and then fades');
      } else {
        _addmsg('The room is lit');
        if (!g.terse) _addmsg(' by a shimmering blue light.');
        await _endmsg();
        rp.r_flags &= ~ISDARK;
        _light(g.player.t_pos);
        mvwaddch(g.cw, g.player.t_pos.y, g.player.t_pos.x, PLAYER);
      }
      break;
    }

    case S_ARMOR:
      if (g.cur_armor !== null) {
        await _msg('Your armor glows faintly for a moment');
        g.cur_armor.o_ac--;
        g.cur_armor.o_flags &= ~ISCURSED;
      }
      break;

    case S_HOLD: {
      // Stop monsters within 2 spaces
      for (let x = g.player.t_pos.x - 2; x <= g.player.t_pos.x + 2; x++) {
        for (let y = g.player.t_pos.y - 2; y <= g.player.t_pos.y + 2; y++) {
          if (y > 0 && x > 0) {
            const mch = g.mw[y] && g.mw[y][x];
            if (mch >= 'A' && mch <= 'Z') {
              const mon = _find_mons(y, x);
              if (mon !== null) {
                const th = mon.l_data;
                th.t_flags &= ~ISRUN;
                th.t_flags |= ISHELD;
              }
            }
          }
        }
      }
      break;
    }

    case S_SLEEP:
      g.s_know[S_SLEEP] = true;
      await _msg('You fall asleep.');
      g.no_command += 4 + rnd(SLEEPTIME);
      break;

    case S_CREATE: {
      // Create a monster near player
      let appear = 0;
      let mp = null;
      for (let y = g.player.t_pos.y - 1; y <= g.player.t_pos.y + 1; y++) {
        for (let x = g.player.t_pos.x - 1; x <= g.player.t_pos.x + 1; x++) {
          if (y === g.player.t_pos.y && x === g.player.t_pos.x) continue;
          if (_step_ok(winat(y, x))) {
            if (rnd(++appear) === 0) mp = { y, x };
          }
        }
      }
      if (appear) {
        const titem = _new_item({
          o_type: ' ', o_pos: { x: 0, y: 0 }, o_count: 1, o_which: 0,
          o_hplus: 0, o_dplus: 0, o_flags: 0, o_group: 0,
          o_damage: '0d0', o_hurldmg: '0d0', o_ac: 11, o_launch: 100, o_charges: 0,
        });
        _new_monster(titem, _randmonster(false), mp);
      } else {
        await _msg('You hear a faint cry of anguish in the distance.');
      }
      break;
    }

    case S_IDENT:
      await _msg('This scroll is an identify scroll');
      g.s_know[S_IDENT] = true;
      await whatis(g);
      break;

    case S_MAP: {
      g.s_know[S_MAP] = true;
      await _msg('Oh, now this scroll has a map on it.');
      // Reveal structural cells (walls, floors, doors, passages) but not items
      for (let i = 0; i < LINES; i++) {
        for (let j = 0; j < COLS; j++) {
          const ch = g.stdscr[i][j];
          let reveal = false;
          switch (ch) {
            case '-': case '|': case '+': case '#': case '%': case ' ':
              reveal = true; break;
            case '&': // SECRETDOOR
              g.stdscr[i][j] = '+';
              g.cw[i][j] = '+';
              reveal = true; break;
          }
          if (reveal && g.cw[i][j] === ' ') g.cw[i][j] = ch;
        }
      }
      break;
    }

    case S_GFIND: {
      // Gold detection — show gold positions on hw overlay (matches C)
      let gtotal = 0;
      wclear(g.hw);
      for (let i = 0; i < MAXROOMS; i++) {
        gtotal += g.rooms[i].r_goldval;
        if (g.rooms[i].r_goldval !== 0 &&
            mvwinch(g.stdscr, g.rooms[i].r_gold.y, g.rooms[i].r_gold.x) === GOLD) {
          mvwaddch(g.hw, g.rooms[i].r_gold.y, g.rooms[i].r_gold.x, GOLD);
        }
      }
      if (gtotal) {
        g.s_know[S_GFIND] = true;
        await show_win(g.hw,
          'You begin to feel greedy and you sense gold.--More--');
      } else {
        await _msg('You begin to feel a pull downward');
      }
      break;
    }

    case S_TELEP: {
      const cur_room = _roomin(g.player.t_pos);
      const rm = _teleport();
      const new_room = _roomin(g.player.t_pos);
      if (cur_room !== new_room) g.s_know[S_TELEP] = true;
      break;
    }

    case S_ENCH:
      if (g.cur_weapon === null) {
        await _msg('You feel a strange sense of loss.');
      } else {
        g.cur_weapon.o_flags &= ~ISCURSED;
        if (rnd(100) > 50)
          g.cur_weapon.o_hplus++;
        else
          g.cur_weapon.o_dplus++;
        await _msg(`Your ${g.w_names[g.cur_weapon.o_which]} glows blue for a moment.`);
      }
      break;

    case S_SCARE:
      // Reading a scare monster scroll just produces laughter
      await _msg('You hear maniacal laughter in the distance.');
      break;

    case S_REMOVE:
      if (g.cur_armor !== null) g.cur_armor.o_flags &= ~ISCURSED;
      if (g.cur_weapon !== null) g.cur_weapon.o_flags &= ~ISCURSED;
      if (g.cur_ring[0] !== null) g.cur_ring[0].o_flags &= ~ISCURSED;
      if (g.cur_ring[1] !== null) g.cur_ring[1].o_flags &= ~ISCURSED;
      await _msg('You feel as if somebody is watching over you.');
      break;

    case S_AGGR:
      _aggravate();
      await _msg('You hear a high pitched humming noise.');
      break;

    case S_NOP:
      await _msg('This scroll seems to be blank.');
      break;

    case S_GENOCIDE:
      await _msg('You have been granted the boon of genocide');
      await _genocide();
      g.s_know[S_GENOCIDE] = true;
      break;

    default:
      await _msg('What a puzzling scroll!');
      return;
  }

  await _look(true);
  _status();

  if (g.s_know[obj.o_which] && g.s_guess[obj.o_which]) {
    g.s_guess[obj.o_which] = null;
  } else if (!g.s_know[obj.o_which] && g.askme && g.s_guess[obj.o_which] === null) {
    await _msg(g.terse ? 'Call it: ' : 'What do you want to call it? ');
    const buf = await get_str(_readchar);
    if (buf !== null) g.s_guess[obj.o_which] = buf;
  }

  // Consume the scroll
  g.inpack--;
  if (obj.o_count > 1) {
    obj.o_count--;
  } else {
    _detach(item);
    _discard(item);
  }
}

