import {
  S_CONFUSE, S_MAP, S_LIGHT, S_HOLD, S_SLEEP, S_ARMOR, S_IDENT,
  S_SCARE, S_GFIND, S_TELEP, S_ENCH, S_CREATE, S_REMOVE, S_AGGR,
  S_NOP, S_GENOCIDE,
